/* 令和5年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r05.committeeSessions.push(...[{"id":"r05-20231128-6","meetingId":"r05-cm11","date":"2023年11月28日","dateIso":"2023-11-28","committee":"区民委員会","time":"午前１０時０７分～午前１１時２５分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を36件抜き出しています。","topics":[{"id":"topic-01","title":"施設予約システムのリニューアルに伴う運用変更等","agenda":"施設予約システムのリニューアルに伴う運用変更等","exchanges":[{"speaker":"横山委員","kind":"質問","question":"ご説明、ありがとうございました。何点か伺っていきたいと思うのですけれども、オンラインクレジットカード決済を導入するということで、利便性が向上してすばらしいなと思っているところなのですけれども、こちらは手数料といいますか、ランニングコストみたいな部分が今までとこれからでどういった形で変わってくるのかというところを教えてください。","respondent":"横田情報推進課長","answer":"ある意味、機能の一つとしてこういうものができたということになります。続きまして、５月１３日から１４日ですが、システムのリプレースということで、最終的なデータ移行などを行いますので、そのときはシステムの利用停止ということを予定しております。","id":"exchange-001"},{"speaker":"横山委員","kind":"確認","question":"メールの件は、お休み等、何かあったときに送信ができるというのは、区のほうから利用者にという形で、一方向でそういったことができる機能がシステムとしてできるという認識で合っていますでしょうか。確認だけお願いします。","respondent":"横田情報推進課長","answer":"おっしゃるとおりです。","id":"exchange-002"},{"speaker":"横山委員","kind":"質問","question":"理解いたしました。様々な機能が付加されてすばらしいなと思うのですけれども、例えば、５月１３日から１４日の切替えのときにキャンセルをしたくて、それが１か月前のぎりぎりといったようなケースも、もしかしたらあるかもしれないのですけれども、利用停止の間の対応というのは区としてどうされるのかというところをちょっとお聞きしたかったので、そちらの補足をお願いできればと思います。","respondent":"横田情報推進課長","answer":"今現在この辺りはどうすべきかとちょうど詰めているところでして、決まり次第またご報告させていただければと思いますので、よろしくお願いします。","id":"exchange-003"},{"speaker":"横山委員","kind":"質問・要望","question":"皆さん、最近ホームページからですとか、ＤＸ化に慣れている方もいらっしゃるかと思うのですけれども、もし何かあったときに、お電話の対応ですとか、メールでの対応ですとか、利用停止の期間も含めて、どうやってフォローするかというところもしっかりと留意していただいて、ぜひ今後の周知、そして５月からの新しいシステムの切替えというところでランディングさせていただきたいと思いますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"あくつ委員","kind":"質問","question":"実際利用している側として、具体的なというか、細かいことを伺いたいのですけれども、今私も集会場とかをお借りして、きゅりあんの会議室等をお借りしたときに、オンラインで予約をして、中小企業センター等にお支払いに行くという手続きを踏んでいたのですけれども、これからはクレジットカード決済ができるということなのですけれども。","respondent":"篠田文化観光課長、横田情報推進課長","answer":"現金のお取扱いに関しては、クレジットカードでのお支払いができるというのが一つ新しい取組であります。当然クレジットカードをお持ちでないお客様もいらっしゃいますから、現金の取扱いは、今後も変える予定はございません。領収書の件ですが、今手元に資料がございませんので、確認してまたご報告します。","id":"exchange-005"},{"speaker":"あくつ委員","kind":"質問・要望","question":"会計上の話で恐縮なのですけれども、現金であれば当然、現金に名前はついていませんから、団体の名前でしっかりと領収書が出るのですけれども、これがカードになった場合に、個人名が出ると、会計上またちょっとややこしいことになる可能性があるので、その辺りは利用者側の都合に合わせた形でしっかり領収書が出るような仕組みにしていただきたいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"えのした委員","kind":"意見","question":"学校施設も予約でオンライン化することで、より一層区民の利便性向上につながると思っていますけれども、２の主な変更点の(2)、オンラインクレジットカード決済を導入する。","respondent":"横田情報推進課長","answer":"今後につきましては、システム事業者とかキャッシュレス事業者と区で、３者でできるような形で調整していく予定になっております。時期については未定なのですが、そのように考えています。","id":"exchange-007"},{"speaker":"えのした委員","kind":"確認","question":"確認が取れましたので、安心しました。そういった取組を進めていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"山本委員","kind":"質問","question":"システムを抜本的に見直されたというところでいうと、当時の課題がいろいろあって、それを踏まえて変えていかれるというアプローチをされたのだと理解しているのですが、どういった形で抜本的見直しなのかというのをちょっとお伺いしたいというところと、あとクレジットカード決済を導入して。","respondent":"横田情報推進課長","answer":"３点目のキャッシュレス対応ですが、取り急ぎ５大国際ブランドのクレジットカードに対応しつつも、今後ＱＲコードといったものにも対応できるように少し改善していければというふうに考えております。","id":"exchange-009"},{"speaker":"山本委員","kind":"質問・要望","question":"このようにお伺いできてとてもよかったなと思います。そういうふうに対応していただいているということを、変更をご案内するときにも、ぜひ併せてご案内いただいて、区として住民目線でそういった見直しを図っているということを言っていただくことが、区民の方に寄り添って対応しているということを示していくことになると思うので、そういったことをしていただきたいと思いました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"せらく委員","kind":"質問","question":"支払い方法についてなのですけれども、オンラインクレジットカード決済を導入して、現金払いも残しながら、今ある口座振替というのも残されるのでしょうかということをお聞きしたいのと、あとこちらのシステムリニューアルが、令和４年度にリニューアルの会社をプロポーザルで決定されたということなのですけれども、令和４年度の時点でリニューアルの予算が組まれていたということなのか、お聞きしたいです。","respondent":"三井スポーツ推進課長、宮澤地域活動課長","answer":"公園の施設につきましては、口座振替の登録をしておりますので、今後も残していく予定にしております。令和４年度にプロポーザルで事業者を選定しましたが、このリニューアルに向けた予算については、令和５年度に予算を計上しております。ですので、契約は令和５年度になってから契約をしたです。","id":"exchange-011"},{"speaker":"藤原委員","kind":"質問","question":"施設予約システムですけれども、まず何で中小企業センターは、ここに参加していないのでしょうか。","respondent":"小林商業・ものづくり課長","answer":"ですので、中小企業センターも含めて、幅広く施設予約システムの対象施設だというふうに認識しています。","id":"exchange-012"},{"speaker":"藤原委員","kind":"質問・要望","question":"すみません。よく分からないです。中小企業センターも施設がありますよね。入っているのだけれども、最初の説明で入っていないとか、でも入っているのですとか、よく分からないので、具体的に教えていただきたいです。","respondent":"宮澤地域活動課長","answer":"すみません。私の最初の説明が分かりづらかったかと思います。この予約システム自体は１１課にまたがって様々な所管がこのシステムを統一で運用しております。その中に中小企業センターも入っております。","id":"exchange-013"},{"speaker":"藤原委員","kind":"質問","question":"地域活動課長が説明してくれれば、もうそれで分かるでしょうということだったということですか。次がすぐに入ればいいですけれども、そうすると、７日前にいろいろ計画したりとなるのは、ある意味、主催者側からは本当に厳しい面もあると思うのですけれども、その辺についてどういう声があったのか、背景でこういうふうになったのか、また分けたのかという点についても説明していただけますか。","respondent":"宮澤地域活動課長、篠田文化観光課長、三井スポーツ推進課長","answer":"施設につきましては、中小企業センターも含めて説明させていただいたというところで、失礼いたしました。２つ目のところです。使わなくなったのだけれども、７日前までで全額返ってくるのだったらということで、そういった連絡をなかなかいただけないということも考えられます。区立体育館につきましても、特別な取扱いが残っているところについては指定管理者施設ということで、施設利用料収入に影響が出るということ。","id":"exchange-014"}]},{"id":"topic-02","title":"住民基本台帳事務における「特定個人情報保護評価」の実施","agenda":"住民基本台帳事務における「特定個人情報保護評価」の実施","exchanges":[{"speaker":"えのした委員","kind":"確認","question":"今の個人情報保護委員会、品川区のホームページに「特定個人情報保護評価について」と、令和３年にページができていて、そこからその委員会のサイトに飛ぶようになっているのですけれども、この第三者点検というのは、例えば、そういった委員会が点検するのか、どのような団体が点検するのか、そこだけ確認させてください。","respondent":"吉野戸籍住民課長","answer":"こちらは個人情報保護委員会とは直接全く関わってはいないところなのですけれども、品川区個人情報保護審議会の委員になります。実際に特定個人情報保護評価の概要と説明も、この評価が正しいかどうかというところで、第三者委員の方に評価していただくような形になります。","id":"exchange-015"},{"speaker":"えのした委員","kind":"確認","question":"品川区にもそういった委員会があるということで、確認が取れました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"せらく委員","kind":"質問","question":"１２月１日からパブリックコメントの実施という予定なのですけれども、区民意見の聴取ということで、何に対しての区民の意見を聴取するのかよく分からなくて、教えていただければと思います。","respondent":"吉野戸籍住民課長","answer":"実際にこのファイルがどのように使われていて、皆さんの情報をどのように使っています、リスクに対してはこういったリスクに対応していますというところが全て書かれたものになりますので、見ていただくことは本当にたくさんあるかなと考えています。","id":"exchange-017"},{"speaker":"せらく委員","kind":"質問","question":"評価書をご覧いただいて、その上で意見を聴取するという形になるのですか。","respondent":"吉野戸籍住民課長","answer":"そのとおりです。","id":"exchange-018"},{"speaker":"横山委員","kind":"質問・要望","question":"全体像が分かりにくいところがあったので、ちょっと確認させていただけたらと思うのですけれども、まず、そもそも国から令和７年度中でしたか、２０２５年度中にガバメントクラウドを活用した標準準拠システムの移行を目指して、移行作業が円滑かつ安全に実施されるということを求めているのかなと思うのですけれども、その中で住民基本台帳事務における特定個人情報保護評価を、今回の評価書を修正する。","respondent":"吉野戸籍住民課長","answer":"それ以外に、例えば、大きなシステム改修であったり、今回これは標準化、ガバメントクラウドへの移行なのですけれども、こういったものが５年前にあったというところで、今回はこういった評価をやらなければいけないという形になっております。","id":"exchange-019"},{"speaker":"横山委員","kind":"質問","question":"今のご説明だと、もともと評価書というものが品川区のホームページに公開されていますよね。それが５年前につくられたので、評価のタイミングであるという理解でよろしいですか。","respondent":"吉野戸籍住民課長","answer":"実際には前回の評価は令和２年ではあるのですけれども、今回の標準化システムは令和７年１月に開発をしなければいけませんので、それに合わせて少し前倒しで全体の評価をやっているという次第です。","id":"exchange-020"},{"speaker":"横山委員","kind":"質問","question":"システムの移行に向けて、５年に１回というものではなくて、システムの移行に対して修正する部分もあったりして、前倒しをする必要があるので、令和２年に行ったばかりですけれども、このタイミングで修正を実施するということで、修正内容としては、移行のために修正しなければならないことがあるので、今後修正の細かい項目というのを、今、精査したり、検討していただいているのかなと思うのですけれども。","respondent":"吉野戸籍住民課長","answer":"今回はシステムの改修があるので実施するということになります。それがなければ、５年に１回で、そのときには内容が変わっていなくても、必ず５年に１回はあります。ただ修正がある場合には、その都度実施することになります。","id":"exchange-021"},{"speaker":"横山委員","kind":"質問","question":"そうしましたらシステム移行に伴って、品川区だけではなくて、ほかの自治体もいろいろ修正しなければならない事項というのが恐らくあると思うのですけれども、その辺りは国等から指導であったり、相談しながら、項目と修正項目を見直していただいている作業を、今進めていらっしゃるということなのでしょうか。","respondent":"吉野戸籍住民課長","answer":"そういったデータ項目がこう変わりましたとか、そういった内容が全て網羅されたような形になります。そういった意味でいきますと、全体の項目が出ているようなイメージになります。","id":"exchange-022"},{"speaker":"横山委員","kind":"質問","question":"そうすると、ガバメントクラウド等の利用によって、システム全体が移行することによって、特定個人情報保護評価の考え方とか、内容が大きく変わるということではなくて、例えば、ファイルの場所みたいな、細かいところで修正がいろいろ必要なので、置き換えというか、今はガバメントクラウドを利用していないので、例えばＡというところに書いてあるけれども、ガバメントクラウドを利用することになると。","respondent":"吉野戸籍住民課長","answer":"委員のご指摘のとおりでして、今回主な修正項目を３に記載しています。","id":"exchange-023"},{"speaker":"あくつ委員","kind":"質問・要望","question":"今、個人情報保護という言葉が独り歩きして、決算特別委員会のときも申し上げましたが、住民基本台帳法上の情報を町会・自治会等に提供するのが難しくなったというようなこともありますけれども、関心は非常に高いという中で、区としてはこういうことをしっかり、適正なプロセスにのっとって手続きを進めているということを示すいい機会でもありますので、そこについては、同じ答弁になってしまいますから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"それで、標準準拠システムに移行していくことで、令和７年度に向けてやっていくことで、特定個人情報保護評価を実施しなければいけないと。いいですよとか、全然駄目ですよとか、評価書に対しての評価がまた返ってくる形になるのか、そして評価書も含めてパブリックコメントもするということなのですけれども、それは全てが公開されるということでいいのか、伺います。","respondent":"吉野戸籍住民課長","answer":"窓口でどういった会社でどういった内容を委託していくのかというのを記載しております。特定個人情報保護評価の回答なのですけれども、問題ありませんというような回答をいただいてから、公表する形になります。","id":"exchange-025"},{"speaker":"石田（ち）副委員長","kind":"確認","question":"分かりました。先ほどあくつ委員からもありましたけれども、前回は０件で、そうだろうなという思いです。特定個人情報保護評価をするに当たってはパブリックコメントもやらなければならないというふうに入っているものなのですか。取りあえずやっていますという感が否めないのですけれども、そこの確認と、もうちょっと分かりやすくできる工夫というのを区として検討しないのか、伺いたいと思います。","respondent":"吉野戸籍住民課長","answer":"住民基本台帳は４０万人というところで、３０万人以上の場合はこういった第三者点検とパブリックコメントは実施しなければならないということが規定されております。それ以外に関しましては、任意になっております。","id":"exchange-026"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"なかなか分かりづらい部分でもありますけれども、本当に個人情報は大事な部分で、そしてそれが国のシステム標準化で変わっていくことになるので、そこは丁寧にしていただきたいなと私も要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"}]},{"id":"topic-03","title":"顔認証マイナンバーカードの開始","agenda":"顔認証マイナンバーカードの開始","exchanges":[{"speaker":"横山委員","kind":"確認","question":"１点だけ伺わせてください。顔認証マイナンバーカードで、うまく認識できないというような事例があるのかなと思うのですけれども、どういう事例があるのかというのと、その場合の対策についてどのように考えられているのかというのを確認させてください。","respondent":"吉野戸籍住民課長","answer":"医療機関等で実際に使うときに、顔の写真を撮って、それと整合がつかないときがありまして、それでうまく読み取れないというような形になります。そういった方がもし健康保険証として利用される場合には、顔認証の場合には、券面の写真と住所を確認して目視での確認になります。","id":"exchange-028"},{"speaker":"横山委員","kind":"質問","question":"私の聞いた事例だと、髪の毛がちょっと目にかかっていたりするとこのシステムは認識しづらいみたいな形で、そういったところもあるような話を聞きますので、うまく認識できない事例というのをちょっと捉えていただいて、なるべく認識しやすいような写真を使っていただくとか、そういったご案内というのもしていただくといいのかなと思っているのですが、その辺りはいかがでしょうか。","respondent":"吉野戸籍住民課長","answer":"確かに最初にカードをつくるときに、正面であったり、例えば車椅子であったりが映ってしまう場合もあるのですが、そういったときでもやはり顔の目と鼻と口の部分が認識できればできるような形になっておりますけれども、実際にいざ認証するときに。","id":"exchange-029"},{"speaker":"あくつ委員","kind":"質問","question":"顔認証マイナンバーカードの仕組みなのですけれども、現在保持している人で希望する方となっているのですが、新しいカードを発行するのではなくて、今あるカードを、総務省が発行している資料、ちょっと前の８月の資料ですけれども、それを見ると、暗証番号をロックするというような形を今考えていますということで、いわゆる暗証番号等を使わなくても、医療機関、薬局に情報提供することができるようになる。","respondent":"吉野戸籍住民課長","answer":"今回のカードが実装する意味なのですけれども、病気や体が不自由な方、マイナンバーカードの暗証番号の管理がとても不安な方がいらっしゃるという声が上がりまして、そういったところを解消するために、顔認証マイナンバーカードが導入されたという経緯になっております。","id":"exchange-030"},{"speaker":"あくつ委員","kind":"意見","question":"経緯は分かるのですけれども、仕組みとしてこれから先、１１月２７日と書いてあるから、あれ、もうスタートしているのかなと私もホームページを見たら、特に何も載っていなかったので、先ほど訂正があったのですけれども、これから希望する方というのは、例えば私が顔認証マイナンバーカードを使いたいと思ったときには、現在持っているマイナンバーカードを持って行って。","respondent":"吉野戸籍住民課長","answer":"失礼いたしました。先ほどの開始時期の、対応可能窓口のところで書かせていただいたのですけれども、顔認証カードの交付であったり、あと切替えのところです。","id":"exchange-031"},{"speaker":"あくつ委員","kind":"質問","question":"印字をするということは分かったのですけれども、先ほど私が申し上げたような、いわゆる電子的なロックをかけるということではないということですか。","respondent":"吉野戸籍住民課長","answer":"電子証明書を使えなくするロックをかけます。","id":"exchange-032"},{"speaker":"あくつ委員","kind":"確認","question":"その手続きについては即日でできるし、簡易だということは今、確認させていただきました。今日の所管からは少し広がった話になってしまいますが、今回国からこういうような通知が来ておりますけれども、品川区として、昨年は行政書士を活用した申請サポート事業を行いましたけれども、今年、来年度を含めて、そういったこともご検討されているのか教えてください。","respondent":"吉野戸籍住民課長","answer":"今回の顔認証マイナンバーカードなのですけれども、施設の施設長、高齢者施設であったり、障害者施設の方からも、暗証番号の管理がとても難しいというお声が上がった経緯もあると考えています。","id":"exchange-033"},{"speaker":"あくつ委員","kind":"確認","question":"それともう一点だけ確認です。これは高齢者とか障害者の所管になってしまうのですけれども、こういったところについて周知ができているのかどうかというところを最後に確認させてください。","respondent":"吉野戸籍住民課長","answer":"委員ご指摘の疎明資料なのですけれども、出頭困難な方に対しましては、施設長であったり、ケアマネージャーの方に署名していただくと顔写真で代理申請、それから代理受領というのが可能ですので、そういったところは高齢者等の担当と連携を取りながらやっているところです。","id":"exchange-034"},{"speaker":"えのした委員","kind":"質問・要望","question":"ご説明、どうもありがとうあります。例えば、機械が停止したり、故障したというときに、目視による顔確認、ただデジタルなのに、ＤＸなのに目視なのかというところもあるので、ご担当者が万が一間違えたとか、責任だったり、リスクだったりがあると思うのですけれども、その辺は区独自で何か対策として考えていることなどがあればお聞かせいただきたいです。","respondent":"吉野戸籍住民課長","answer":"先ほどお伝えしたとおり、これ自体は国のシステムとつながっておりますので、区として機器を提供するとか、そういった独自のものは、現在は考えておりません。","id":"exchange-035"},{"speaker":"えのした委員","kind":"確認","question":"窓口での目視の場合に、やはり人間がすることですから、ヒューマンエラーではないですけれども、違う方と見間違えるということは、そうないとは思うのですけれども、万が一のことを考えた場合に、区としてその辺は何か、１人だけで確認するのではなくて、２人で確認するとか、何かそういったことは。","respondent":"吉野戸籍住民課長","answer":"委員のご指摘のとおり、本人確認というのはとても大切なことですので、私どもの窓口では確かに１人ではなくて、数人で確認しております。医療機関のほうにもそういった呼びかけをしていきたいと考えています。","id":"exchange-036"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/238887?Template=document&Id=2976#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":24130,"voices":97}},{"id":"r05-20231128-7","meetingId":"r05-cm11","date":"2023年11月28日","dateIso":"2023-11-28","committee":"厚生委員会","time":"午前１０時０８分～午後 ３時２７分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を85件抜き出しています。","topics":[{"id":"topic-01","title":"を聴取したいと思います。 初めに、(1)「品川区障害者計画及び第７期品川区障害福祉計画・第３期障害児福祉計画（素案）」に係るパブリックコメントの実施","agenda":"を聴取したいと思います。 初めに、(1)「品川区障害者計画及び第７期品川区障害福祉計画・第３期障害児福祉計画（素案）」に係るパブリックコメントの実施","exchanges":[{"speaker":"おぎの委員","kind":"意見","question":"私もこの策定委員会、３回の開催を、途中退室という時もあったのですけれども、３回とも非常に興味深く傍聴させていただきました。私のほうから２点だけありまして、ページが飛びますので１点ずつお聞かせいただきます。３月に、こちらの障害者計画等を作成するための報告書、こちらのほうをいただいたのですけれども、こちらの１７ページ。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"},{"speaker":"おぎの委員","kind":"質問","question":"そうですね。障害者計画等策定のための基礎調査報告書。大丈夫でしょうか。","respondent":"川崎障害者施策推進課長","answer":"アンケートのほうですね。","id":"exchange-002"},{"speaker":"おぎの委員","kind":"質問","question":"大田区では、「おおた障がい政策推進プラン」として、障害者計画、障害福祉計画、障害児福祉計画のほかに別枠として、大田区発達障がい児・者支援計画と、発達障害だけ切り離してカテゴリーが、令和３年から始まっていますので、人数の増減等を見ながら、そういった発達障害の方というのももう少しクローズアップして、計画等もまた次期に盛り込んでいっていただけたらいいなと思いますが、いかがでしょうか。","respondent":"川崎障害者施策推進課長","answer":"今、委員がおっしゃった報告書というのは、基礎調査報告書のことですね。令和４年度に実施した基礎調査の報告、アンケートの結果になります。今回クロス集計等をしまして、様々な障害がある方の障害の特性というものを、具体的に示しています。","id":"exchange-003"},{"speaker":"おぎの委員","kind":"意見","question":"発達障害の方が増えてきていると、ご家族やお母様なども、どうしようといっていろいろ情報を探していると思います。こちらの報告書のほうでも、７８ページの行動援護のところで「「今後利用したい」が、〔居宅介護〕が１２.１％〔行動援護〕が１０.７％と１割台で高く」という評価も出ておりますけれど、これはニーズがあるのかなと思うのですが。","respondent":"川崎障害者施策推進課長","answer":"行動援護のところですけれども、令和３年、４年、５年と実績がゼロになっているというのは、利用実績がなかったということでゼロという記載になります。今後、令和６年度以降は、利用者１を見込んでいるという形で、記載となっております。","id":"exchange-004"},{"speaker":"おぎの委員","kind":"質問","question":"こちら、利用者１名を見込んで８６時間ということなのですが、８６時間確保できる準備等はできているのでしょうか。","respondent":"松山障害者支援課長","answer":"行動援護の令和６年度からの見込量についてのご質問です。行動援護を指定されている事業所はおりますので、利用される方がお一人いらっしゃれば、この程度の時間数の見込みというのは、通常のサービス量から見込んだものですので、お一人利用されれば８６時間がほぼ目安だろうと。","id":"exchange-005"},{"speaker":"おぎの委員","kind":"意見","question":"今までこういったことがなかったので、０時間であったと理解いたしました。そして、今後、今のところは希望の人数があまり多くないので、８６時間という準備でされているということで、承知いたしました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-006"},{"speaker":"ひがし委員","kind":"確認","question":"今は利用を希望されている人がいなくて、利用していないからゼロとなっていて、ただ、報告書を読んでいると、「今後利用したい」という方は１０.７％いらっしゃって、その方々がもし希望された場合は８６時間分の提供の枠を、既に準備ができているということなのか、それとも、令和６年度に向けてサービスを提供できる見込みということなのか、というところは確認したいかなと思いました。いかがでしょうか。","respondent":"松山障害者支援課長","answer":"今、令和６年度からということになっていますけれども、実際希望される方がいらっしゃって、相談員にご希望を伝えていただいて、事業者との契約ということが整えば、この時間数は今年度であっても提供されるものです。","id":"exchange-007"},{"speaker":"ひがし委員","kind":"質問・要望","question":"その点が確認できて、安心しました。時間は見込みということも分かりますし、利用される方々が時間を決めて、この８６時間に持っていくというわけではなく、その枠がきちんと確保できていて、希望されるときに使えるのかというところを確認したかったのかなと思いましたので、私も付け加えて質問させていただきました。","respondent":"川崎障害者施策推進課長","answer":"ただ、やはりボリュームがありますので、配布も含めて検討はします。今後ですけれども、ホームページ、広報しながわ等で周知をします。今のところ、別途説明会という予定はございません。","id":"exchange-008"},{"speaker":"ひがし委員","kind":"質問・要望","question":"パブリックコメントで区民の声を聞くといっても、現場に行かないと見られないとか、しかもボリュームが多いというふうになると、できる方が限られてしまうかなと思うと、発達障害の方々のお母様とか、なかなか行かれないという声が拾えないのかなと思うので、そういう方法も、今はまだ検討していないということだったのですけれど、今後検討していただければいいなと思いますし、強く要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それなので、いろいろな思いがあると思うのです。パブリックコメントというのはそういうものを吸い上げる、いい機会なのではないかと思うのです。区としてこういう方向でやりますよというところが全然分からないで、意見を言うというのもなかなか難しいですし、そういう点ではぜひ説明会は、切実な要求だけに、ぜひやっていただきたいと思うのですけれど、ご検討いただけないでしょうかというのが１点です。","respondent":"川崎障害者施策推進課長","answer":"他区の周知方法なども今後の参考にしながら、十分に検討はしていきたいと思います。２つ目の団体数ですけれども、１３団体にヒアリングをいたします。３つ目の方法ですけれども、基礎調査の際にヒアリングをしたときと同様のスタイルで、実施することになります。","id":"exchange-010"},{"speaker":"鈴木委員","kind":"質問","question":"基礎調査の時のヒアリングの中身を、教えていただけないでしょうか。今、私が言ったような形での、説明みたいな形でパブリックコメントが広く出せるような、そういう形なのか、それとも、何というのですか、団体の中心の方にだけ集まっていただいて意見を聞くという感じなのか、そこら辺のやり方についてお聞かせください。","respondent":"川崎障害者施策推進課長","answer":"主には団体の中心の方と、ヒアリングをするという形になるかと思います。","id":"exchange-011"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それは団体の方の希望ということにもなると思うのですけれど、会員の方も含めて説明をしていただいて、パブリックコメントも皆さんが出せるようにというふうな希望があったら、ぜひその希望に応えるようにしていただきたいと思います。だから１ページ抜けてしまったのかなと思ったのですけど。これがもし抜けたのであれば、追加していただいたほうがいいかなと思ったのが、１点です。","respondent":"川崎障害者施策推進課長","answer":"ご指摘ありがとうあります。確認させていただいて、もしこちらが抜けていたら、早急に対応いたします。ありがとうございました。","id":"exchange-012"},{"speaker":"鈴木委員","kind":"質問・要望","question":"同行援護についても、これは同行援護のヘルパーさんがいないために、なかなか使える時間が使えないというようなところを、区としてもその養成をしてこれから拡大していきますという方向を出していると思うのですけれど、それが、８２ページの「見込量確保のための方策」という四角枠の中にはそういうふうに書かれているのですけれども、それなのにこれまでよりも減ってしまう見込量で。","respondent":"川崎障害者施策推進課長","answer":"２つを比較して、将来サービスの見込量が多いほうを、採用しております。ただ、見込量としてはサービスの上限を定めるものではありませんので、一人ひとりへの個別支援というのが最も重要なことでありますので、そこは丁寧に進めていきたいと考えております。","id":"exchange-013"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そうは言っても、こういう形でここは見込量と確保の方策ということになるわけですので、これまでよりも減ってしまう見込量というのは、しかも令和３年度、４年度というのはかなりコロナの影響も受けている、その受けているところよりも減ってしまう見込量というのは、要望があれば受けていきますよということなのか、でも、そうしたら何のための見込量なのかということになってくるのではないかと思うので。","respondent":"川崎障害者施策推進課長","answer":"今回、将来推計を出して、サービスの見込量が多いほうを採用しておりますが、あくまでも見込みになりますので、それを超えたらもちろん、その方に対しての対応というのはしていくことになります。","id":"exchange-014"},{"speaker":"鈴木委員","kind":"質問・要望","question":"放課後デイは２３日まで使えることに、前は１０日までだったのですけれど、かなり議会のほうでも声を上げて、２３日まで使えるということになったのですけれど、実際そういうふうに使えていないのですけれど、でも、それは区としても積極的に誘致して充実を図るということであれば、ここのところもう少し、これでは多分希望に添えないと思うので。","respondent":"川崎障害者施策推進課長、松山障害者支援課長","answer":"実際のところ、放課後等デイサービスの事業所数が足りていない状況ですので、区としては誘致に取り組むというところで、今、相談も来ていますので、そちらの個別相談への対応も含めて民間の参入が結構ありますので。放課後等デイサービスも含め、サービスの給付については現在国のほうで、令和６年度の報酬改定の見直しが検討されております。","id":"exchange-015"},{"speaker":"鈴木委員","kind":"質問","question":"それで、本当に事業所の質というのがこれからいろいろ問われてくると思うのですけれど、そういうときに、事業所連絡会をやっていきますよみたいな、そういう方向がこの計画の中にもあったと思うのですけれど、今、事業所連絡会というのは具体的に、どのようなところがどういう形でされているのか、そういうものに区も関わって、事業所の質を上げていくことにつながっていくのではないかと思うのですけれど。","respondent":"松山障害者支援課長","answer":"相談事業所連絡会は本当に定期的に、頻度を高くして行っているものです。障害児向けの事業所連絡会というのを、区と心身障害者福祉会館、障害児者総合支援施設、その３者が協力をしまして、区内の障害児向けの事業所に呼びかけをして、事業所連絡会というのを開催しています。","id":"exchange-016"},{"speaker":"鈴木委員","kind":"質問","question":"事業所連絡会というのは大きなところだけでなく、民間の、例えば放課後デイの連絡会のようなものであったり、民間事業所の連絡会というのを、私も他区でいろいろ話を伺ったとき、そういうふうなものをやって質を上げるような形にしているということも、お話を伺ったことがあるのですけれど、そういう民間での連絡会、例えば民間の放課後デイの事業所に集まっていただいて、共有をしながら。","respondent":"松山障害者支援課長","answer":"ご説明申し上げます。事業所絡会については、区立、民間を問わず全ての事業所に参加していただいております。ただし、児童発達支援、放課後等デイサービス、一緒に行っておりますので、それぞれにきめ細やかに行う方法も一つかと考えています。これから検討してまいります。","id":"exchange-017"},{"speaker":"やなぎさわ委員","kind":"意見","question":"３０ページの就労機会の拡充のところですが。後期、令和３年から５年で超短時間就労促進事業、令和５年から開始されていると思うのですけれど、これに関して、どこでどういうふうに行っているか、告知あるいは現時点でどれくらいの方が利用されているか、素案の中に特になかったと思うのですけれど、その点、情報をお知らせしてあげてほしいのですが。","respondent":"松山障害者支援課長","answer":"この中には特に、この数値目標というのは、国から示されている成果目標あるいはそれぞれのサービスの目標を示したものですので、超短時間就労促進事業につきましては、まだ今年度スタートしたばかりということで、来年度モデル実施の予定なので。","id":"exchange-018"},{"speaker":"やなぎさわ委員","kind":"質問","question":"分かりました。恐らく需要が見込まれる事業だと思いますので、周知を含めてぜひお願いいたします。ほかの委員の前の質問と重なるところがあるかもしれませんけれども、パブリックコメントの周知に関してなのですけれども。例えば区の旧ツイッターとか、そういったＳＮＳでの発信の予定というのは、特に今のところは検討中ということでしょうか。","respondent":"川崎障害者施策推進課長","answer":"そこも含めて十分検討します。","id":"exchange-019"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"先ほど鈴木委員のご指摘もあったのですけれど、見込額というのを割り返すと、そんなに変わってないという状況が結構散見されるので、別にそれ以上、見込みより増えても対応できないわけではないというのは、先ほどご答弁で確認はできたのですけれども、区民の側からすると、少しそういう感覚にならないのかなと思うので、できれば、そこら辺のことも含めて数字とかもう少し。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"鈴木委員","kind":"質問","question":"医療的ケア児のことで伺いたいのですけれど、１９ページには医療的ケア児は３０人と書かれているのですけれど、同じこの計画の４３ページの、「医療的ケアについての困りごと【障害児】」というところで、ｎが５４となっているのですよね。だから、ケア児だけで５４人ということになるのではないかと思うのですけれど、この５４と３０の数というのはどう捉えたらいいのか、伺いたいと思います。","respondent":"川崎障害者施策推進課長","answer":"４３ページ以降、基礎調査のところの人数ですけれども、これは病院に入院させている方もいらっしゃいますし、区としては把握し切れていない方の人数というのも含まれております。","id":"exchange-021"},{"speaker":"こしば副委員長","kind":"質問・要望","question":"委員の私たちもないのです。持ち合わせてないのですよ。恐らくホームページで、先ほどおぎの委員も提示されていましたけれども、ほかの委員は把握できていないところもあるので。それであれば委員会の事前に、１週間前とか２日前か、分からないですけれども、全員にそれはしっかり事務局と相談した上で、共有していただきたいと考えます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"鈴木委員","kind":"質問","question":"議員がいろいろとどのような資料を基にして、どう質問するかというのは、もうそれぞれ、いろいろな資料を基にしながら、ここにこういうことが書いてありましたよとかいうのは、何というのですか、事前にいろいろ調べて質問に臨むので、それを全部、全てここに書いてあったこういうもので質問しますので、皆さん、共有してくださいというふうには、なかなかならないと思うのですよね。これまでも。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"鈴木委員","kind":"質問","question":"こういうもので、ということは、もう少し皆さんにも分かるような形で、質問の仕方にするようにしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そうしますと、医療的ケア児というので、区がこの人が医療的ケア児だと、顔も分かるというところでは３０人だけれども、しかし、区として顔と名前が一致するということでないところでは、少なくとも５４人は医療的ケアの方がいらっしゃると、そういう捉え方でいいのかという確認を、お願いしたいと思います。","respondent":"川崎障害者施策推進課長、松山障害者支援課長","answer":"今後も実態の把握には努めてまいりたいと思います。移動支援事業につきましては、昨日指定管理者の指定のところでも、移動支援を増やしていくという方法をご説明させていただいたのですけれども、この計画自体も、第３回策定委員会で委員の皆様のご意見を伺いつつ。","id":"exchange-025"},{"speaker":"鈴木委員","kind":"質問","question":"そうすると、全体的にサービス見込量というのはこれから３年間、今までより少なくなると、何となく希望があまり持てないような気がしてしまうのですけれど、これから検討して、この数字は変わり得るということはあるのでしょうか。","respondent":"松山障害者支援課長","answer":"第３回の策定委員会で、委員の皆様にご審議いただいた結果ではあります。ですので、この数値で素案としてお出ししていくことになります。ただ、やはりコロナがありまして、実際に見込量を、令和２年、３年と下回ってしまった事業、サービスもあります。","id":"exchange-026"},{"speaker":"鈴木委員","kind":"質問","question":"３０ページの「しながわ見守りホットライン」なのですけれど、ここに寄せられた虐待の情報というのは、計画の中には書かれてないと思うのですけれど、この件数というのは何件ぐらいあるのか、また、そういうのをここの中にも、何といいますか記述していただくと、それが見えるのではないかと思うのですけれど、いかがでしょうか。","respondent":"松山障害者支援課長、川崎障害者施策推進課長","answer":"区の法定雇用率は、確かに委員おっしゃるように２.６％になっておりますが、それは人事課所管のものですので、数字としては把握しているものではございません。令和３年度末の人数は１２８名、これが総合実施計画上に記載されている人数ですが、これを令和８年度までに２２８名に増やすということで、区内にホームを開設して、スピード感を持って進めていく、そのような形で取り組んでいます。","id":"exchange-027"},{"speaker":"鈴木委員","kind":"質問・要望","question":"いろいろありがとうございました。ぜひ、障害者の皆さんからご意見を伺っていただきながら、本当に障害者福祉が前進するような形で取組を進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"筒井委員","kind":"確認","question":"確認なのですけれど、素案の８ページの第２章、タイトルは「障害児者の現状」と書いているのですけれど、書いてあることは障害児に限らず、成人の障害者のことにも触れているのですけれど、なぜタイトルが障害児者にしてあるのか、伺いたいと思います。","respondent":"川崎障害者施策推進課長","answer":"こちらの障害児者の現状は、こちらの棒グラフを見ていただくと分かりますとおり、年齢別にも分かれておりますので、障害児、障害者、大人と子どもの推計というものが載っている形ですので、現状把握として掲載しております。","id":"exchange-029"},{"speaker":"筒井委員","kind":"質問","question":"あえて障害児者をクローズアップしたいから、この書き方にしたということでよろしいですか。","respondent":"川崎障害者施策推進課長","answer":"今回、障害者計画という、障害者の基本計画に当たる部分の策定となりますので、障害者全般に関わる部分になりますので、このように障害児者を取り上げているということになります。","id":"exchange-030"},{"speaker":"筒井委員","kind":"質問","question":"ひきこもりということがありますけれど、ひきこもりは様々な原因があり、なかなか、なぜそういう状態になったのかというのは様々なパターンがあるかと思うのですけれども、一方で発達障害が原因であることもあります。そうしたとき、このひきこもりという用語は、入れないのでしょうか。ひきこもりについて、どうお考えなのか伺いたいと思います。","respondent":"松山障害者支援課長","answer":"委員おっしゃるとおり、ひきこもりになる要因、それぞれの状態は非常に様々ですので、もちろんひきこもりの方の中には発達障害の方もいらっしゃる、また精神障害の方もいらっしゃる、そのほか様々な要因の方もいらっしゃいますので。","id":"exchange-031"},{"speaker":"おぎの委員","kind":"意見","question":"すみません、最後に１点だけ、災害のところだけお聞かせください。２７ページの人工呼吸器使用者の、自家発電装置というのを令和４年度から追加して入っているのですけれども、これは実際のところ、支給した実績等はありますか。","respondent":"松山障害者支援課長","answer":"在宅人工呼吸器の方への自家発電装置につきましては、令和４年度には１件ございまして、５年度につきましては、少しずつ広がっているところです。数件以上は支給した実績があります。","id":"exchange-032"},{"speaker":"おぎの委員","kind":"質問・要望","question":"告知のほうも進めていただきたいと思います。実際に災害が起きたときというのは、人工呼吸器の方が自己避難する場所というのは、どちらを想定されているのでしょうか。","respondent":"松山障害者支援課長","answer":"それぞれの個々人によって、災害時の避難計画というのはご本人やご家族と相談しながら作っていくものです。人工呼吸器の方は、移動にリスクも伴いますので、在宅をご希望されている方が多い状況です。","id":"exchange-033"}]},{"id":"topic-02","title":"戸越四丁目区有地の今後の活用","agenda":"戸越四丁目区有地の今後の活用","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"対象となる障害で、重度の方を受け入れられるようなものを検討して公募するのか、そこら辺はどういう、性別にしても、対象の障害種別も含めて、どのようなグループホームになるのかも伺いたいと思います。","respondent":"川崎障害者施策推進課長","answer":"ただ、今は、最終的なボリュームチェックの結果を待っておりますので、その結果次第で確定となります。こちらの運営につきましては、資料の米印にありますとおり、選定事業者にて実施予定ということで、民設民営で選定を行っていくことになります。","id":"exchange-034"},{"speaker":"鈴木委員","kind":"質問","question":"そうすると、３０年定期借地のような形でなっていくのでしょうかね。それから、公募するのは来年度ということになると思うのですけれど、公募をしてもなかなか事業者が来ないというか、難しい状況が今まであったと思うのですけれど、どういう形で公募をされるのか、どこに声をかけていくのか、そこら辺の公募の仕方、応募していただけるような公募の仕方はどう考えられているのか、も伺いたいと思います。","respondent":"川崎障害者施策推進課長","answer":"今後の区有地の考え方ですけれども、やはり区有地は区全体の行政需要を考慮し、検討を進めていくことになりますので、全体の中で今後も、連携する企画課含めて検討していくことになります。","id":"exchange-035"},{"speaker":"鈴木委員","kind":"質問","question":"ということは今、様々、区有地の洗い出しというところで、何に使うかというのは区全体として考えるとしても、区有地で活用できる土地というのはほかにも、見つかっているというか、見つけなくてもあるのかもしれないですけれど、そこら辺の可能性はほかにもまだあると考えていいのか、その点だけ伺います。","respondent":"川崎障害者施策推進課長","answer":"一方で、やはり民有地の活用というのも必要にはなっていきますので、土地を所有しているオーナー様への働きかけというのも十分検討しながら、実際に今年度、個別相談会というのも実施させていただきましたので。","id":"exchange-036"},{"speaker":"鈴木委員","kind":"確認","question":"ということは、民有地を品川区が取得して、それで区有地として貸出して、定期借地みたいな形でする、そういうことも考えているということですか。民有地を品川区が取得して、グループホームの整備に充てていくと。それとも、そうではなくて自分の土地を使って自分で建ててくださいよと、そういうことだけなのか、そのことだけ確認をお願いします。","respondent":"川崎障害者施策推進課長","answer":"現在は、障害当事者のご家族の方で土地をお持ちの方に向けた相談会ということで、具体的な話が進んでいるということになっております。","id":"exchange-037"},{"speaker":"やなぎさわ委員","kind":"確認","question":"改めて確認なのですけれど、運営主体は民営になるのか、区でやるかというのは、まだ決まってないということですね。","respondent":"川崎障害者施策推進課長","answer":"民間事業者にて実施をすることになります。","id":"exchange-038"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"そのように考えると、大丈夫なのかなという不安、どれぐらいの応募があるのかなという不安もあるので、そういった面でいうと、民間活力だけでなく、区の力も活用することもぜひ考えていただきたいと思いますし、民間に依頼するならそれこそ、前回もそうでしたけれど、３０年とかの定期借地の期間が終わったら更地にして返すみたいな、いや。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"ひがし委員","kind":"質問","question":"この戸越四丁目の区有地の今後の活用で、グループホームになるということで、福祉の領域で使えるということはうれしいなと思います。２日間ぐらいで予約多数だったのかなと考えると、開設したいと思う方々が結構参加されたのかなというふうに想像されるのですが、この実態というところで、参加された方々の人数はどのぐらいだったのか聞けたらと思うのですが、いかがでしょうか。","respondent":"川崎障害者施策推進課長","answer":"こちらの相談会は、５組の方を対象に予約制で行いました。委員おっしゃるとおり、開始から１時間で埋まってしまいまして、１０月２５日にはホームページのほうで予約受付は終了しましたというふうに掲載しています。","id":"exchange-040"},{"speaker":"ひがし委員","kind":"質問・要望","question":"今回申込みが多かったということを踏まえると、今後も開催はぜひ検討していただきたいと思うのですが、その点について、検討状況を教えてください。","respondent":"川崎障害者施策推進課長","answer":"私どもも今回は試験的に初めて行いまして、反響があったということで、そこについては開設したい方々がいらっしゃるのだという実態をつかむことができました。今後も、この件については前向きに検討していきたいと考えております。","id":"exchange-041"},{"speaker":"鈴木委員","kind":"質問","question":"今の障害者グループホームの開設に関する個別相談会というのは、５組来られたというのは、品川区の補助金が受けられますよということも含めた相談会ということなのでしょうか。","respondent":"川崎障害者施策推進課長","answer":"今まで公的補助を使った事業者ですけれども、グループホーム金子山と、令和４年度の民間でのグループホームの運営者と、今、２件です。","id":"exchange-042"},{"speaker":"鈴木委員","kind":"意見","question":"民設民営でのグループホームは結構幾つもできていると思うのですけれど、この補助金が活用されない、壁というか何かそういうものがあって、２件しか使われてないという、もっとたくさんできていると思うのですよね、それなのに補助金が使われていない理由というのは、どのようなものがあるのかお聞かせください。","respondent":"川崎障害者施策推進課長","answer":"は東京都のほうで補助金の申請をする必要がありますので、そのタイミングも含めて、品川区の整備費補助のタイミングとずれてしまうということも、１つあります。自己資金などで建てられるという方もいらっしゃる、それは事実です。","id":"exchange-043"},{"speaker":"やなぎさわ委員","kind":"質問","question":"今の質問に追加でお伺いしたいのですけれど、手持ちの資金でやるというのは、例えば補助金を受けると何か制約ができてしまうから、あえて自分たちの自己資金でやるという、そういう事務所が多いというか、いるということでしょうか。","respondent":"川崎障害者施策推進課長","answer":"区の補助金を使うということは、東京都の申請もありますので、手続に時間がかかるというのもあります。早急に建てたいという方、そこで２段階の申請を早めて建てたいという方は、ご自身の蓄えで作られるという方もいらっしゃいます。","id":"exchange-044"},{"speaker":"やなぎさわ委員","kind":"質問","question":"私が今お伺いした、いろいろ条件が出てしまうとかいうことではなく、スピード感という方が多いということで、よろしいですか。","respondent":"川崎障害者施策推進課長","answer":"そのとおりです。","id":"exchange-045"}]},{"id":"topic-03","title":"「第九期品川区介護保険事業計画概要（案）」に係るパブリックコメントの実施","agenda":"「第九期品川区介護保険事業計画概要（案）」に係るパブリックコメントの実施","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"やはり介護というのは本当に多くの区民の関心事ですし、やはり切実な思いも抱えていますので、様々要望があると思いますので、要望を聞く機会としても、説明会をぜひ持っていただきたいと思います。その点、いかがでしょうか。２３区の中でも幾つもの区が説明会をやっていると思うのですが、その２３区の説明会の状況というのも、分かったらお聞かせいただけたらと思います。","respondent":"菅野高齢者福祉課長","answer":"２３区の他区の状況ですけれども、近隣区におきましては、例えば大田区が１２月に２回ほど予定をしている、渋谷区も１２月に４回ほど予定しているというところで、説明会を実施する区もあれば、説明会を実施していないだろうという区もあるというところなので。","id":"exchange-046"},{"speaker":"鈴木委員","kind":"質問・要望","question":"たしか世田谷区とかほかの目黒区とか、私、今回調べていないのですが、前回調べたときには、近隣区どこでもやっていると思ったのですが、そこら辺のところはつかまれていないでしょうか。それで、やはりパブリックコメントを多くの区民からいただくためにも、説明会はぜひやっていただきたいと思うのですが、ちなみに３年前のパブリックコメントは何件ぐらい来たか、それも分かったら教えてください。","respondent":"菅野高齢者福祉課長","answer":"説明会、ご指摘の世田谷区と目黒区につきましては、今、こちらで捉えている範囲では、世田谷区は、パブリックコメントが９月７日から９月２７日までで終了しておりまして、説明会については、ホームページ上はなかったので、実施していないのかなというところです。","id":"exchange-047"},{"speaker":"鈴木委員","kind":"質問・要望","question":"説明会をやらない理由というのは何かあるのか。少しそこら辺のところも、何でやらないかというあたり、ぜひ区のこういうのをやっていますよというアピールの場でも、私は、啓発の場というところでも説明会というのは活用できますし、それで皆さんからご要望を伺う場としても、知らせてご意見を伺う場としても、説明会はぜひお願いしたいと思うのですが、改めてお願いします。","respondent":"菅野高齢者福祉課長","answer":"この中でも審議しているということと、あとは今回のパブリックコメントも実施するというところで、いろいろな角度からお声もいただいているというところで、今のところ説明会の予定はないとお答えします。","id":"exchange-048"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それで、一部のその２０人の方では全てを反映できるかというと、なかなか難しいと思いますし、これは毎回申し上げているのですが、ぜひ私は、品川区はほとんどの計画に対して説明会は開かないという方向で来ていますが、やはり区民に情報公開とか情報提供をして、そして区民の意見を聞く、住民参加という点からもぜひ説明会は、こういう大きな計画、３年に１回ですから。","respondent":"菅野高齢者福祉課長","answer":"それを合わせると１５０床ぐらいあるではないかというところなのですが、ここの見込みの出し方につきましては、今までの実績、令和３年とか令和４年の実績なども、推計値で国の「見える化」システムというシステムがあるのですけれども。","id":"exchange-049"},{"speaker":"鈴木委員","kind":"質問","question":"だから、本当にお金のある人でないとなかなか入れないというところは要支援から入れて、そして、そのところが介護財政をより使っているという状況では、私は公平性という観点から、有料老人ホームを誘導するというのはどうなのかなという思いがあるのですが、有料老人ホームを誘導するというよりも、誰もが低廉で入れる特別養護老人ホームをつくることのほうが。","respondent":"菅野高齢者福祉課長","answer":"それはそれなりのニーズがあるというところで、有料老人ホームを運営する会社も、品川区につくりたいというところで計画を立てるのだと思いますので、そのあたりの多様なニーズというところで、必ずしも皆さん、特別養護老人ホームに入りたいというニーズではないと思いますので。","id":"exchange-050"},{"speaker":"鈴木委員","kind":"質問・要望","question":"ちなみに、これは令和４年の介護保険制度の運営状況の資料ですが、特別養護老人ホームは約３７億４,３００万円、有料老人ホーム（特定施設）は約４０億９,７００万円ということで、これだけ多く使っていますので、また特別養護老人ホームは、計画してから、今回の３か所にしても本当に６年、７年とかかっていますので、私は、有料老人ホームを誘導するというよりも。","respondent":"菅野高齢者福祉課長","answer":"それ以外の、各こちらの数字につきましては、都内でも老人保健施設は比較的入れるところがあるというふうにも聞いておりますので、そういうところに入っていただくなどして、短い期間、基本的には３か月、長くて６か月という施設なのですけれども、在宅の療養に向けて。","id":"exchange-051"},{"speaker":"鈴木委員","kind":"質問・要望","question":"品川区は在宅介護支援センターが２０か所ということでありますけれども、仕組みとして少し教えていただきたいのが、在宅介護支援センターの委託に係る財源というのはどういうところから出てくるのかと、それから、２０か所で幾らぐらい在宅介護支援センターに委託料が出ているのか、その点を伺います。","respondent":"菅野高齢者福祉課長","answer":"１点目の、老人保健施設の今後の整備計画というところですが、こちら、区としては今のところ明確な予定はございません。","id":"exchange-052"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それからあと、ブラッシュアップのところで、７番の介護・福祉職員の確保といって、ここのところというのは（２）番でも、担い手の確保・育成というのはやはりすごい課題で、どこでも本当に大変な深刻な状況があると思うのですが、これは介護職員の待遇改善なしにはできないと思うのですが、その待遇改善に向けて、国も若干増やすという方向を出していますが、それはあまりにも少な過ぎると思うのですが。","respondent":"菅野高齢者福祉課長","answer":"介護の処遇改善ということにつきましては、様々なところで国としても全体的な問題とはなっておりますので、給料の値上げとか、そういった部分はご指摘をいただているところなのですが、やはり区としては、給与の原資となるものは介護報酬外から賄われるものというところが。","id":"exchange-053"},{"speaker":"鈴木委員","kind":"質問・要望","question":"介護職員の確保・育成というのが本当に根本的な問題ではないかなと思うのですが、介護報酬となるとやはり保険料にも反映してきてしまうということで、前に処遇改善交付金という形で国から出されたことがありましたので、そういう形もぜひ区からも求めていただきたいと思います。取りあえず、では一旦。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-054"},{"speaker":"ひがし委員","kind":"質問","question":"以前、第２回の定例会で我が会派の松永よしひろ議員から質問があったと思うのですが、まず、高齢化が進む中で介護職員の人材確保に力を入れてほしいという内容で、品川区の現状についてという質問をさせていただいたときに、「品川区は介護士が不足しているのですか」という趣旨の質問に対して、「現在、品川区内介護施設における介護士については、今のところ不足しているという声は届いていませんが、今後。","respondent":"菅野高齢者福祉課長","answer":"いずれにせよ、区内においては、例えば実際たまに散見されるのですけれども、介護人材がいないがためにサービス提供ができないとか、そういった事態までには今のところ陥っていないと、そういうところは共通していると認識しているところです。","id":"exchange-055"},{"speaker":"ひがし委員","kind":"質問・要望","question":"そこで、中を見ていくと、品川区の介護福祉専門学校の設置とか、そこの定員のところに力を入れていたり、その他の研修とかにも力を入れていると決算特別委員会のときにもお話をいただいていたと思うのですが、やはり給料の問題とか職場の環境も、品川区内の事業所については、品川区としても、政策、何か支援の方法を模索していくべきかなと思いますので、その点については要望にはなるのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-056"},{"speaker":"やなぎさわ委員","kind":"質問","question":"先ほど鈴木委員の質問ですけれども、パブリックコメント、前回６件で、多い、少ないみたいな話もありまして、その際に公募の区民の方も入られていると。そこで区民の方の意見も吸い上げているよと、多分そういったことなのかなと思ったのですけれども、この公募の区民の方というのは５名ですかね。何か応募基準というか、どういった形で公募されたのか、詳しくお聞かせいただければと思います。","respondent":"菅野高齢者福祉課長","answer":"介護保険制度推進委員の公募区民についてのご質問に、お答えします。こちらについては、公募委員の方は４名となっております。第１号被保険者と第２号被保険者の方で、３名の方が６５歳以上、１名の方は６４歳以下で構成されております。","id":"exchange-057"},{"speaker":"やなぎさわ委員","kind":"質問","question":"分かりました。当然、品川区の介護保険制度のことなので、介護事業所も大きく関わってくるお話かなと思うのですが、介護事業所というのはその委員会の中に何名ほど入られているのでしょうか。","respondent":"菅野高齢者福祉課長","answer":"事業者代表者としましては、医師会の会長、歯科医師会の会長などのほか、事業者代表として社会福祉法人の理事の方、あとはホームヘルスなどの会社をやっていますＮＰＯ法人を運営している方の理事の方２名。","id":"exchange-058"},{"speaker":"やなぎさわ委員","kind":"質問","question":"商店街の会長とか、そういう方も当然必要ですけれども、どちらかというとやはり実際事業をされているというか、運営されている方がより委員に入ったほうが、いろいろな意見が出ていいのかなと思うので、ぜひそういったメンバー構成というのを少し検討していただければなと思うのと、少し話が戻ってしまうのですが、公募の区民の方はたしか６５歳以上とか以下で区切られているというのは。","respondent":"菅野高齢者福祉課長","answer":"特に、そのあたり、何名という縛りはございませんので、毎年４名というところで選ばせてもらっています。ちなみに第１号被保険者というのは、６５歳以上ということになります。","id":"exchange-059"},{"speaker":"やなぎさわ委員","kind":"質問","question":"恐らく第１号被保険者が多かったりする理由は、私が思うに、開催の日にちというか時間帯とかですよね。大体というか、ほぼ全て平日の午後に開催されているではないですか。そうすると、普通に働かれているけれども品川区の介護保険制度とかに興味があったり、発言をいろいろ中に入ってしたいなという方が、参加できないですよね。そういった取組とかはいかがでしょうか。","respondent":"菅野高齢者福祉課長","answer":"もちろん、今、やなぎさわ委員がおっしゃったみたい、公募区民の方が第１号、６５歳以上の方が多いのは、ふだんお仕事をされている方がなかなか入れないような、そういう会議体の時間帯になっているのではないかというところで、そのあたりのところは。","id":"exchange-060"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"先ほど人材不足で介護提供ができないまでには至っていないというご見解でした。これは一般質問でおぎの委員も質問されていたのですが、外国人の採用に向けた支援というところは、大体こういった介護人材の文言には必ずと言っていいほど品川区では入っているのですが、これも変わらず積極的に採用支援は行っていくような取組の理解でよろしいですか。","respondent":"菅野高齢者福祉課長","answer":"例えば迎える側の施設も、最初はすごく抵抗があったりしたのですけれども、ある施設の施設長が外国人の方を採用すると踏み切ったときに、やはりすごくきめ細やかに真面目に働いてくれるという実態があって、ほかの施設も、うちも。","id":"exchange-061"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"むしろインバウンドで外国人の方がたくさん来るような、少し賃金の安い国というか、物価の安い国にどんどんなってしまっていっているので、当然、そういった来てくれる方がいるならというのはあるのですが、そこだけに頼らずに、やはり国内のそういった人材確保、人材育成をぜひ積極的に、そこを第一に、どうしてもというような次の手段だなというふうには。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-062"},{"speaker":"鈴木委員","kind":"質問・要望","question":"認知症の対応なども、そういうことで豊かに進めていただきたいと思うのですが、そこのところは、やはりこれからも在宅支援でずっと行くということなのか、私は在宅支援にあとの２つの職種を入れていただければ、そこで地域包括という看板もつくれるし、地域包括に変わることができるわけですから、その配置さえしていただければできると思うので、ぜひ在宅介護支援センターに保健師や社会福祉士を配置して。","respondent":"菅野高齢者福祉課長","answer":"委員ご指摘の保健師の人数が規定より不足しているのではないかとか、そういった課題を抱えているところもあるのかもしれないのですけれども、何よりも２０か所の各在宅介護支援センターと高齢者福祉課、オンラインで情報も結んでおりまして。","id":"exchange-063"},{"speaker":"鈴木委員","kind":"質問・要望","question":"保険料は１７ページ、１８ページのところで、今、６,１００円のところが７,１００円程度で推計ということで、実際は６,５００円から７,０００円程度を見込んでいますということで、この７,１００円というと、１,０００円も上がってしまうのかというすごい値上げなのですけれども、６,５００円から７,０００円というのもどうなっていくのかというところなのですが、少し伺いたいのは。","respondent":"菅野高齢者福祉課長","answer":"というのは、今後のこの計画の概要のところも見ていただきますと、第九期が６,５００円から７,０００円になっているのですが、今後２０３０年、２０４０年を見ると、高齢者の数がどんどん増えていくところもありますので、今、安ければいいのかという部分も。","id":"exchange-064"},{"speaker":"鈴木委員","kind":"質問","question":"基金をどれだけ残すかというのはどう考えるかということだと思うのですが、この基金というのは６５歳以上の人の保険料そのものですよね。それなので、やはり６５歳以上の人に返せるときに返すべきものだと思うのです。これは本当に積立てておいて自由に使うというよりは、国の方針としてもそういう方向が出されていると思います。先ほど伺った市町村特別給付のことも、ご答弁をお願いしたいと思います。","respondent":"菅野高齢者福祉課長","answer":"例えば要支援者夜間対応サービスや通院等外出介助サービス、そして、指定地域密着型ケアハウスサービス、こちらについてが市町村特別給付というところで、ここについてはやはり委員ご指摘のとおり第１号被保険者の保険料を財源としておりますので。","id":"exchange-065"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それなので、私は、この市町村特別給付は一般財源でぜひやっていただきたいということで、求めておきたいと思います。だから、そういう形で、６５歳以上の人の保険料がこれだけどんどん高くなって、本当に介護保険が始まったところからすると約２倍になるわけですから、そういうところでは、保険料を引き上げる、丸々保険料だけで賄う市町村特別給付は、ぜひ一般財源に変えていただきたいと思います。","respondent":"菅野高齢者福祉課長","answer":"ちなみに区では大体３.５％から３.７％前後で近年推移しております。こちらにつきましては、全国の市町村会議等におきまして、５％一律でというところは毎年要求しているところです。","id":"exchange-066"},{"speaker":"鈴木委員","kind":"質問・要望","question":"ぜひそれを強力に求めていただきたいと思います。もう２５％丸々来て、その上にプラス５％としていただけるようにということで、国にも引き続いて強力に求めてください。それなので、これはぜひもっと多段階にして、それで、応能負担というところでしていただきたいと思うのですが、今の段階での品川区の考えを伺えたらと思います。区の考えをお願いしたいと思います。","respondent":"菅野高齢者福祉課長","answer":"その部分も踏まえまして、区としては１４段階で、前回、前々回は段階の設定をしているのですけれども、そこについての見直しも含めて、今検討を図っているところです。","id":"exchange-067"},{"speaker":"鈴木委員","kind":"質問・要望","question":"分かりました。それなので、品川区で言えば６,１００円の保険料が、渋谷区で言えば４,７６８円としているのです。今の段階で品川区は一番高額所得者に安い保険料になっていますので、これは他区の状況も見ながら、ぜひ多段階化、応能負担を進めていただきたいと要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-068"},{"speaker":"おぎの委員","kind":"質問・要望","question":"質疑ではなく、これ、要望というか意見なのですが、先ほどやなぎさわ委員が言っていました１３ページの外国人の採用の件の話ですが、こちら、私、２０１１年の震災の直前まで台湾におりまして、台湾は、早くから介護に関して外国人人材の導入に踏み切っておりました。以上、意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-069"}]},{"id":"topic-04","title":"後期高齢者医療制度令和６・７年度保険料率の改定","agenda":"後期高齢者医療制度令和６・７年度保険料率の改定","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"少し今の説明でよく分からないところがあったので、何点か伺いたいのですが、一番左側の（６）の剰余金ですが、２５０億円を剰余金として見込んだというのは、剰余金の分だけは保険料の算定の中に入れて安くなるという考え方でいいのでしょうか。それから、右側の所得割のところが、旧ただし書き所得の５８万円以下と５８万円超というところで、２段階になったというのが今回変わったところなのでしょうか。","respondent":"池田国保医療年金課長","answer":"剰余金につきましては、前回、令和４・５年度の算定の際の１８７億円を見込んで計算をさせていただいたところは、今、令和６・７年度については２５０億円を見込んだということになっています。","id":"exchange-070"},{"speaker":"鈴木委員","kind":"質問","question":"前の資料を見ると、１人当たりの平均保険料額というので見ると、令和４・５年のときは前の期に比べてプラス３,７８９円、その前は３,９２６円、その前は１,６３５円となっているのですが、そのことからすると、何かこの８,９３２円というのは、この８０万円とか、それぞれに合わせてというところでの資料を持ち合わせていないのでよく分からないのですが。","respondent":"池田国保医療年金課長","answer":"委員がお話しされた金額でなく、私たちは率でお話しをさせていただいたところで、率としては、令和４・５年の保険料を決める際が一番高く上がっているところではあります。額としてというところになるかと思うのですけれども、額につきましても……。少し待ってください。","id":"exchange-071"}]},{"id":"topic-05","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"こしば副委員長","kind":"質問","question":"八尾市の例を出してしまうのですけれども、八尾市ですと、各部署といいますか、窓口のところに、区民の方のちょっとした変化といいますか、言葉もそうでしょうけれども、そういった少しの変化に気づけるようなチェックリストというのを設けていまして、それがなかなかより具体的に書かれていまして、そういったものを品川区で取り組まれているのかどうかも踏まえて教えてもらえますか。","respondent":"坂野保健予防課長","answer":"やはり眠れていないというのは非常に危険なサインということで、そこは確認してくださいねというのは、お話はしているところです。","id":"exchange-072"},{"speaker":"おぎの委員","kind":"質問","question":"こちらの心の健康相談訪問事業のところですが、電話相談の件数が思ったよりすごく多いなというのがありまして、この電話を受けている職員の方というのは大体何人ぐらいで、１回の通話はどれくらいお話しされているのでしょうか。","respondent":"榎本荏原保健センター所長","answer":"職員の数は、保健センターにおります保健師と心理職、それから精神保健相談員という者がおりますが、その職種が中心になって、こころの健康相談のときは対応しております。","id":"exchange-073"},{"speaker":"おぎの委員","kind":"意見","question":"予想していたよりも非常に多い件数で、驚いています。顔が見えない相手にでもお話を本当に聞いてほしいとか、最後の訴える場になっているかもしれないので、本当に丁寧に当たっていただいているのだなというのが分かりました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-074"},{"speaker":"ひがし委員","kind":"質問・要望","question":"前回の行政視察のときも思いましたし、今回、認知症をテーマに少し調べ物をしているときとかもすごく思ったのですが、何かキャラクターというのはすごくアイキャッチとしていいなと思っていて、ほかの区だと、例えば八尾市だときくにゃんだったり、あと奈良のキャラクター、ラブキー君とか、何かそれぞれ自殺の対策に力を入れていますといって、キャラクターで結構統一してポスターとかに入れることで。","respondent":"坂野保健予防課長","answer":"実は自殺対策で作っているカレンダーには、シナモロールですか、あれを使っております。ただ、キャラクターの権利の関係があって、なかなかほかに横展開ができていない部分があるので、また何かありましたら勉強していきたいなと思います。","id":"exchange-075"},{"speaker":"ひがし委員","kind":"意見","question":"品川区の自殺対策のホームページを見てみると、この黒の猫ちゃんがちょこちょこと出てくるので、何かこれがキャラクターなのかなと思ったり、サイトとかに飛ぶとところどころで出てくるので、これがキャラクターなのかなと思うけれども、特に名前も出てきていないし、ほかのところを見ると、こころの電話帳とか対策のマニュアルとかには載ってこないので、統一感としてはやはり何か１個あるといいのかなと。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-076"},{"speaker":"鈴木委員","kind":"質問","question":"精神保健事業のほうでメンタルチームサポート事業について伺いたいのですが、本当に精神の問題を抱えた方というのはすごく多くて、しかもかなり深刻で複雑という方も多いと思うのですが、このメンタルチームサポート事業にどういう形でつながっていくのか伺いたいと思います。その中身についてもう少し教えてください。","respondent":"榎本荏原保健センター所長","answer":"多職種のところですが、保健センターにおります、保健師、心理職、それから精神保健相談員を中心としながら、その対象者の方によりまして、例えばですけれども、退院後支援で入院した後の支援をする場合などは、入院中でしたら病院の主治医と看護師さんと連絡を取って。","id":"exchange-077"},{"speaker":"鈴木委員","kind":"質問","question":"この多職種チームというのは、例えば１か月何回カンファレンスをやるとか、そういう形でというよりは、具体的に事例があったときに集まって、みんなで相談をしながらやりましょうみたいな、そういう形になっているのか、少しそこら辺、何というのですか、本来であれば医療機関につながってほしいなと思いながらもなかなか医療機関につながらなくて。","respondent":"榎本荏原保健センター所長","answer":"先ほどかなり広範囲のいろいろな方の職種というか、連携のところをご説明いたしましたけれども、その場面ではかなり多くの方が集まって会議をやることになりますけれども、中心になっておりますのは、先ほどご質問があった例えば医療機関につながっていない方の場合などは。","id":"exchange-078"},{"speaker":"鈴木委員","kind":"質問","question":"今、訪問看護ステーションも、かなり精神に特化したところでの訪問看護ステーションというのがすごく増えてきていて、訪問看護ステーションから訪問をしていただくことで、うつの方だったり、それから統合失調症で妄想のある方なども、かなり、何というのですか、落ち着くという、そういう対応をしていただいているなと思っているのですが。","respondent":"榎本荏原保健センター所長","answer":"精神に特化した訪問看護ステーションのことがありますが、精神疾患への対応に非常に慣れていらっしゃるというのもありますし、かなり密に連携して支援をしているという状況があります。","id":"exchange-079"},{"speaker":"鈴木委員","kind":"質問・要望","question":"本当に精神で苦しんでいる方というのはたくさんいらっしゃって、そういうところが様々進んできている部分というのがあると思うのですが、そこが、何というのですかね、うまくつながっていないところもあったりするのではないかなという思いがしていまして、そういう点では、こういう事業があるよというところもぜひ周知もしていただきたいと思いますし、この訪問看護ステーションも。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-080"},{"speaker":"筒井委員","kind":"質問","question":"自殺者が今、３０代、４０代の方が増えているということで、そうした年代の方にとっては、インターネットゲートキーパーという手法は非常にいいのかなと考えていますけれども、今、品川区のホームページで少し検索しますと、ＮＰＯ法人ＯＶＡというところが出てきているのですけれども、ここでインターネットゲートキーパー、相談機関のバナー広告を出すというシステムは。","respondent":"坂野保健予防課長","answer":"今、お話があったように、インターネットゲートキーパー事業はＮＰＯ法人のＯＶＡに区が委託をして行っています。そこである程度ご相談が、やり取りができて、それで、これはもう継続的な支援がこの先必要だからと、区のほうに戻ってくるようなケースも何例かあります。","id":"exchange-081"},{"speaker":"筒井委員","kind":"質問","question":"要は相談件数を見ると多いのですけれども、下の表を見ると、躁うつ病とかギャンブル依存とか具体的な診断が出ているのですが、その相談件数の中から、あなたはギャンブル依存症ですよとか躁うつ病ですよという具体的な診断に至るのは、やはりどうしても絞られていくか、具体的な診断に至るケースというのは、どうしても数字的には少なくなるということでよろしいのですか。","respondent":"榎本荏原保健センター所長","answer":"参考資料のほうのこころの健康相談の件数と、一番下のところの専門医による相談のところ。","id":"exchange-082"},{"speaker":"筒井委員","kind":"質問","question":"相談を受けて、その方がお話を聞いていただけたということでご納得されて、それで終わるというケースもあるのですか。","respondent":"榎本荏原保健センター所長","answer":"もちろんその後何かあったらご相談くださいということでお伝えはしますけれども、そういった１回とか２回ぐらい、数回ぐらいで終わる場合もありますし、もうかなり、何年という形でご支援している方もいらっしゃいます。","id":"exchange-083"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"品川区の自殺率については非常に優秀で、品川区の成果が出ているのかなと非常に感心するのですけれども、区で行っている自殺対策は何個かあると思うのですが、その中でこれがすごい、特に効果が出ているなみたいな、そういった実感がもしあるようなものがあればお教えてしていただきたいと思いますが、いかがでしょう。","respondent":"坂野保健予防課長","answer":"逆に、広くに効いてくるであろうというのは、今もやっていますけれども普及啓発事業とかゲートキーパー研修とかは、１つのケースでの効果はそんなに深くはないのかもしれないのですけれども、ただ広い範囲に効いているということで。","id":"exchange-084"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"すみません、約３,０００件、全部回って、その中で夜逃げしている人もいたり、病気とか、あとひきこもりとか、そういったところで様々な困難な事情が複合的にあったりということで、つまりその中に、その先に自殺にもつながるような方もいたというのをそういった調査によって明らかにできたというところで、このお話は非常に、我々委員もそうですし、参加された全員が多分感心したような事例だと思って。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-085"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/424146?Template=document&Id=3678#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":70409,"voices":236}},{"id":"r05-20231128-8","meetingId":"r05-cm11","date":"2023年11月28日","dateIso":"2023-11-28","committee":"建設委員会","time":"午前１０時０８分～午後 ０時０８分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を36件抜き出しています。","topics":[{"id":"topic-01","title":"令和６年１月区営住宅入居者募集","agenda":"令和６年１月区営住宅入居者募集","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"最近の応募状況を伺いたいのと、いつも配布期間と申込み期間がずれているのですけれども、その理由を伺いたいと思います。それで、区営住宅の中で結構空き室があるという話も伺うのですが、今、空き室が何戸あるのか伺います。","respondent":"竹田住宅課長","answer":"最近の倍率です。令和５年７月に実施しました募集では、全体で５０.７倍、令和５年１月実施が４２.２倍、令和４年７月が４７.０倍となっております。","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問","question":"応募倍率が直近で言うと５０倍になっていると。区営住宅のニーズが高いなと感じるところですけれども、そうすると、空き室のところは半年間ずつ、空いたところは全て募集をかけているという捉えでよろしいのでしょうか。","respondent":"竹田住宅課長","answer":"空いたところは全部募集をかけているかということなのですが、例えば、居住者の方がお亡くなりになって、残置物があった場合、相続人の方にお引取りをお願いするのですけれども、それをなかなかしていただけない等々の理由がございまして。","id":"exchange-002"},{"speaker":"のだて委員","kind":"質問・要望","question":"期間についても、郵送が遅れる場合があるということですけれども、受付期間が今回１月２９日ということで、そうすると、応募する方も、そこまで受け取れるのかなと思ってしまう方もいると思いますので、そこはしっかり説明していただくのと、できれば受付期間まで配布をしていただきたいということを要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"西本委員","kind":"質問","question":"そこは空き室になるわけではないですか。それと、募集住宅の９戸なのですけれども、これと空き室との関係がよく分からないです。要は、空いたから募集という話ではないのですか。だから、９戸というのは完全に空いているということなのか、ということは、９戸というのが空き室と理解していいのか、はっきり空き室のことをおっしゃらなかったので、何かその理由があるのかなと思うのですが、いかがでしょうか。","respondent":"竹田住宅課長","answer":"ですから、近々に退去されたものというのは、原状回復が終わっていませんので、１月に入居されるまでに原状回復が終わらない可能性もありますので、そういったものは今回の募集にはかけないで、次回送りにしているというところがあります。","id":"exchange-004"},{"speaker":"西本委員","kind":"質問","question":"分かりました。そうすると、申込みの抽選までに空き室が、ここの募集住宅数には入っていないけれども、入れそうだという場合には、それも加えた形の募集という意味合いでよろしいのでしょうか。","respondent":"竹田住宅課長","answer":"先ほど申し上げたとおり、残置物の問題とか、業者に原状回復費の見積りを取ったところ、こういう金額です、そのうち自己負担は幾らです、区の負担は幾らですということでご案内差し上げるのですが、そちらの金額にご納得いただけないケースとか、様々ありますので。","id":"exchange-005"},{"speaker":"西本委員","kind":"質問","question":"お聞きしたかったのは、残物とかいろいろあって、手続があってと言ったけれども、この申込みにもし間に合えば、その戸数も、例えば１戸でも２戸でも可能だったら、それに加えられるわけではないですか。そういう意味合いでいいのですか。それとも、この段階で９戸しか駄目ということなのか、問題解決できたら、ここに加えることができるのかというところを知りたかったのです。","respondent":"竹田住宅課長","answer":"退去されたお部屋なのですけれども、放置されているお部屋も多いという状況で、例えば今年あった事例ですと、入居者がお亡くなりになっているのですけれども、相続人の方が、私が物置として使っているとご主張されて、そういう趣旨のお部屋ではないですから。","id":"exchange-006"},{"speaker":"西本委員","kind":"質問","question":"質問が悪かったのかもしれません。だから、２１戸についてはまだ時間がかかって、ここには恐らく間に合わないだろうと。そうすると、１戸とか２戸増えれば、競争率が下がるではないですか。１人でも多くの方に入ってほしいから、そういう準備ができた段階で、決まるのが２月ですよね。その間に１戸でも２戸でも入れる可能性があるのだったら、それも加えていきますということでの理解でよろしいですか。","respondent":"中村都市環境部長","answer":"ただ、今回の９戸が１０戸に、１戸２戸増えるかどうかというのは分かりませんが、もし可能であればというところですが、考え方としましては、入居できるのに、ただ単に放置しているといったところはなく、可能な限り入っていただくといった考えで運営しております。","id":"exchange-007"}]},{"id":"topic-02","title":"しながわ水族館リニューアル整備運営準備事業事業者の選定結果","agenda":"しながわ水族館リニューアル整備運営準備事業事業者の選定結果","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"初めに、外部有識者の方の意見書が出されたということで、ぜひこれは資料として出していただきたかったということで、今後は出していただきたいということで要望しておきたいと思います。それで、今回３名、人選をされているということで、この３名を人選された理由を伺いたいと思います。今回、公募して１者しか来なかったということで、区としてはこのことをどのように捉えているのか、伺います。","respondent":"高梨公園課長","answer":"東海先生につきましては、令和２年度に実施したしながわ水族館顧客満足度満点プロジェクトということで、しながわ水族館のこれからの在り方についての検討等でもご尽力をいただいている先生でございまして。","id":"exchange-008"},{"speaker":"のだて委員","kind":"提案","question":"運営準備事業者は、今回、助言・準備をする事業者ということですけれども、選定理由のところに、本委託の受託者として適していると書いてあるのは、そうするとどういうことなのか、伺いたいと思います。今回、それも含めて附帯意見をつけたということで、その附帯意見は、検討していく分についてのことなのかどうかも併せて伺います。","respondent":"高梨公園課長","answer":"得点率６７％の評価といったところですが、一定、比較対象がいない中での採点といったところで、難しい部分が審査会の各委員の中でもあったのかなとは感じているところですけれども、それぞれ委員から、しっかりと区が示しているリニューアルの方向性についての理念であったり。","id":"exchange-009"},{"speaker":"西本委員","kind":"提案","question":"それに対して、選定理由の中で、例えば１個目は、条件に合致した提案内容というのだけれども、この数字を見たら、そうですかと言いたくなるのです。本当は１００％に近い状況が、合致しているというのではないですか。イルカのショーはいつまでやられるのかというのをもう一度確認したいし、代わりになる等のイメージアップをするために、何か提案があったのかというのをお聞きしたいと思います。","respondent":"高梨公園課長","answer":"取組姿勢のところですが、主に当日、提案説明・ヒアリングでの事業者の受け答えの部分で、配点をしていただいたところ、採点をしていただいた部分であると考えています。","id":"exchange-010"},{"speaker":"西本委員","kind":"質問・要望","question":"品川区が取り組んでいるというのは大きなメリットだし、努力の成果だと私は思うので、財政面からすると、運営は厳しいと思いますが、それを起爆剤にして、観光であったりというように広げられるということがありますので、ここだけ考えるのではなくて、ほかの部とも、文化観光のほうとか、一緒に考えていただきたいと思いますので、いい水族館を継続していただくように強くお願いしたいという思いで。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"田中委員","kind":"質問・要望","question":"私も同じような視点からなので、重複を避けながらお伺いしたいと思いますが、まず、公募結果、１者しかなかったということで、本来であれば複数あって比較したかったけれどもというご答弁もありましたが、そもそもの公募要件とか公募条件がどうだったのかとか、あるいは公募の仕方が、ホームページか何かに掲載しただけで、それに対してを求めたのか、全国で水族館は、数もそうあるわけではないので。","respondent":"高梨公園課長","answer":"ご提案のありました、それぞれというか、水族館の事業者に個別に、区からこういったプロポーザルの実施について申し入れたといったことは、行ってございません。","id":"exchange-012"},{"speaker":"田中委員","kind":"提案","question":"審査結果のことについてなのですが、６７％というのは若干低いような印象を持ってしまうところがあるのですが、今回のご提案された内容はこういうことなのですが、例えば、区側から採点の低いものに対して改善を求めるようなことが、先方に伝えられ、受け止めてもらえるのかどうか、その点はいかがでしょうか。","respondent":"高梨公園課長","answer":"現段階におきましては、事業者にそれを伝えてございまして、事業者もしっかりとそれを真摯に受け止めて、今後協議をしてつくり上げていきたいという回答を得ているところです。","id":"exchange-013"},{"speaker":"田中委員","kind":"提案","question":"審査結果のうちの一番下の、提案額の妥当性が、ポイント的には低いと思えるのですけれども、この評価というか、どのようなことなのかというのを確認したいのですが、要は、予算額に対してそれを超える、相当上回るような提案があったから、評価として低いのか、あるいは、予算に対してそこまで至らない、過小の提案だったために、こういう評価になってしまっているのか、そこはいかがなのでしょうか。","respondent":"高梨公園課長","answer":"その予算額に対して、どれだけ低減されたかといったところで評価をしています。ここの部分につきましては、予算とほぼ同額といったところですので、中庸な評価という形で、こういった配点になっているところです。","id":"exchange-014"},{"speaker":"田中委員","kind":"提案","question":"附帯事項の中で、設計費に関わる経費の妥当性云々とありますが、ここで経費をさらに抑える方向で働いてしまうと、逆にそれより上の提案の内容が、質的にとか、量的に下がってしまう可能性も、仮に出てしまったとすると、この採点はもっと下がるようにも感じられてしまうのですが、要は、最小の費用で最大の成果を上げるという、最小の費用だけを求めるだけではなく。","respondent":"高梨公園課長","answer":"附帯意見のほうの経費の妥当性は、同じ経費の妥当性で分かりにくいのですが、こちらにつきましては、区が予算額を示したものではなく、その先、将来にかかる実施設計や工事監理等々の費用については、まだ区が予算額を示していないので、その妥当性については。","id":"exchange-015"},{"speaker":"田中委員","kind":"提案","question":"提案の内容がどうなのかは分かりませんけれども、例えば私の思いとしては、大井競馬場もぜひ品川競馬場にしていただきたいし、これは都議会議員のときから言っていたのですけれども、ホッケー場も大井ホッケー競技場なのですが、つくる前から、あそこは大井ではなくて、住所は八潮ですし、それよりも何よりも、品川ホッケー競技場にしてくれと、ずっと言っていたのですが。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-016"},{"speaker":"西本委員","kind":"提案","question":"すみません、１点だけ確認させてください。事業者の方が、このような提案をしたいのだけれどもといったときに、「それは予算を超えるから難しいです」とはしてほしくないのです。自由度は高められるような予算取りというか、やみくもに予算を上げるべきとは思わないですけれども、いろいろ提案を事業者の方がしてきて、だけれども、それにはやはりお金が必要だ。","respondent":"高梨公園課長","answer":"事業者もやりたいことというところを、コミュニケーションを取りながら、場当たり的な形にならないような形で、計画的に、予算につきましても事業の進捗につきましても、進行していけるように区として取り組んでまいりたいと思います。","id":"exchange-017"},{"speaker":"西本委員","kind":"提案","question":"ぜひ、いろいろな提案があるし、状況も変わっていきますので、柔軟に対応をお願いしたいと思います。それと、これは意見として聞いていただければと思うのですが、多分、指定管理者という形になっていくのだろうと思うのです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-018"},{"speaker":"のだて委員","kind":"質問","question":"すみません、聞き忘れまして。外部有識者の意見書を今回もらっているということですけれども、外部有識者の方を選定委員にしなかった理由を伺いたいと思います。ほかにいろいろ選定する中では、外部有識者の方が入ったりしていると思うのですが、そこを伺いたいのと、ヒアリングを事業者にしたときに、先ほど来、説明の中で少しずつ出ていますけれども、どういったやり取りがあったのかを教えていただければ。","respondent":"高梨公園課長","answer":"これから、リニューアルについても複数年で、我々としましては、出来上がった水族館が、また何十年という形で付き合っていく施設ですので、会社としての取組の意欲、複数年にわたってやるといった体制の部分等、質問が委員から出されたという状況でございました。","id":"exchange-019"},{"speaker":"のだて委員","kind":"質問・要望","question":"最後に意見だけ。今回、これまでのプロポを参考にして、選定委員を選んだということですけれども、この間、指定管理者などで外部委員が入って選定していると思いますので、今後そうした有識者の方を選定委員に入れて、やっていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"まつざわ副委員長","kind":"確認","question":"すみません、確認だけさせてください。公募で１者ということで、その中から、選定も大分ご苦労されたというのは、質疑の中で確認が取れました。それで、事業者が選定されまして、多分、これから基本設計に入ります。","respondent":"高梨公園課長","answer":"そういったところでも意見をいただきますし、これから事業者とも打合せしてまいりますけれども、かねてからご案内をしております区民アイデアの募集であるとか、区民向けの説明会、周辺にお住まいの方々に対しても、また個別の説明も必要でしょうし。","id":"exchange-021"}]},{"id":"topic-03","title":"しながわ区民公園北側ゾーン改修工事（第二期）","agenda":"しながわ区民公園北側ゾーン改修工事（第二期）","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"変更内容の（２）と（３）のところで、これがどこに当たるのかという場所と、これが変更されることでの区民への影響とか、そういったところはあるのかどうか、伺いたいと思います。鉄鋼スラグ状の固い地盤が確認されたということで、それはそのまま残されているということですね。では、ほかの質問に答えていただきたいと思います。","respondent":"高梨公園課長","answer":"変更を行った場所についてですが、（２）の部分はテニスコートの舗装を全部やり替えてあります。舗装を撤去したところ、本来であれば下の部分に砂地というか、土砂があるはずのところに、鉄鋼スラグ状の固い地盤が確認されたといったところです。","id":"exchange-022"},{"speaker":"田中委員","kind":"質問・要望","question":"鉄鋼スラグの関連で、これがあったために排水施設が作れなかったということなのですが、これは完全に埋め戻して、そのままにしてしまった、表面をテニスコートにしたということなのだと思いますが、いわゆる土壌調査といいますか、そういった観点からは、戻したとしても、環境影響上問題はないということも確認した上で、そういう対応を取られたのか、お聞かせいただきたいと思います。","respondent":"高梨公園課長","answer":"テニスコートの舗装を撤去したところ、それが確認されて、テニスコートは、今までも支障もなかったということで、これからも十分問題ないということと、今ご質問のありました、残しても大丈夫かどうかというところは、先ほど申しましたとおり。","id":"exchange-023"}]},{"id":"topic-04","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"まつざわ副委員長","kind":"質問","question":"公園の中で、看板のことだけ一つ言いたいのは、少し前になりますけれども、委員会で言わせていただきましたが、禁止看板を、禁止ではなくて、できる看板と、たしか私もこの足立区のをいいなと思って、質問させてもらったのです。","respondent":"高梨公園課長","answer":"可能な限り説明を尽くしているところではありますが、四六時中迷惑を被っている方の立場としましては、強い表現で一刻も早く迷惑行為をやめてもらいたいという気持ちも分かるところでございまして、そういったところのバランスを見ながら、ただ、そういったご意見の中。","id":"exchange-024"},{"speaker":"西本委員","kind":"質問・要望","question":"少し細かいところから質問といいますか、意見も含めてお願いいたします。それから２つ目が、樹木なのですけれども、これは要望を時々いただくのです。品川区は、樹木に対しては結構しっかりやられていると思っていて、ネームプレート、木の名前というのをなるべく書いてほしいのだと。鳥籠と呼んでいるのでしょうか、あれはいろいろあると思うのです。それについてのお考えを示していただきたいと思います。","respondent":"高梨公園課長","answer":"現在、施設の在り方とか、どういった連携の仕方ができるかというところについて、地域の各団体の方々とお話を進めているところですので、委員からご紹介のありました視点をしっかりと区としても把握し、地域の方々と話合いの中で、いいものがつくれるように。","id":"exchange-025"},{"speaker":"西本委員","kind":"質問・要望","question":"ここからは意見なのですけれども、これから公園整備の計画がなされていくのだろうと思いますが、ここは公表して、皆さんに理解をしていただきたいと思っています。いろいろなお祭りも盛大にあって、いろいろな方々が関わっているという公園ですので、うまく民間の方々とのコラボレーションができるように、交通整理が必要なときには交通整理、けれども出過ぎずということで、ぜひお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"田中委員","kind":"質問・要望","question":"公園をつくりやすい場所と、そうでない場所、近隣に多くある場所と、町会内に一つもないという場所、２７４あってすばらしいのですけれども、その配置の状況も、ぜひ満遍なくといいますか、均等に身近なところに憩いの場として設けていただけるような取組を、ぜひお願いしたいと思います。最近ですと、新たな土地が出たときに、手順としては、企画部がまとめるのでしょうか。","respondent":"高梨公園課長","answer":"その旨の認識は、企画部としても持っていただいているものと考えていますので、基本的には、そういったところの優先度を高めてやっていきたいのですが、品川区内は、適地に適当な広さの土地というのがなかなか出てきづらいといったところですので、数少ないチャンスを。","id":"exchange-027"},{"speaker":"田中委員","kind":"質問・要望","question":"最近、確かに、なかなか新たな土地が見いだせない中でも、目黒線の地下化に伴って、その上部を緑道公園にしたりとか、既に先行して池上線の上部もそうですし、また、今回もＰＦＩの対象になっている東品川海上公園は、東京都の下水道局のポンプ場の上を利用してということでもありますし、勝島運河の先のところも多分そうだと思いますが、そのようにいろいろな併用した中での新たな土地の活用という視点で。","respondent":"高梨公園課長","answer":"もともと再開発は、地域の様々な課題解決を目的に行われているものですので、周辺の道路の拡幅であったり、場合によっては道路の新設であったり、その中で、周辺の状況等を見まして、公園や広場が少ないといったところは。","id":"exchange-028"},{"speaker":"田中委員","kind":"質問・要望","question":"国が入るのかどうか、そこも確認なのですが、要は、特定のために財源が入ってしまったために、公園を一旦はつくったけれども、時代の変化だとか周りの変化に伴って、その土地を別の用途に活用するといったときに、可能かどうかということと、ある場所では財源が公園用地として入ったために、それ以外の多目的のものには活用できない縛りがあるということも、一部にあるかと思うのですが、要は。","respondent":"高梨公園課長","answer":"別の視点、公園という視点で見ますと、都市公園法上の公園として指定をする、もしくは都市計画公園として指定をするということになりますと、そこは一定程度、恒久的に公園として指定をするということですので、例えば都市計画公園を外すということであれば。","id":"exchange-029"},{"speaker":"田中委員","kind":"質問","question":"分かりました。財源的には、多分、区なので、また同じ公園という範疇のものですから、例えばですが、場所によってはこれを入れ替えるといったことも、それがいいのか悪いのか、どういうメリットがあるのかというのも、それぞれの判断はあるのですが、そういう対応というのは可能なのでしょうか。","respondent":"高梨公園課長","answer":"最後、ご質問にありました、財源を入れた児童遊園等の入替えというところについては、それは補助金を所管している国であったり、東京都の判断というところがあろうかと思うので、ここで断定的なことは申し上げられませんけれども、いただいた額に相当するものということで。","id":"exchange-030"},{"speaker":"田中委員","kind":"質問・要望","question":"より有効に活用していただく配置が必要なところは、いろいろな手法を取ってご対応いただくことで、全体的な公園の評価の価値を高めていただけるようにお願いしたいと思います。その辺の今後の、１か所だけではあれなので、全体的な視点ならば考えられなくないというお話が以前あったかと思うのですが、その辺の、まず電源に関しての考え方をお聞かせいただきたい。","respondent":"高梨公園課長","answer":"ただ、今、公園の施設の様々な防災関連の製品の中では、公園の中に公園灯があって、上にソーラーパネルがあって、その電源を、スマホの充電ぐらいの容量であれば発災時に使えるという製品は、実際の遊具メーカー、公園施設メーカー等から出てきているというのがありますので。","id":"exchange-031"},{"speaker":"田中委員","kind":"意見","question":"私は必要だと思いますので、ぜひご検討をお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-032"},{"speaker":"のだて委員","kind":"質問・要望","question":"一つはトイレについて、先ほど洋式化を進めているということで、ぜひそれは進めていただきたいと思います。それと、公園が町会に１か所もないところというところで、優先度を上げてやっているということですので、ぜひそれを私からも、公園がつくれるように進めていっていただきたいと要望しておきたいと思います。","respondent":"高梨公園課長","answer":"バリアフリートイレ、だれでもトイレの中には、介助用ベッドということで、大人の介助ができるようなシートの設置も現在進めているところです。","id":"exchange-033"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ進めていっていただきたいと思います。ボール遊びができる公園は、ぜひ増やしていただけたらと。それと、公園内にあるフットサル場、スケートボード場、ボルダリング場、これは、子どもたちが利用するというところで、ぜひ無料にしていただきたいと思うのですけれども、いかがでしょうか。","respondent":"高梨公園課長","answer":"ただ、例えば砂場に猫であったり、そういったものが入らないように柵がありますけれども、その柵と一体化したような屋根が作れないか等々、遊具メーカーにいろいろとヒアリングしながら、砂場になかなか日陰がなくてという声は公園課でもいただいてありますので。","id":"exchange-034"},{"speaker":"のだて委員","kind":"質問・要望","question":"遊具のところは、砂場の屋根も検討されているということですので、ぜひ進めていただきたいと思いますし、施設の無料化は、ぜひ誰でも利用できるように進めていただきたいと、改めて要望しておきたいと思います。大体町会の方とか、そういうことになってしまうと思うのですが、それをさらに広げて、多くの利用者も含めて、声を聴いていただきたいと思いますが、いかがでしょうか。","respondent":"高梨公園課長","answer":"ただ、１本も切らないのかどうかということにつきましては、提案の内容とか、また、中には古い樹木等もありますので、そういったところを総合的に勘案しながら、樹木等の対応については取り組んでまいりたいと考えています。","id":"exchange-035"},{"speaker":"のだて委員","kind":"質問・要望","question":"それと、面積としては、最大ですけれども２,０００m2余ということで、なかなかの広さだなと。そうなると、樹木の伐採なども出てきますし、これまでの公園の利用ができなくなってしまうということにもなりかねないかなと思いますので、そういったことも考慮いただきたいということで、これは要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/216259?Template=document&Id=4396#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":38046,"voices":98}},{"id":"r05-20231128-9","meetingId":"r05-cm11","date":"2023年11月28日","dateIso":"2023-11-28","committee":"文教委員会","time":"午前１０時０７分～午後 ２時３２分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を62件抜き出しています。","topics":[{"id":"topic-01","title":"第１０１号議案 学校教育職員の給与に関する条例の一部を改正する条例、(2)第１０２号議案 幼稚園教育職員の給与に関する条例の一部を改正する条例の２議案","agenda":"第１０１号議案 学校教育職員の給与に関する条例の一部を改正する条例、(2)第１０２号議案 幼稚園教育職員の給与に関する条例の一部を改正する条例の２議案","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"勤勉手当というのはどういう手当なのか、改めてご説明いただきたいのと、あと今回、一般職の特別給の改正というのは、全て勤勉手当に割り当てるということでしたけれども、その理由ももう少し伺いたいと思います。","respondent":"中谷指導課長","answer":"今回、一般職員につきまして勤勉手当に割り当てるというところですけれども、こちらは、民間の支給状況と比較というところにおいて割り当てるというところで、一般職員は勤勉手当に割り当てるというような結論となったものです。","id":"exchange-001"}]},{"id":"topic-02","title":"第３回～第５回品川区学事制度審議会の実施報告","agenda":"第３回～第５回品川区学事制度審議会の実施報告","exchanges":[{"speaker":"安藤委員","kind":"確認","question":"前提として、パブリックコメント前の文教委員会の報告だと思うのですけれども、パブリックコメントにかける内容が全く示されていないというところで、審議会の内容も確認しようと思ったのですけれども、第３回までしかホームページに出ていない。議事録要旨もまだアップされていないということで、どうなのかという。議会を軽視していると言われても仕方がないと思うのですけれども、いかがでしょうか。","respondent":"柏木学務課長","answer":"パブリックコメントですが、中間答申については現在、最終調整をしているというところで、文言の表現の修正等を今実際行っているところですので、現段階ではお示しできないです。","id":"exchange-002"},{"speaker":"安藤委員","kind":"確認","question":"それで、「検討が必要となる学校の再確認」というような文言がありますけれども、検討が必要となる学校とはどこなのでしょうか、伺いたいと思います。それと、中間答申の案を作成するに当たって、当該学校の学区の地域からの声や意見はどのように聞いたのでしょうか、伺いたいと思います。","respondent":"柏木学務課長","answer":"それと、地域の意見聴取ですが、メンバーの委員の中に地域の代表等が入ってありますので、そちらから意見等はいただいてあります。","id":"exchange-003"},{"speaker":"安藤委員","kind":"質問","question":"となると、中間答申というものに行く中には、検討が必要となる学校の名前というのは一切入っていないということでよろしいのか、伺いたいと思います。明かさない以上は、検討が必要な学校の地域の意見を聞いているかどうかも分からないということになってしまうのですけれども、それでいいのでしょうか、伺いたいと思います。","respondent":"柏木学務課長","answer":"答申に具体的な学校名が出るかですが、学校ごとに学級数の状況については資料として出す予定です。それと、地域等の意見等です。","id":"exchange-004"},{"speaker":"安藤委員","kind":"質問","question":"結局、前回の資料ですと、この後８回なのです。そしてもう一つは、どうやって具体的に影響がある地域の方の声を伺うのですか。伺うつもりがあるのでしょうかというふうに私は思うのですけれども、あまりに不十分といいますか、それだと進め方としても問題があるのではないですか。地域から相当、ハレーションが起こるのではないでしょうか。どうでしょうか。","respondent":"柏木学務課長","answer":"それと、地域の声ですが、こちらも一部、繰り返しになりますけれども、審議会で、地域の代表等も入っていますので、そこで受けてあります。最終的な答申を受けまして制度設計をするときには、また個別の地域等とはお話をさせていただきたいと考えています。","id":"exchange-005"},{"speaker":"安藤委員","kind":"確認","question":"伺いたいのは、つまり中間答申のみならず、答申にも、ではどこの学校をこういうふうにしますという学校の変更案が出てこないということなのか、確認させてください。それと併せて、第２回では委員から、学校の新設も含めて検討するのかという質問が出ていたのですけれども、私も必要な検討材料の一つなのではないかと思うのですけれども、検討の俎上には上ったのかどうかも併せて伺います。","respondent":"柏木学務課長","answer":"答申に個別的な学校の具体策というのが出るのかという、こちらも繰り返しになりますが、区全体としての、こういうときにはこういう方策等を検討したらどうかということですので、個別的にこの学校を答申でこうしなさいというものは出てこないと考えています。","id":"exchange-006"},{"speaker":"安藤委員","kind":"質問","question":"だから、結局、答申にもそういうことを書かないで、最後、教育委員会の任意みたいな感じになってしまっているようにしか聞こえないので、それは私は進め方としては、これだけ大きな影響を受ける地域にとっても、地域コミュニティの核の学校なわけですからどうなのかと、私は問題があるのではないかと思います。それは埼玉県の話だったのですけれども、どのような意見だったのでしょうか。","respondent":"柏木学務課長","answer":"１つ目、再開発の抑制等の件ですが、委員からある自治体を例にして、そういうことは品川区で可能かというお話は、意見としては出てあります。それと、中間答申の説明会ですが、実施する予定はございません。","id":"exchange-007"},{"speaker":"安藤委員","kind":"質問","question":"なぜ実施する予定がないのかというのを教えてもらいたいのと、あと私は先ほど、まちづくりの点では、そういう意見が出たわけではないですか。やはり教育環境に直結する問題だから言っているわけです。だから私は、他人事ではないのではないですかと言ったので、そこについても教育委員会のお考えを伺いたいと思います。","respondent":"柏木学務課長","answer":"説明会の件ですけれども、中間答申は区全体のことで分かりやすく示していますので、ご覧いただければ、説明会等なくてもご理解いただけるのではないか、ご意見も寄せられるのではないかと考えています。","id":"exchange-008"},{"speaker":"ゆきた委員","kind":"質問","question":"令和６年度当初から、通学区域を具体的にどう設計していくか進めていくということと、令和７年度から新制度の適用の開始を目指すことの２つが示されたと思いますが、ここでお聞きしたいのですが、よく地域からの声で上がっているのが、例えばなのですけれども、勝島に住んでいる方々が、どうして八潮学園ではなくて。","respondent":"柏木学務課長","answer":"区民の声の反映ですが、すぐできるもの、できないものが、正直ありますので、そういうご意見をいただいているということについては、いろいろな場でその部分も含めて検討し、区民の声等には回答させていただいているところですが、正直、通学区域を変更するというのは。","id":"exchange-009"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"私たち生活者ネットワークとしてはずっと、パブリックコメントがあったら、もう近隣の方には、パブリックコメントがあるから、ぜひ区民の声として出してくださいとお伝えしているのです。傍聴もしていますので、大体これは合っているということも判断できるのですけれども、学事制度審議会について、要旨であって発言録にはならないという理由が何かあったら教えていただきたいと思います。","respondent":"柏木学務課長","answer":"発言録等の公表ですが、発言録ですと、発言された方が特定されてしまうという部分で、審議で自由濶達なご意見等を本当に今いただいているところですので、そういう部分が制限されてしまうおそれがありますので、現状では発言録については公表する予定はございません。","id":"exchange-010"},{"speaker":"吉田副委員長","kind":"確認","question":"それを特定しない方法は幾らでもあると思いますし、障害者のほうはどうでしたっけ。だから時間がかかるので、やむを得ないと思うのですけれども、そういうことも一般的には、インターネット上の公開でなくても、公式な議事録・発言録として一般的に公開する場合には、発言者の確認は必ず取るはずです。そういう形を教育委員会事務局として取ることは可能だと思うのですが、いかがでしょうか。","respondent":"柏木学務課長","answer":"発言録ですが、正直、中で、本当に具体的に自分のお住まいの地域等を含めての発言等が結構多くありますので、委員Ａ、Ｂにしたとしても、分かる人には、この人だというのが分かってしまう、個人が特定されてしまうというおそれが、審議会の運営を見ていましてもありますので。","id":"exchange-011"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"やはり、それぐらいは発言には責任を持っていただきたいと思いますし、できるだけ、一般的にもう、すぐ個人が特定されてしまうような表現は確かにいかがなものかと思いますけれども、その辺は工夫をしていただいて、こういう発言ということで発表しますということを確認していただいて、ここについては、このとき言い過ぎてしまったから直してくださいなどというのはありかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"}]},{"id":"topic-03","title":"区立学校におけるいじめの重大事態の発生状況","agenda":"区立学校におけるいじめの重大事態の発生状況","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"それを求めた上で、同時にここまで来ると、対症療法だけではなく、根本原因にも目を向けた抜本対策も必要なのではないかと思います。伺いますけれども、品川区教育委員会は、なぜこのようにいじめの重大事態が頻発すると考えているのか伺いたいと思います。根本には、子どもたちのストレスの高まり、学校が楽しくない、つらいということがあるのではないかと思うのですけれども、伺いたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"ご指摘いただいた点につきましては、教育委員会も真摯に受け止めて取り組んでいるところですので、今後も引き続き、いじめの予防や、万が一いじめがあったときには適切に認知して早期対応を行っていくということを、しっかりと実施してまいりたいという考えです。","id":"exchange-013"},{"speaker":"安藤委員","kind":"質問","question":"私は、今のご説明を聞いても、子どもが、いじめへの理解が仮にされたとしても、それで、では子どもがいじめに走らなくなるか。だから、私が伺ったのはあれなのです。ストレスなのではないですか。子どもがすごく今、追い詰められている。そういうのがあるのではないかと思うのですけれども、そこについては、いじめとの関連性について、どのように考えているのでしょうか。伺いたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"そうしたストレスをキャッチしたところに、教員がどうアプローチしていくのか。教員だけではなくて、スクールカウンセラーや、我々の組織にいるＨＥＡＲＴＳ等も含めて、そうした子ども一人一人の支援というものに努めてまいりたいと考えています。","id":"exchange-014"},{"speaker":"安藤委員","kind":"質問","question":"だから私は、いよいよそういうところに目を向けて、自分たちが子どもたちを追い詰めているという自覚を品川区教育委員会は持たなくてはいけないと思っているのですけれども、そういう点でどうでしょうか。先ほど、自らの教育施策が子どもたちのストレスの１つの要因であることは理解するというお話でしたけれども、やはり加速させているという自覚はあるのでしょうか、ないのでしょうか。","respondent":"丸谷教育総合支援センター長","answer":"そういったところからも、学校教育は少しずつ変わっているところですので、それがストレスを加速させているとは考えてはございません。","id":"exchange-015"},{"speaker":"安藤委員","kind":"質問・要望","question":"論争はあると思うのですけれども、私はもう少し自分たちの、これは国連・子どもの権利委員会からも、日本の教育は競争し過ぎると毎年指摘されているわけですから、それで、その先頭に立ってきたのが品川区の教育なのですから、その自覚を持っていただきたいと私は強く思います。","respondent":"丸谷教育総合支援センター長","answer":"市民科の例えばスチューデント・シティといったところの様子を見ると、子どもたちは本当に生き生きと活動していますし、そういった取組をしっかりと、根差していく、継続させていきながら、子どもたちにとっての学びの充実を図り、発見することが楽しい。","id":"exchange-016"},{"speaker":"ゆきた委員","kind":"質問","question":"現在、いじめの重大事態が６件あると報告を受けています。昨日、品川区のいじめ防止対策推進条例の一部を改正する議案で、いじめ対策委員会に臨時委員を設置できるようになると審議がされましたが、現在の品川区のいじめ対策委員会は、設置が５名以内で、４名で構成されていると聞いていますが、今現在、この６件の重大事態について４名で対応されているとの認識でよろしいでしょうか。","respondent":"丸谷教育総合支援センター長","answer":"本体に対して諮問をしたところなのですけれども、今後この条例が改正されれば臨時委員を設けることができますので、この６件についてどう割り振っていくかというところは、今後、円滑に調査が進むように検討していきたいと考えております。","id":"exchange-017"},{"speaker":"ゆきた委員","kind":"質問","question":"今後は臨時委員も設置されていくと思われますが、条例にのっとることももちろんですが、公布されるまでの間の継ぎ目の期間、この間の期間の暫定的な措置があるのかないのかについても教えていただければと思います。","respondent":"丸谷教育総合支援センター長","answer":"条例が公布されるまでの期間ですけれども、調査の方針や、調査結果をいつまでに出せるかというところの検討は進めていきながら、円滑に引継ぎ、つなぎができるように努めてまいります。","id":"exchange-018"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"それには、私は数字にあまりとらわれてほしくなくて、どうしても件数が出てしまうと、いろいろな方面から、そんなに品川区はあるのかなどと、もちろん言われることもあるのだけれども、ただ、そこに今とらわれてしまうと、解決できるものもできなくなってしまうと私は思うので、ぜひそこは、今この時期は、そうやって本当に一生懸命、洗い出しているからこそ浮き彫りになってきて。","respondent":"丸谷教育総合支援センター長","answer":"そこは、件数などにとらわれることなく、しっかりと一人一人の、被害に遭った児童・生徒、加害の児童・生徒に対して適切に対応していくという考えで取り組んでまいりたいと考えております。","id":"exchange-019"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"ぜひリアルなものを教えてくれ」という気持ちを示すことによって、学校側もリアルなものを提出しやすくなる環境になると思うので、その環境づくりを、ぜひつくっていただきたいと思いますし、ストレスの部分もそうで、まさに各子どもたちがいろいろな考えを持って、多分、いろいろなストレスの発散方法が、昔と違って特にそれぞれ違うのかと思うので、そこはある意味、スポーツもそうだし、昨日。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"せお委員","kind":"質問・要望","question":"この２件なのですけれども、お伝えできる範囲でいいのですけれども、報告までの経路というか、何というんですか、例えばＨＥＡＲＴＳを挟んでの教育委員会なのかとか、学校から直接来たのかという、そういうところをお話しできる範囲で教えていただきたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"いずれも、２号、いじめに遭って不登校になったケースということで、いじめの報告と併せて不登校の報告が教育委員会に上がってきます。","id":"exchange-021"},{"speaker":"せお委員","kind":"質問・要望","question":"今のやり方がもしかしたら正しいかもしれませんし、件数が上がってきて、そういったところもぜひ一緒に検証していただきたいというところを要望します。本当にすばらしい言葉がいっぱいあったのですけれども。正直、支援学級でいろいろな体験をさせていただいているのです。体験の授業がすごく多いという。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"高橋（し）委員","kind":"質問","question":"それで、その調査の結果、どういう対応を教育委員会および現場がしていくというところで、今の区の姿勢で、さらに真価が問われるので、ぜひしっかりとというか、応援するという意味を含めて、頑張ってと言うと失礼ですけれども、きちんとしていただけるとありがたいということを、まずお話しします。お尋ねしたいことは、学校種のところで、義務教育学校の前期か後期かを書いていないのはなぜなのかと。","respondent":"丸谷教育総合支援センター長","answer":"そういった児童・生徒に対しては、しっかりとした心のケアが必要だと考えますので、スクールカウンセラーとの連携やＨＥＡＲＴＳの支援等も含めて、継続的に行っていきたいと考えております。","id":"exchange-023"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"さっきのいじめを見てということなのですけれども、特に、いじめを経験したお子さんが、１年生のときに解決しました。それは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"吉田副委員長","kind":"質問","question":"私から伺いたいのは、例えばいじめの態様の分類については、これが文科省の文部科学大臣決定から、この文言をと、そのまま書かれているようなのですけれども、具体的にはもう少し、何というか、細かいいろいろな個別のケースがあると思うのですけれども、そういうことが報告されているのを、今日、委員会に向けた報告のためにこのようにまとめられたという理解でよろしいのでしょうか。","respondent":"丸谷教育総合支援センター長","answer":"そうしたところでの、８つ示された中でのものということで、実際にはもう少し、いじめの事案としては、絞った形での報告も上がっていますし、それを基に調査を行っていくということになっています。","id":"exchange-025"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"報告が必要ですので、報告のために、書式にのっとった形で報告されているということで理解いたしました。それで、先ほどからも、原因ということであれば、１つはやはり承認欲求というのは、いろいろな意味で、いじめというのは、ある意味で承認欲求が悪い方向に働いてしまった事例なのではないかというのを感じることがあります。もし何か見解があれば伺いたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"これはいじめに当たるという意識がというところで言うと、児童・生徒の理解というところにつながっていくと思いますので、そういうことも認識を深められるようないじめ予防プログラムを検討しておるところですので、引き続き、教育委員会として努めてまいりたいと考えております。","id":"exchange-026"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"最後に、本当におっしゃるとおりだと思いますので、それは現場の先生方にとってはまた難しい対応ということになってしまうのかもしれませんけれども、その辺については、ぜひよろしくお願いいたします。ですので、そこでやはり、まずは本人の言い分を聞くという。でも、まずは本人の言い分を徹底的に受け止めるということは、ぜひ教員の方には徹底していただきたいと思います。これは要望でとどめます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"あまりにも保護者が学校に頼り過ぎという部分もあると私は思うのです。それは、シングルだろうが、いろいろそれぞれ家庭の事情はあると思うのですけれども、やはり一番は保護者が寄り添うというのが、加害者・被害者に対しても、絶対それはもう最終的には家庭教育というのが一番だと私は思っているので、もし、ほかに何かお考えがあれば教えていただきたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"やはり、いじめの定義の共通認識を、子どもも教員も保護者も、教育委員会は当然ですけれども、共通理解をした上で議論していかないと、どうしても話がずれてしまったり、かけ違ってしまったりしてしまいますので、そういった家庭への啓発ということも。","id":"exchange-028"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ぜひ家庭への啓発は、改めて私からお願い、要望させていただきたいと思いますので、もう本当に当然、教育委員会の皆さん、そして学校側の現場の先生方も、もう一回、繰り返しになりますけれども、本来ならば教育の場でいじめというのはあってはならないのですけれども、これは大小なりとも、今後、根絶というのはなかなか難しいと思いますけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"高橋（し）委員","kind":"意見","question":"最後に一言。今、ほかの委員の方から、先生が当てにならないというお話があったのですけれども、保護者の方の考えなのか、委員の考えかはあれですけれども、それは考え方なので、そういうのはいいのですけれども、それに対して教育委員会としてどうかというのはお答えいただいたほうがいいと思ったので、お尋ねします。","respondent":"丸谷教育総合支援センター長","answer":"対応が適切ではなかった場合に、こちらから指導・助言、校長・管理職からも、その教員に対して指導していただいて、保護者との関係を修復するような形を取らせていただいているところです。","id":"exchange-030"}]},{"id":"topic-04","title":"ヤングケアラー調査の実施結果について（速報）","agenda":"ヤングケアラー調査の実施結果について（速報）","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"大変重要な資料だと思って聞いていましたけれども、特に悩みなど相談できない方や、聞いてほしいという方が多いというのは、本当に深刻というか、何とかしてあげたいと強く思う内容だと思いました。２点伺うのですけれども、まず調査のやり方なのですけれども、送付して、どんなやり方で、どういうふうに回収したのでしょうか。","respondent":"染谷子ども家庭支援センター長","answer":"今後のスケジュールというお話ですけれども、まず、一部並行してという作業にはなってまいりますが、今回出ているアンケートの結果を、次年度の予算にも支援策として反映していきたいと考えているところと。","id":"exchange-031"},{"speaker":"安藤委員","kind":"質問","question":"すみません。高校生のほうですけれども、これは全ての区内在住の高校生の数かということと、小・中学校は、区立校についてはそういうことだということなのですけれども、タブレット以外にも何か回答の仕方というのはあったのかということと、区立小・中学校ではない子というのはどうしたのかを教えてください。","respondent":"染谷子ども家庭支援センター長","answer":"私立の小学校に通われているお子さんにつきましては、直接ご自宅にご案内を郵送させていただいてご回答いただいているという状況です。","id":"exchange-032"},{"speaker":"ゆきた委員","kind":"質問","question":"アンケートの結果から、家事援助の訪問支援や配食サービス、学習支援が必要なのだという実態が分かってきていますが、８月の文教委員会では、今年度はヤングケアラーについて既に予算化されているというお話もあったと思います。これからだと思われますが、具体的なところで決まっている事業等など、紹介できる範囲で教えてもらえればと思います。","respondent":"染谷子ども家庭支援センター長","answer":"そのほか、今回、実施を予定しているものの中で１つ、ピアサポートといいますか、当事者同士が集って、悩みのお話合いができるとか、区に配置しておりますヤングケアラーコーディネーターも併せて、そういったところでお話をしていくと。","id":"exchange-033"},{"speaker":"ゆきた委員","kind":"意見","question":"このアンケートも引き続き継続していきながら、この結果について反映できるような事業の展開を、ぜひともよろしくお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-034"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"そこの子たちに支援が必要であって、ほかの子たちにはどちらかというと、それが駄目というよりも、逆にお手伝いをしてあげてというか、例えばきょうだいの面倒を見てあげてみたいな方向に、うまくつなげていかないと、せっかくこうやって一生懸命、区で今やっていただいているので、もったいなくなってしまうので、そこはぜひ気をつけて取り組んでいただきたいと思いますけれども。","respondent":"染谷子ども家庭支援センター長","answer":"今お話しいただきましたとおり、まさにお手伝いと、ヤングケアラーというケア負担が実際に発生しているようなところの境は非常に重要なところで、本来、子どもとして生活していく権利が侵害されているような状況があれば、まさに支援の対象として。","id":"exchange-035"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"ぜひ、よろしくお願いします。実はケアをされている子も、その経験が将来生かされることも十分あるし、これはもう本当に、だから私が一番初めに言った、何でもかんでも駄目という、ヤングケアラー、イコール、よくないのだというのだけは、考えから取っ払っていただいて、ぜひいい方向に進んでいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"高橋（し）委員","kind":"質問","question":"ご説明ありがとうございました。貴重な調査で、回答者の回答率など、もう少し高いと、実態にもう少し近づいたのではないかと思いますけれども、このパーセンテージでこれだけということは、数字的に言うと、きっともっといらっしゃるのではないかというところがあります。ご質問は、この内容は、学校、特に区立小学校、中学校にどのようにして伝わるのでしょうか。","respondent":"染谷子ども家庭支援センター長","answer":"学校の教員の皆様にも、ぜひこちらを共有させていただきたいと思いますので、教育委員会事務局と相談をさせていただければと思います。","id":"exchange-037"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"それで、何が言いたいかというと、だれかに話したことがありますかというのは、きっと小学生だと先生などが多いのかという気もしますので、中学生もそういう部分があると思うのですけれども、それで、してほしいところに、話を聞いてほしいのと、あと、家族のことについて話を聞いてほしいというのが小学生にあり、中学生なども同じで、特に中学生は、勉強を教えてほしいというところもあるので。","respondent":"丸谷教育総合支援センター長","answer":"そうした上で、今回の調査結果につきまして、自校にいる子どもたちはどうなのかというところを、アンテナを高く張っていただいて、該当者がいるようでしたら、子ども家庭支援センターとも連携をしながら、その子のケアに努めていきたいということと、あとは学習支援であったり。","id":"exchange-038"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"回答率がこのぐらいのパーセンテージで、小学校だと１学年にコンスタントに１人いる。中学校だと、学校全体で１３、４、５人だから、１学年には４、５人いるということは、１クラスに１人いるという。単純な計算ですけれども、そういうところから、やはり、今お話があったような指導をきめ細かくしていただきたいと思います。これは要望で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"せお委員","kind":"質問","question":"今までも議論というか話がありますけれども、やはり感じ方も様々で、「つらい」と感じるときはありますかで、「まったくない」という人も一番多いですし、「いつもある」という方もいらっしゃるので、感じ方も様々だし、あと、その要因も様々で、かなり支援メニューというのは様々準備しないと、それは支援にならないのかというのは感じているところで、今では、私は把握していないのですけれども、今。","respondent":"染谷子ども家庭支援センター長","answer":"あと在宅介護支援センターにいらっしゃるケアマネジャーの方たちを対象とした研修なども実施しておりまして、ご自宅を見られるときに、ヤングケアラーという視点を１つ持って見ていただくというところについても、研修・啓発を進めているところです。","id":"exchange-040"},{"speaker":"せお委員","kind":"質問・要望","question":"庁内連絡会議を開いていただいているということなので、ぜひそれが１回で終わらず、定期的に続けていただきたいと思っています。やはり、先ほどからお話がありますけれども、かわいそうという空気になっているから、それは嫌だというお話などもあって、そういったいろいろな考え方があると思いますので、その辺もぜひ配慮していただきながら、庁内でも検討していただければと要望いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"吉田副委員長","kind":"提案","question":"仕組みは最初につくっただけではやはり意味がないので、その運営というのでしょうか、それが大事だと思います。それで、定期的な協議を進めてほしいというのは、先ほど、せお委員からもご要望がありましたけれども、今既に、今後こういう調査を生かしてどういう協議を進めていくかというようなスケジュールがありましたら、教えていただきたいと思います。その１点。","respondent":"染谷子ども家庭支援センター長","answer":"今後、この調査の結果に基づいて、どういう形で仕組みをつくっていくかというところにつきましては、やはりこれまでと同様、子ども未来部のみで検討を進めていくものではないと思いますので、具体的支援策を実際につくっていく中でも。","id":"exchange-042"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"ですので、ここは教育委員会ということで、中学生、高校生、大学生まではテリトリーではないのかもしれませんけれども、そういうヤングケアラーもいらっしゃるということを視野に入れて、相談窓口や、何かそういうケア、もちろん家事支援やレスパイト支援をぜひお願いしたいのですけれども、そういう方たちもいらっしゃるということを片隅にとどめておいていただいて。","respondent":"染谷子ども家庭支援センター長","answer":"それで、今お話しいただいた事例のとおりで、ケアの責任や負担というのがすごく重くなる一方で、ご本人の将来を決めるような重大な選択をしなくてはいけないような状況というのが若者ケアラーの中にあるかと思いますので、そういった方たちに向けて。","id":"exchange-043"}]},{"id":"topic-05","title":"東京都からの一時保護受託の実施","agenda":"東京都からの一時保護受託の実施","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"２３区中２２区で児童相談所ができていくわけなのですが、一時保護の場所については、保護者が子どもを強引に連れ戻しに来るケースなどもあると思うので、必ずしも品川児童相談所で品川区の子どもを一時保護するわけではないとは思うのですけれども、開設後の一時保護における他区との役割分担や連携のルールというのは、もうつくられているのでしょうか。どのような中身になるのか、伺いたいと思います。","respondent":"長谷川児童相談所開設準備課長","answer":"一時保護した子どもの取扱いや、措置する場合のルール等につきましては、東京都がこれまで実施してきた体制を基本的には踏襲する形を取ってあります。２３区共同体で、会議体を持っていまして、その中で、東京都と区児童相談所になった場合のすみ分けのルールをつくっております。","id":"exchange-044"},{"speaker":"安藤委員","kind":"質問","question":"その会議体の中でいろいろ話しているということだと思うのですけれども、２２区で児童相談所が全て出来上がったときというのは、もう既にそういう一時保護の預かり先のルールというのですか、そういうものというのは出来上がるという感じでよろしいのでしょうか。","respondent":"長谷川児童相談所開設準備課長","answer":"一義的にはそのルールに従いまして、その後に、保護した子どもの措置先や保護する場所等につきましては、先行で開設している区が東京都と協議して決定した内容に従い、品川区も保護するといった方針です。","id":"exchange-045"}]},{"id":"topic-06","title":"品川区内保育園等あり方基本方針素案","agenda":"品川区内保育園等あり方基本方針素案","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"それぞれ教えていただきたいというのが１つ。それと、「保育需要増減時のバッファとしての役割」と書いてあるのですけれども、バッファというのは、緩衝、ゆとりという意味を含むと思うのですけれども、結局のところ、どういう意味なのでしょうか。日本語に置き換えていいので、教えていただきたいと思います。結局どれぐらい減らす、何園減らすと想定しているのか、伺いたいと思います。","respondent":"今井保育教育運営担当課長","answer":"これからの保育需要の変化を鑑みながら、当然、各地区によっても、あと年齢によっても、保育の空き状況といったものは変わってまいりますので、そういったものを総合的に勘案しながら、どの地区で、どの園をというところでの具体的な検討を今後進めするという予定です。","id":"exchange-046"},{"speaker":"安藤委員","kind":"質問","question":"「素案」が「案」になる。それで、「案」が「方針」になるときは４月だと思うのです。方針発表がここですから。といいますのは、何というのでしょうか、きちんと、こういう段階段階の検討委員会や文教委員会の意見を聞いてもらって、「方針」というものをつくってもらわないと困るという意味で聞いているのです。何で減らしてしまうのですか。その辺を伺いたいのが２点目。その２つをお伺いします。","respondent":"今井保育教育運営担当課長","answer":"委員からお話がありましたとおり、当然、今後パブリックコメントを実施いたしまして、そこで出た意見を反映させて、本日、委員会で報告させていただいて、各委員の皆さんからいただいた意見等も反映させていただいてということで。","id":"exchange-047"},{"speaker":"安藤委員","kind":"質問","question":"それと、少し細かいことで申し訳ないのですけれども、現在、「素案」ではないですか。区立園の統合がなぜ必要なのか、改めて伺います。そして、これは聞いてもしようがないかもしれないですけれども、保育園を統合するという方針を出されているわけですけれども、保育園を統合して保育の充実というのは、かなり無理があるというか、矛盾しているのではないかと思うのですけれども、いかがでしょうか。","respondent":"今井保育教育運営担当課長","answer":"３点目と４点目のご質問については、関連するものといいますか、お答えが重複すると思いますので、まとめてお答えしますけれども、委員から挙げていただきましたとおり、今現在、品川区もそうですけれども、全国的に保育のニーズの多様化が進んでおりまして。","id":"exchange-048"},{"speaker":"安藤委員","kind":"質問","question":"委員長、ありがとうあります。なので、私としては頂けない、内容的には大いに異論のある素案なものですから、「案」を「方針」にする上で、やはり、ぜひ多くの区民の方、そして議会などの意見も聞きながら決めていく必要があると思うので、しつこくやってしまいました。園を維持したまま、例えば定員を思い切って減らす、ゆとりある保育環境をつくるなど、できるわけではないですか。お願いします。","respondent":"今井保育教育運営担当課長","answer":"３点目が、民営化の進め方についてのご質問でございまして、委員のご認識のとおりです。","id":"exchange-049"},{"speaker":"安藤委員","kind":"質問・要望","question":"ということで、パブリックコメントの意見は何件ぐらいを目標にされているのでしょうか。この時点で伺いたいと思います。様々な形で働いております、保育士、職員の方々への影響も相当あるわけですから、こうした方々の意見をどう集約するつもりなのか、そのお考えをお聞かせいただきたいというのが２点目。説明会の開催は、やはり絶対必要だと思いますけれども、いかがでしょうか。","respondent":"今井保育教育運営担当課長","answer":"最後、説明会の実施についてですけれども、今回お示ししたとおり、概要版も用意させていただきまして、なるべく分かりやすく、内容が伝わるように対応していますので、現状で説明会を実施する予定はございません。","id":"exchange-050"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"昨年、出生数が８０万人を切って、今年も７０万人前半になるのではないかと言われている中で、見立てとして、今後一定数、減少するのかという見立てもある一方で、今年に入ってから急に、異次元の子育て支援だ、少子化対策だと政府が言ってきて、私も期待したのだけれども、蓋を開けてみたら何もないから、そのまま人口減少になってしまうのかと思いながらも、品川区も様々、子育て支援なりを充実させて。","respondent":"今井保育教育運営担当課長、石井保育支援課長","answer":"お金の部分については、区立保育園の保育士に対してお給料をというところでは、なかなか検討が難しい部分はありますけれども、そのほかの部分で、例えば保育士同士で顔を合わせる機会があって。例えば在宅支援ということですけれども、今年度、国のモデル事業を使って、未就園児の定期預かり事業を実施しています。","id":"exchange-051"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"もちろん外的要素というのはいっぱいあって、それはもちろん、その時々で本当にいつも考えていただいているのは十分分かっているのですけれども、やはりそこは改めて強く要望していきたいと思うし、できたら今後、区の方針の中にも、そういった部分も、できたら反映していただいて、区は本気で保育園を考えているという、本気度を見せていただく意味では、私は処遇改善というのは、やはり一定。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-052"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"１つだけですけれども、医療的ケアのお子さんの対応というのは大変すばらしいと思うので、検討も入れていただきたいのですけれども、配慮が必要なお子さんたちの対応が、今後検討していく中で出てくると思うのですけれども、保育園ごとにいらっしゃる配慮の必要なお子さんに対する対応は、現在も加配や、そういうものであれだと思うのですけれども、関西の自治体だと、１週間や２週間に一遍。","respondent":"今井保育教育運営担当課長","answer":"現状で、例えば品川児童学園と連携した保育所等の訪問支援等を実施していますけれども、今後もやはり区立保育園として、医療的ケアもそうですし。","id":"exchange-053"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"なかなか、新たにそういった施設を造って、そこに行くというのは難しいので、このように一定、施設に別の機能を持たせるというときには、そういうことが行われるチャンスだと思うので、ぜひよろしくお願いします。要望で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-054"},{"speaker":"せお委員","kind":"質問・要望","question":"私からも１点。なので、就学前のところで、ぜひ保護者の方々と関わっていただいて、何か本当、いろいろなところと連携した支援が必要なのではないかとは思っているのです。なので、今、就学後に対しての就学前で行っている支援というのはどういうものがあるのかと、あと、今後そういったところを何か新たに考えるというか、支援としてやっていく、取り組んでいくものがあれば、教えていただきたい。","respondent":"立木保育課長","answer":"特別支援の関係ですと、今現在も、特に就学に向けての年長児に関しましては、ほかの支援が必要でないお子様と一緒に、例えば保幼小連携、学校とも連携を取って、学校にお邪魔させてもらったりはしているのですけれども、それ以外にも、就学に向けて保護者の方へ。","id":"exchange-055"},{"speaker":"せお委員","kind":"質問・要望","question":"なかなか保護者にとって、何というのですか、気づいていないというよりは、自分のお子さんには支援が必要がないと、別に悪気なく思っていて、その後、就学してというところで、早めに支援があれば発達の成長なども早くなるのかというのは、すごく日々感じているところなので、先ほども巡回相談などもありますし、そういったところの支援も活用しながら。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-056"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ハード面のことでお尋ねなのですけれども、素案の１３ページで、施設の併設状況なのですけれども、代替施設なり、再整備という点においては、独立した園だったらできると思うのですけれども、それぞれ地区別で見ても、児童センターがそれぞれ都営住宅、それぞれ併設の状況を今お示しされております。お願いします。","respondent":"今井保育教育運営担当課長","answer":"今ご質問のございました、今後の進め方、手法の検討といった部分のご質問ですけれども、委員ご指摘のとおり、例えば併設の施設等々ですと、その併設されている施設との調整、利用が一定できなくなる部分や、工事で影響を与えてしまう部分といったところが考えられますので、一定。","id":"exchange-057"},{"speaker":"高橋（伸）委員","kind":"意見","question":"荏原地区でも、やはり源氏前保育園と旗の台保育園も併設になっていて、源氏前保育園は図書館になったり、あと旗の台のほうは公園のある児童センターになる。その交渉というのは当然これからだと思うのですけれども、一番、私が思っているのは、都との交渉が結構、大変なのかと思っているのですけれども、そのことだけご答弁いただければと思います。","respondent":"今井保育教育運営担当課長","answer":"なので、こういった施設については、当然その調整に時間がかかるといった背景もありますので、後回しにするなどという話ではなく、長期的な目線を持って、改築に向けて準備を進めていくというような姿勢で取り組んでまいりたいと考えております。","id":"exchange-058"},{"speaker":"吉田副委員長","kind":"質問","question":"１つ、私がぱっと思いつくのは、やはり、このままほっておくと、もしかすると虐待の方向に行ってしまうかもしれない。そういう意味で、やはり区立保育園をだんだん減らしていくという方向はどうなのか。今後の保育の重要性、それこそ子育て支援だけではなく少子化対策にもつながるような保育園の運営というのはあるのではないかと思うのですが、その点についてはどのようにお考えか伺いたいと思います。","respondent":"今井保育教育運営担当課長","answer":"現状で、やはり保育ニーズとして減少の見込みがあるといった背景に基づきまして、また、今後、保育ニーズが多様化してまいりまして、在宅子育て支援等の強化も求められていく中では、まずそれを実施するための人的・施設的な余裕がある必要があると考えております。","id":"exchange-059"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"そういう議論をどんどん深めていっていただきたいと思うのですけれども、その中でもやはり人的な資源を確保するためには、先ほどもどなたか、ほかの委員から発言があったと思うのですけれども、やはり保育士の処遇の改善は、いろいろな場面で度々求めておりますので、特に私立園の保育士の処遇改善。なので、その辺のことも、区としてもぜひ国に対しても求めていただきたい。","respondent":"石井保育支援課長","answer":"現在、保育士の賃金等が改善されているかどうかということに関しては、国も相当程度、問題意識を持っており、例えば東京都がキャリアアップ補助金に対する財務情報公表様式というものを公開させてありますけれども。","id":"exchange-060"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"なので、そういうことも含めて、ぜひ品川区では、そういうものがあったとしても、より分かりやすい公表の仕方というのも検討していただきたいと思います。処遇改善が事業者に行ってしまうというケースは、保育士の手当だけではなく、ほかのところでも見られますので、品川区ではぜひそのようなことがないように、保育の場面ではお願いしたいと思います。これは要望にとどめます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-061"}]},{"id":"topic-07","title":"議会閉会中継続審査調査事項","agenda":"議会閉会中継続審査調査事項","exchanges":[{"speaker":"高橋（し）委員","kind":"意見","question":"いつも文教委員会で体罰について報告していただくのですけれども、詳細はそのときで全然構わないのですけれども、品川区でも体罰等、東京都教育委員会が認定した、あるいは体罰に至らないまでもというものがあったのかどうかだけお願いします。","respondent":"中谷指導課長","answer":"今の体罰のご報告の件なのですけれども、先日、ご指摘いただいたとおり東京都教育委員会からの通知がございまして、これを受けまして品川区としましては、次回の文教委員会で詳細を含めてご報告させていただければと考えていますので、よろしくお願いいたします。","id":"exchange-062"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/246913?Template=document&Id=5116#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":65719,"voices":192}},{"id":"r05-20231128-5","meetingId":"r05-cm11","date":"2023年11月28日","dateIso":"2023-11-28","committee":"総務委員会","time":"午前１０時０８分～午前１０時５６分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を15件抜き出しています。","topics":[{"id":"topic-01","title":"の給与等に関する条例の一部を改正する条例、(5)第９９号議案、職員の給与に関する条例の一部を改正する条例および(6)第１００号議案","agenda":"の給与等に関する条例の一部を改正する条例、(5)第９９号議案、職員の給与に関する条例の一部を改正する条例および(6)第１００号議案","exchanges":[{"speaker":"須貝委員","kind":"意見","question":"一括でよろしいのですね。品川区一般職員の給与、また会計年度任用職員の給与も今回出るということですが、本来なら区民生活、それから区内の中小零細企業においては経営がまだ厳しい、一般の区民においても物価高騰で同様にやはり生活が厳しい中で、区の職員にも我慢をしてほしいところですが、これだけ物価が高騰した中で、今１世帯当たり年間１０万円以上の負担をされている。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"},{"speaker":"澤田委員","kind":"質問・要望","question":"そもそも職員の給与の考えというのが、昭和３９年から民間の平均を取っていて、毎年４月にその平均を取って決めてきていて、長年職員の皆さんも特別職も下がってきたと理解しております。民間の給与と連動して、職員の給与が変わってきた中で、それに対して今回だけ連動しないということではなく、職員の皆さんと同じように、特別職も改正していくというのがいいのではないか、進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"塚本副委員長","kind":"意見","question":"賛成します。考え方としては、民間と合わせて上がるときは上がる、下がるときは下がる。そういうのがこの給与の設定としては合理的な、我々も含めて基本的にはそれが一番合理的であると思っていますので、賛成いたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-003"},{"speaker":"須貝委員","kind":"質問","question":"１個ずつですか。すみません。気が焦っていました。第９５号議案については反対します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"松本委員","kind":"意見","question":"第９５号議案については反対です。そこを上げるには相当な苦労がある。そういう中で、では我々議員がどういう成果を出しているのかというところに関しては、なかなかこの品川区民の皆さんの生活を、今これだけ物価が上がっている中で楽にさせられているかといったら、そう簡単では、そう断言できるほどではないと私どもは考えております。したがいまして、第９５号議案に関しては反対をします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-005"},{"speaker":"石田（秀）委員","kind":"提案","question":"私は第９５号議案、そのほか全ての議案に賛成しますが、考え方だけ言わせてください。１回目は下げませんでした。それをもうずっと受けてきた。それ以外でやるのであればほかのところで議論をするべきであって、それを寄附だ、どうのこうのとかやっているほうが私はおかしいと思っているので、私はこの件については必ずそのとおり、今提案があったとおりやるべきだと思っているので、第９５号議案は賛成。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-006"},{"speaker":"須貝委員","kind":"意見","question":"すみません、私もちょっと一言言わせていただきます。品川区内で多くの方たちが住まわれて、年金暮らしの方、それから本当に中小企業でボーナスも出ない、ボーナスが出てもわずか、給与は上がらない、そういう状況を考えたときに、やはり選挙で選ばれた方たちは、私は自重すべきだと思います。今回の第９６号議案については反対します。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"},{"speaker":"須貝委員","kind":"質問","question":"先ほども申し上げましたけれども、全国自治体において月額報酬から日額報酬に変わっている状況を踏まえたら、一部の行政委員がやはりこのように増額されるというのは私は間違っていると思います。逆に減額するべきであると思います。ですから、第９７号議案は反対します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"松本委員","kind":"意見","question":"反対です。ここだけは少し別のところなので。会計年度任用職員に関しましては、今回ほかのところと同じような増額部分だけではなくて、新たに手当の部分を他の職員の方たちと合わせるというところが令和６年度に入ってからの勤勉手当ですね。こちらについては同一労働同一賃金の観点から賛成したいところですが、期末手当の増額分については他の部分と同様のところがありますので、反対とします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-009"}]},{"id":"topic-02","title":"第７６号議案、令和５年度品川区一般会計補正予算","agenda":"第７６号議案、令和５年度品川区一般会計補正予算","exchanges":[{"speaker":"須貝委員","kind":"確認","question":"１７ページの就学支援費のほうですが、確認ですが、学校給食費無償化事業で、これは国立・私立特別支援学校ということは学校全体に支援をするのか、それとも品川区に住民票がある子どもたちだけに支援するのですか。一応教えてください。","respondent":"遠藤財政課長","answer":"こちらは品川区に在住されている方を対象にして、という形になります。","id":"exchange-010"},{"speaker":"須貝委員","kind":"意見","question":"１５ページの保健衛生助成金で、公衆浴場物価高騰対策支援金と、中小企業活性化事業費で、運送事業者等燃料費高騰対策支援金、これが計上されています。ならば、公衆浴場だけではなく、また運送事業者だけではなく、他の産業・事業所においてもやはり平等・公平に支援をするべきだと私は思います。意見だけ言わせていただきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"}]},{"id":"topic-03","title":"地方税の賦課及び徴収事務における「特定個人情報保護評価」の実施","agenda":"地方税の賦課及び徴収事務における「特定個人情報保護評価」の実施","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"そこにカメラがついているのです。そして、何時何分に例えばそこを通ったとか、普段は別に監視する必要はないですけれども、何かあったときにある方が例えば夜の９時に来てパソコンをいじっていて、その情報が漏れたとか、そういうときに目で見える、そういう情報管理も必要ではないかと思うのですが、すみません、庁内にはそういうカメラみたいなものは設置されているのですか。教えてください。","respondent":"提坂税務課長、佐藤（聡）経理課長","answer":"税務課の立場としては、全庁を把握しているものではございませんが、税務課ですとか戸籍住民課、国保医療年金課、区民の多くの皆様と接する事務室では設置してございませんが。生活福祉課ですとか一部の課においては、窓口の安全ですとか、そういったところの管理のためということで、個別につけている状況です。","id":"exchange-012"},{"speaker":"須貝委員","kind":"質問・要望","question":"一部大手などは、やはりこういう相当な個人情報をお持ちでやり取りしているという、情報開示したりいろいろやっていますので、そういうことも今後必要になるのではないかと。その人を見るというのではなくて、フロア全体で誰が最終的にパソコンをいじっていたのかということも、あるときには一つの調べることができる要素の一つにもなると思いますので、ぜひ私は検討していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"すみません、ちょっと不勉強なので教えていただきたいのですが、特定個人情報保護評価は、品川区が発生させるリスクを分析して、そのリスクを軽減する適切な措置を講ずるというのだけれども、これを見ていくと、この根拠法令を見たときに平成２５年とか２６年で、何で今頃なのかと思った私がいます。","respondent":"提坂税務課長","answer":"これまでにも特定個人情報保護評価というのは少なくとも５年に一回実施しておりまして、その後、システム改修ですとかシステムに重要な変更を行う際に実施することになっておりまして、税のほうも前回４年前に行っております。","id":"exchange-014"},{"speaker":"石田（秀）委員","kind":"質問","question":"今のはそのとおりだと思って伺っていました。そうではなくて、システムはもともとやっていたのを、４年に一回だとかそういうのでやり替えるから、改めて報告しているというだけなのか。ということは４年前にもやっているのだけれども、私もそれは不勉強で、その時ちゃんとやっているのだからという理解なのかどうなのかというところだけ、教えてください。","respondent":"提坂税務課長","answer":"資料の２、評価書の内容ということでＩからVIまで記載されておりますが、これは今回新たに記載したものということではございませんで、もともと記載している部分です。","id":"exchange-015"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/166654?Template=document&Id=2284#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":16151,"voices":90}},{"id":"r05-20231128-10","meetingId":"r05-cm11","date":"2023年11月28日","dateIso":"2023-11-28","committee":"議会運営委員会","time":"午前 ９時３０分～午前 ９時３６分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/105128?Template=document&Id=5524#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":2897,"voices":16}},{"id":"r05-20231129-14","meetingId":"r05-cm11","date":"2023年11月29日","dateIso":"2023-11-29","committee":"行財政改革特別委員会","time":"午前１０時００分～午前１１時５１分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を41件抜き出しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"山本委員","kind":"提案","question":"今、お聞きして、とてもいい進め方をしていただいていると感じました。策定委員会から提案された、多様な人々が集い・学び・助け合い・心と体の健康を育む交流拠点というコンセプトがとてもいいなと思いました。区民の皆様の意見をお聞きするというすごく大事なことだと考えていますが、このパブリックコメントを１２月に実施した後、このコメントはどのように答申などに反映されるのでしょうかです。","respondent":"吉岡政策推進担当課長","answer":"スケジュールに関しましてですけれども、１２月にパブリックコメントをやらせていただいて、その後皆さんからしっかりしたご意見をいただきながら、まず、これが反映に資するかどうかというところも委員会のほうできちんと検討させていただいて。","id":"exchange-001"},{"speaker":"山本委員","kind":"質問・要望","question":"ご回答ありがとうあります。どういった施設かというところで具体的な施設を上げるということではなく、こういった施設があったらいいという考え方で、こういったプロセスから結論に至ったということで理解いたしました。よいなと思いました。こういった広い場所ということで、これは全て入るように、ぜひ進めていただきたいなと考えています。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"あくつ委員","kind":"質問","question":"特にアール・ブリュットの展示とかこういったことも明確に書かれているということで、あとは障害のある方の就労であるとか、そういったことも書かれているということで、非常にすばらしいなと思ったのですけれども、今回のメインコンセプトである図書のことについてまずお伺いをしたいのですが、素案のほうを拝見いたしますと、素案の１７ページ。１９ページには図書館機能というふうに書いてあるのです。","respondent":"吉岡政策推進担当課長","answer":"１９ページの図書館機能というところで入れさせていただいたのですけれども、図書館というのが、そういう施設というような位置づけで言葉を、一旦こういった使い分けをさせていただいているのですが、今回パブリックコメントも経まして。","id":"exchange-003"},{"speaker":"あくつ委員","kind":"質問","question":"障害とか。それは何か指定管理のようなものをして、指定管理者が全部を見るという形なのか、それとも図書館機能というところでそれは教育委員会があくまで責任を持ってそこはやりますよというところなのか、司書の配置をどうするのかとか、いろいろな話が出てくると思うのですが、その辺りはどのようなお考えなのか、現在のところ、決まっていることを教えてください。","respondent":"吉岡政策推進担当課長","answer":"委員おっしゃるとおり、この施設、かなり多岐にわたる複合施設という形になりますので、運用形態につきましては、次年度、計画の策定を進める中で検討していく形にはなりますけれども、できる限り民間の活力も活用しながら運営していくべきだというふうに捉えているところです。","id":"exchange-004"},{"speaker":"あくつ委員","kind":"質問","question":"それと、そういうふうになってくると、多岐にわたる、スポーツも入っている、いわゆる障害も入っている、防災も入っているというところで、品川区にあまり例を見ないような複合施設になってくるのかなと思うのですけれども、こういうところに関しては、これから何か検討していくというのはもうここで素案が出たというところで、策定委員会の役目を終わって。","respondent":"吉岡政策推進担当課長","answer":"こちらにつきまして、策定委員会のほうもこういった類似の施設を例に出しながら、委員の皆様にもご覧いただいて、こういう感じだねというような認識を、感想をいただいたです。","id":"exchange-005"},{"speaker":"あくつ委員","kind":"質問","question":"先ほどできるだけ民間の活用をされていきたいというご答弁があったのですけれども、これから先はもう庁内でどんどん進んでいくということになるのですか。もう一つ言ってしまえば、その途中で議会への報告があるのかどうかというところも含めて、我々が何か意見を言える場があるのかということも含めて質問させていただきました。もう一度お願いします。","respondent":"吉岡政策推進担当課長","answer":"大変失礼いたしました。今年度は多くの方、区民の方、あるいは地域の方に入っていただく委員会という形式で行いましたけれども、次年度はどちらかというと、庁内の検討会議というのも多く重ねる予定です。","id":"exchange-006"},{"speaker":"えのした委員","kind":"質問","question":"ご説明ありがとうございました。複合施設、多岐にわたる取組で、私も拝見させていただきましたが、できるのかなと思いながらも、敷地面積が８,４７２.６９m2ですか。パブリックコメントの実施。オープンハウス方式の開催の日にちが１２月８日・９日・１４日の３日間出ていますが、これは、どちらの場所でやるのかというのが示されてないので、そこをお伺いさせていただけますでしょうか。","respondent":"吉岡政策推進担当課長","answer":"オープンハウス型の説明会の実施場所ですけれども、旧荏原第四中学校の集会室のほうで、３日間行わせていただきます。","id":"exchange-007"},{"speaker":"えのした委員","kind":"質問・要望","question":"本当に１２月、もう年末１か月の中で、パブリックコメント、なかなか皆さん区民の方もお忙しいと思うのですけれども、本当に多くのお声を頂戴して、私も先日の一般質問でも質問させていただきましたが、様々な交流によって災害時の助け合いの輪が広がるという他の自治体の取組なども随分入っていますので、単に避難場所というものではなくて、防災の拠点となるような施設になっていくように、今後も期待して。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"コンセプト案が薄く、どこにでもある施設になるのではないか。それと、これまで私たち共産党は特別養護老人ホームなどの増設もここに求めてきましたけれども、素案の１０ページのところでも、世論調査、荏原東地区では、区内全域よりも福祉保健施設の要望が強い結果が示されていると思いました。特別養護老人ホームも導入施設に入れていただきたいなと思うのですけれども、いかがでしょうか。","respondent":"吉岡政策推進担当課長","answer":"こういったものを中心に据えながらやっていこうというところで、第３回の策定委員会のほうでは、こちらのほうで進めるというようなお話をいただいたところです。先ほど、特別養護老人ホームというお話がございました。","id":"exchange-009"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"要望です。私たちも説明会を要望してきましたけれども、区としては、説明会を実施しないというような姿勢だったのではないかと思うのですが、これは何か方針が変わったのか要望があったか伺いたいのと、住民同士がどういう要望をみんなが持っていて、お互いに知り合うという上では教室型の説明会も重要だと思い、これも実施していただきたいなと思うのですが、いかがでしょうか。","respondent":"吉岡政策推進担当課長","answer":"今回この旧荏原第四中学校、非常に大きい施設になります。今回、方針の素案のところでも、複合型施設ですので、こういった新たな試みとして、こちらの施設については、オープン型で説明会を実施したいと考えたところです。","id":"exchange-010"},{"speaker":"石田（ち）委員","kind":"意見","question":"分かりました。どちらにしても区民の意見をさらに聞いていただいて、本当に充実する、愛される施設になっていくといいなというところでは私たちも一緒に意見を上げていきたいなというふうに思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"},{"speaker":"松本委員","kind":"質問","question":"そうすると、例えば二葉のほうは設立が１９７０年で、ゆたか図書館は１９７５年ということなので、場合によっては、この辺り将来的には統合ということも、一応視野には入れていらっしゃるということなのでしょうか。","respondent":"吉岡政策推進担当課長","answer":"これからの図書館の計画、整備計画、あるいは修繕計画。そういったところも含めまして、今回の旧荏原第四中学校のところの図書機能、図書館機能、図書スペース。こういったものがどれだけ拡充できるかといったところで、そういった話になってくるかと考えています。","id":"exchange-012"},{"speaker":"松本委員","kind":"質問・要望","question":"分かりました。最後は要望ですけれども、これだけ複合的な施設ですので、ぜひ公民連携といいますか、ＰＰＰ、ＰＦＩの視点は取り入れて、整備を進めていただきたいなというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"まつざわ委員","kind":"質問","question":"会派からも、例えばマイスクールに関しては、中心にあったほうがいいというのもしっかり反映されていて、非常に評価が高いところでありまして、私からは、まず１点伺いたいのは、防災拠点という部分で、もともと豊町三丁目、四丁目の避難所でありますけれども、入りきれないから、実際あそこの人たちは大崎高校に行ったりという、分散している。","respondent":"吉岡政策推進担当課長","answer":"しかしながら、今委員もご紹介のとおり、防災の拠点というところで、一番大きいところは、今、５７２人の区民避難所として指定されているところなのですけれども、最低でもここは確保してほしいというところが、地域の強い声だです。","id":"exchange-014"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"５７０名を入れるというのは重々承知で、絶対それはマストな感じになっているのですけれども、例えば少し要望として言わせていただきたいのは、前回の決算特別委員会でも言わせてもらったのですが、消防団というのはもう正式に言うと東京都の管轄なので、品川区がどうとかということは確かに全く筋違いというのは私も重々承知なのですが、例えばそういう団小屋というのは。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ご説明ありがとうございました。それぞれ行政需要の中で、４項目あって、戸越荏原地区にも複合拠点となり得る施設になるのではないかなと考えています。本当に地域の皆さんの一番の要望は、私は防災の拠点だと思っているのです。例えば備蓄倉庫とかいろいろ書いてありますけれども、具体的に絶対これは必要というような何か意見、どういった意見があったのかというのを、まず教えていただきたいと思います。","respondent":"吉岡政策推進担当課長","answer":"どういった意見があったかですけれども、今回方針というところで、非常に大きいところでお話し合っていただくといったところで、特に備蓄倉庫とかあまり細かい機能についてのお話はなかったところですが、体育館ですとかこういう教室系のスペース。","id":"exchange-016"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ありがとうございました。ぜひ、これからパブリックコメントがあって、それぞれまた区民の要望、意見があると思いますので、おまとめいただいて、進めていただきたいと思います。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"塚本委員","kind":"質問","question":"質問なのですけれども、学びの場と同時ににぎわい・交流というところも入ってきているわけで、どちらかというと図書館というのは静かなイメージで、学びというとみんなで集団でいろいろ学習するというのもあるのかもしれないですが、基本的には静かな感じがイメージとしてあるのですが、そういった中でのにぎわいとか交流というのをどういうふうに織り交ぜていくのかというところについて、お伺いしたい。","respondent":"吉岡政策推進担当課長","answer":"委員の皆様から、視察先でご提案があったところも含めまして、先行事例を今後研究していきまして、こういったものをまとめていきたいというふうに考えてあります。","id":"exchange-018"},{"speaker":"塚本委員","kind":"提案","question":"別の観点なのですけれども、屋上緑化とは別にビオトープが出ていて、ビオトープはこれまでも例えば戸越公園に蛍を何とかみたいなことで、ビオトープを造れないかとか、いろいろなお話が地域でもあったりしたのですが、実際に生態系を人工的に維持していくのが非常に大変というふうなことで、そういったところでの実現性とか現実性というのは、ある程度見越した上でここまで提案書には載せているのか。","respondent":"吉岡政策推進担当課長","answer":"こういった具体的な計画落としていく中で、適切に進められるよう、区のほうも努力していきたいと考えているところです。","id":"exchange-019"},{"speaker":"塚本委員","kind":"質問","question":"そうすると、ビオトープということで言うと、生き物を飼うということも一応念頭に入っているのですか。","respondent":"吉岡政策推進担当課長","answer":"ビオトープにつきましては、直接そこまであまり深掘りをされていない部分です。こういった生き物が飼いたいだとか、そういった展示会をしたいとか、そこまでの議論は深まっていない部分ではありますので、こちらは今後検討していきたいというふうに考えてあります。","id":"exchange-020"},{"speaker":"塚本委員","kind":"意見","question":"今、いろいろな不登校対策というか不登校の児童生徒にどうやって対応していくかということでは、居場所みたいなそういうものもあって、必ずしも学校に戻すということを念頭にしないような形で、何とか子供たちを不登校から少しでも外に出ていくとか、少しでも社会になじんでいけるとか、学校に適応できるというようなことも対策としては考えられてきている流れもあるので。","respondent":"吉岡政策推進担当課長","answer":"そういった場を目指していきたいというふうに考えてあります。","id":"exchange-021"},{"speaker":"松永委員","kind":"質問","question":"先ほどまつざわ委員からありましたけれども、消防団の分団小屋というのも必要かとは思うのですが、今消防団の訓練場所というのがあまりなくて、今、文庫の森でやっているそうなのですが、ほかの分団は区役所の第二駐車場に来たりとか移動する部分があるので、もし人工芝であった場合というのは、可搬ポンプを使うことができるのかどうかというのと、土だったら多分できるとは思うのですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"松永委員","kind":"質問","question":"いろいろな方が来られるということで、もう一つなのですけれども、まだ先の話になるのですが、東急大井町線、恐らく高架になると思うのですが、その辺のセットバックとかは関係が出てくるのかどうかというのをお知らせいただければと思います。すごく危ないので、何かそういった対策とかも含めて考えていただければと思うのですけれども、ご意見を伺いたいと思います。","respondent":"吉岡政策推進担当課長","answer":"今、委員からのお話のとおり、四方に囲まれて非常に狭隘道路があります。高架下のところもありますので、今後基本計画の中で、人の流れ、交通の流れ。そういった部分も確認しながら基本計画の中で、安全にこの施設を使用していただけるように努めてまいるところです。","id":"exchange-023"},{"speaker":"せお副委員長","kind":"質問","question":"ご説明ありがとうございました。そして、様々議論伺っていました。でも地域バランスを考えると、今、マイスクール八潮があって、大井のほうにできると。もう１点インクルーシブひろばベルが暫定で移ってくると。なので、そういった２点、教育委員会であったり、あと障害福祉のほうとかとしっかり連携して話し合える、庁内検討できる場所というのが、今あるのかどうか、お聞きしたいです。","respondent":"吉岡政策推進担当課長","answer":"詳細につきましては、今後の検討になりますけれども、現時点でも必要な情報につきましては、各所管と連携を取っているというところだけ、お伝えさせていただければと思います。","id":"exchange-024"},{"speaker":"せお副委員長","kind":"意見","question":"ここの庁舎跡地もそうですし、しっかり区民の声とか地域のお声とかを聞いてくださっているので、そこももちろん大切ですし、ただ、区の計画のバランスとかそういったところも先ほどもお話がありましたけれども、同じようなものが同じ地域に２つあるとか３つあるとか、そういったことももったいないなということもあるので、ぜひそこら辺もこれから間に合うようでしたら、インクルーシブひろばベルに関しては。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-025"},{"speaker":"石田（ち）委員","kind":"質問","question":"スライドの３ページ目、オンライン手続の拡大ということで示されていますけれども、これらはマイナンバーカード取得とセットになるのか、マイナンバーカードがなければ行政サービスが受けられないという仕組みにはすべきではないと思うのですけれども、伺いたいと思います。","respondent":"河西情報戦略担当課長","answer":"例えば、従来どおり免許証のコピーですとか、そういった本人確認するものを添付することによって受け付けるという方法も提供しておりますので、マイナンバーカードがないと利用できないかというと、そうではないということでご報告いたします。","id":"exchange-026"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"あらゆるデータを行政側に集積して、このビッグデータを企業に提供するなど、もうけの種になっていく、こうした匿名加工情報として提供されるという活用はすべきでないということはずっと言ってきているのですけれども、このマイナンバーカードの取得も任意というのが法の規定でありますので、ひもづけの間違いや情報の漏えいなど様々な問題も起こっていますので。","respondent":"河西情報戦略担当課長","answer":"ＤＸの流れについて、改めて認識を共有しますと、ＤＸに関しては、デジタルを業務に取り入れることによって、質の向上という側面が非常に強いと思っています。","id":"exchange-027"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"質が高くなるのはいいことなのですけれども、それとともにこれまではそういったＤＸを進めることで、要は手間が省ける職員の部分をしっかり区民サービスに活かしていくということをおっしゃっていただいていたので、その考えは今も変わらないということで、いいでしょうか。人員削減ありき、行政コスト削減ありきのデジタル化は、改めてやめるように求めたいと思うのですけれども、いかがでしょうか。","respondent":"河西情報戦略担当課長","answer":"委員おっしゃるとおり、ＤＸ推進基本方針には、まさに今おっしゃったとおり、ＤＸを進めることによって、空いた手間、稼働を本来必要な区民との対話ですとか、相談受付ですとか、そういった業務に振り向けることによって。","id":"exchange-028"},{"speaker":"石田（ち）委員","kind":"質問","question":"スライドで言う１３のところです。テレワークについては、メリットもデメリットもあるのかなと思うのですけれども、この新テレワークの導入も示されていまして、テレワーク利用促進については、数値の目標というのがあるのかどうか。ぜひ、言いたいのは現場で働く方の希望や声を聞きながら、拡大ありきではなくて、実態や必要に応じて進めていくべきだと思うのですけれども、いかがでしょうか。","respondent":"河西情報戦略担当課長","answer":"もちろん今の業務がありますし、例えば窓口業務ですとかそういった業務がありますが、そういった中でもテレワークという仕組みを提供することによって、うまく職員が各所管のほうで工夫して利用できるように、環境を整えるという意味で、拡大のほうをしてまいります。","id":"exchange-029"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"分かりました。改めて、テレワークにおいては、推進ありきではなくて、仕事の実態や職員の要望に応じて進めるように求めたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"山本委員","kind":"質問・要望","question":"できそうかどうかというところについて、お伺いしたいと思います。新庁舎建設が予定されておりますので、そこへの関係というところで、どの程度お考えなのかというのをお聞かせいただきたいというのが２つ目になります。例えばそういった個人情報に関わるものは持ち帰れないとか、もしくは持ち帰った自宅の中では見られないとか、そういった対策などがおありでしたらぜひ伺いたいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"山本委員","kind":"質問・要望","question":"１５ページのスライドでご説明いただいた、この業務のところでの情報漏えいのところですが、そのようなご検討をとお答えをされているということで理解をしたのですが、１点確認をさせていただきたいのが、区役所内で扱われる業務の中で、区民の方々の様々な個人情報を扱われるところがあると思うのですけれども、それがテレワークで自宅でも見られるような状況なのでしょうか。確認させてください。","respondent":"河西情報戦略担当課長","answer":"先ほどのご質問にお答えいたします。１５ページの図、左下を見ていただきたいと思います。品川区役所は、３つのネットワークで構成されております。マイナンバー系、ＬＧＷＡＮ系、インターネット系。今回、テレワークの対象とするのが、職員端末ＬＧＷＡＮ系の端末になります。","id":"exchange-032"},{"speaker":"山本委員","kind":"質問・要望","question":"これすごく大きなことだと思うのですけれども、実際使っていただく皆様にこういった情報の管理のところについてもしっかりと守っていただけるように、周知をお願いできればと思って、職員の皆様にご説明していただきたいです。そして、これを導入した後、ぜひ効果検証をしていただいて、多くの方々が利用できるようにしていただきたい、使いやすい仕組みにしていただきたいという、これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"あくつ委員","kind":"確認","question":"先ほどからこれによって、個人情報等は自宅でテレワークであったとしても、マイナンバー系ということでその情報については扱わないというお話でしたけれども、今まで行政の方がタブレットであるとかＵＳＢとかを、例えば夜飲食の場に置き忘れてしまって紛失してしまったみたいなことが年に数回報告がありますが、例えばこの端末を持ち帰って、そのようなことが起きた場合。","respondent":"河西情報戦略担当課長","answer":"接続するときには、必ずモバイルネットワークＳＳＩＤというものを通して接続を行います。そのときのＳＳＩＤ認証というのを実施しております。この３つを合わせることで、知識と物がないと接続できないというところを担保して、セキュリティの確保を実施しております。","id":"exchange-034"},{"speaker":"あくつ委員","kind":"確認","question":"分かりやすくというところで、私の知識が浅薄なので、少し分からない部分もあったのですけれども、今おっしゃっていたような３つの認証があって、それは職員の頭の中にあるものであって、例えば端末は予約は要らないという話ですが、パスワードなどは紙で示されるというものなのか、それを例えば本人がメモ帳や手帳に貼り付けておいて、それと一緒になくしてしまった場合でも。","respondent":"河西情報戦略担当課長","answer":"認証を通してしまいますので。ですので、先ほどご説明したとおり、２要素認証という仕組みを使って、ＩＤパスワードプラス端末、あとモバイルルーター。この３つがセットでないと接続できないというところまでセキュリティの担保をしようというところになっております。","id":"exchange-035"},{"speaker":"あくつ委員","kind":"質問","question":"だんだん理解をしてきているのですが、モバイルルーターというのは、これは説明で多分あったのかもしれないのですけれども、モバイルルーターも一括して貸し出すということなのでしょうか。それはもう間違いないということなのですか。","respondent":"河西情報戦略担当課長","answer":"それを分かっている方であれば、接続できてしまう。ただし、そうなってしまうので、我々日頃からセキュリティに関する研修を実施しております。","id":"exchange-036"},{"speaker":"あくつ委員","kind":"質問","question":"確率が少ないのは分かっているのですけれども、最後にすみません。私も素人考えなのですが、例えば本人認証のときに、今生体認証とありますよね。本人の顔とか網膜とか指紋とか。そういったものでの、それがなければ突破できないというような、そこまでは今回はつくらないということなのでしょうか。","respondent":"河西情報戦略担当課長","answer":"今、生体認証を使っていますが、そちらの認証サーバーというものが、庁内にあります。今回は外から接続しますので、その生体認証サーバーにアクセスできないところから接続をかけますので、生体認証は使うのが難しいという回答になりまして、ＩＤとパスワードにしています。","id":"exchange-037"},{"speaker":"あくつ委員","kind":"確認","question":"ありがとうございました。今、生体認証は難しいということでした。やれることはやってというところですので、端末を物理的になくしちゃう、ルーターを物理的になくしちゃうということは、これは人間だから起こり得る、起こってはいけないことですけれども、起こり得る可能性があるということですが、限りなく情報の流出は低いのだろうなというところで確認させてきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"えのした委員","kind":"質問","question":"品川区電子申請サービスの利用状況を見ても、訪問者数、申請数、順調に伸びているということで、１９時以降仕事が終わってからですかね。すごく助かっているのではないかなということは数字で感じ取れます。区民の方からアンケートを取っているか分かりませんけれども、チャットボットはすごく分かりやすいよとか使い勝手がよかったとか、何かそういうような声があれば教えていただけますでしょうか。","respondent":"河西情報戦略担当課長","answer":"今ちょうどＣｈａｔＧＰＴが出てきておりまして、いろいろなマニュアルを読み込んで、それに回答できるような仕組みというのが出てきておりますので、そういった仕組みを総合窓口として、ＡＩチャットボットに活用できないかというところも今ちょうど研究を進めておりますので。","id":"exchange-039"},{"speaker":"山本委員","kind":"質問","question":"２回目で恐縮ですが、１点追加でお聞かせください。これは一般質問でも申し上げたところなのですが、そういったセットでやるべき。シニアスマホ教室は高齢者地域支援課ですか。所管が別のところでやっていらっしゃるという。","respondent":"河西情報戦略担当課長","answer":"今の高齢者地域支援課のほうでシニア教室を実施しておりますが、そちらに関しては、どうしても教室数に限って言うと、なかなか大人数が参加できないので、ある地域のある特定の方に限られてしまうというのがどうしても課題としています。","id":"exchange-040"},{"speaker":"山本委員","kind":"質問・要望","question":"要望になりますが、窓口へ来ていただいた方への十分なサポート。それから、シニアスマホ教室の拡大には課題があるということで、どうしても数がなかなか難しいということでございましたが、一般質問やこれまでの議会でも申し上げていますように、工夫をしながら数を増やせる取組についてもご検討いただきたいというところ。それらぜひ進めていただきたいということで、要望として終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/994750?Template=document&Id=6160#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":36725,"voices":111}},{"id":"r05-20231130-19","meetingId":"r05-cm11","date":"2023年11月30日","dateIso":"2023-11-30","committee":"災害・環境対策特別委員会","time":"午前１０時００分～午後 １時４３分","status":"正式会議録","sourceType":"formal","overview":"災害・環境対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を32件抜き出しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"リサイクルのほうで伺いたいのですけれども、まずこの間の、法律の関係のご説明が少しあったのですが、リサイクルについて国のほうでの流れというものはどのようになっているのか。伺いたいと思います。捉え方です。","respondent":"品川品川区清掃事務所長","answer":"それに対する区の考えですが、先ほど少し説明したとおり、近年ではちょっと、一定の伸びが出ない傾向がありますので、やはりここを伸ばしていく策をこれから取り組んでいかなければいけないと、このように思っております。","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問・要望","question":"拠点回収のところでは少し増えてきているのですか、という感じなのですけれども、今区内では、単純に考えると、人口が増えてきているところで考えると、資源、単純な量でいけば増えていくのかなと思うのですが、それが明らかに増えていくということにはなっていないということは、区としてはどのようにお考えなのか伺いたいと思います。","respondent":"品川品川区清掃事務所長","answer":"最近では大分、何というのですか、通販ですか、そのようなものが増えて、やはり段ボールの量などは意外と多くなっている傾向はあるのではないかなと考えています。","id":"exchange-002"},{"speaker":"のだて委員","kind":"質問・要望","question":"廃棄物の量に合わせて、資源リサイクルも増えているということなので、そうしたら、それをやはりさらに前に進めていけるように、力を尽くしていただきたいと思います。そもそもごみを出すということを減らしていくということで、区としてもそのような姿勢だということなので、それをさらに進めていっていただきたいと思いますが、何か具体的な取組、考えていらっしゃることがあれば伺いたいと思います。","respondent":"品川品川区清掃事務所長","answer":"現状の製品プラスチックの中での課題というところですけれども、６月から進めているところですが、説明会等をやっていても区民の皆様の理解度が非常に高いというか、私も長年説明会などやっているのですけれども、これだけ。","id":"exchange-003"},{"speaker":"のだて委員","kind":"質問・要望","question":"そうですね。区民の方々は、何が対象なのかということは、多分日々迷うようになってしまうと思うので、ぜひこれは進めていっていただいて、多くリサイクルできるようにしていっていただきたいと思います。私もハンガーなどリサイクルされるということになると助かるなと思います。そういったところでも、区としても発信をしていっていただきたいと、これは要望しておきたいと思います。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"吉田委員","kind":"確認","question":"何点か伺いたいと思います。この古紙の中に平成３０年度から雑紙が入っているのかどうか伺いたいと思います。１点。それから、この集団回収の中の紙パックというものは、牛乳のパックのことをいっておられるのか、その点も確認したいと思います。それから、よく学校やＰＴＡが回収しているのは、この集団回収のほうに含まれて実績が出ているのか、その３点伺います。","respondent":"品川品川区清掃事務所長","answer":"集団回収としてこちらに登録をしてあれば、集団回収団体としてＰＴＡがやっているという傾向もありますし、学校によっては未登録でやっている場合もあるのかなと考えていますので、ちょっとＰＴＡの回収については。","id":"exchange-005"},{"speaker":"吉田委員","kind":"質問","question":"雑紙については分かりました。うちの会派の中で「このチラシ届いた」と聞いても「来ていない」という方が多いのですけれども、どのような形で、私は、「あっ、説明会しろしろと言ってきちんと配られている、すごい」と思ったのですが、みんな知らないと言うので、どのような配られ方だったのかなと思って伺いたいと思います。","respondent":"品川品川区清掃事務所長","answer":"製品プラスチックの説明会のほうですが、こちらについては、すみません、全戸配布をしているつもりなのですけれども、多分ちょっと一部に漏れがあったのかなと考えているところです。","id":"exchange-006"},{"speaker":"吉田委員","kind":"質問・要望","question":"だから、私が「これ配られた、配られた」と聞くから、「いや、うちは来ていないよ」と言うのであって、配られていないことに気づかないと思うのです。ですから、周辺でいうと配られていないというお答えのほうが多いので、その辺どうして配られなかったのか、調べていただけたらと思います。その辺、庁内での徹底といいますか、そのようなものはできているか、今後どのようにしていくか伺いたいと思います。","respondent":"河内環境課長","answer":"ただ、今の段階ではなかなか、エコルとごしにつきましては、原則紙のもの、いわゆるパラフィンを折ってというところで、非常に手が込んで、まだまだコスト的に悪いというところで、そういったところの目を厳しく見ながら、まだお時間がかかって本当に申し訳ないのですが。","id":"exchange-007"},{"speaker":"吉田委員","kind":"質問・要望","question":"今、本当に地球全体の危機的な状況なわけです。だから、その辺は若干ではない、とても危機感あおって、本当に全体で進めていかなければいけないことだということを、ぜひ徹底していただきたいと思います。これはもう強い要望で終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"何点かご質問させていただきたいと思います。最後に、プラスチック製品回収については６月からモデル回収を実施されていると思われますが、その中で、回収後に新たに見えてきた問題点や課題などがあれば教えてもらいたいと思います。","respondent":"品川品川区清掃事務所長","answer":"１点目、啓発講座のほうですけれども、すみません、少し説明不足がありました。親子の部分もやっておりまして、このごみ追っかけ隊というところに付随しまして、夏休みに親子でリサイクル工場を見学に行こうというツアーを、今年度も夏にやらせていただいております。","id":"exchange-009"},{"speaker":"ゆきた委員","kind":"質問","question":"各家庭では出し方は簡易的ですが、年間の予測で回収量が約４００トンであれば、毎週約８.３トンの選別作業になると思われます。改めて、東京資源回収センターでの現場の声など調査して、もう十分に検討されてきたことだと思われますが、この製品だけは種類別に出すなど、各家庭の回収の仕方で改善できることがあればと思いますけれども、その辺についてもう一度お聞きできればと思います。","respondent":"品川品川区清掃事務所長","answer":"ただ、これから量が増えていくことによって、そのような負担感も出てくるかなとも思いますし、１つには分別して出すという手段もあると思いますし、また、リサイクル技術というものは年々すごく進んできているところで。","id":"exchange-010"},{"speaker":"ひがし委員","kind":"提案","question":"私からは１点だけ、以前も提案させていただいたかもしれないのですけれども、結構分別というものは、区民の目からするといろいろと細かく分かれていて難しいなどと思ったりして、私も分別でごみを出すときにネットで調べて、どこに出したらいいのだろうなどと細かく調べているのですけれども、品川区のごみの分別一覧を開くと、紙ベースというか、あいうえお順で書かれていて。","respondent":"品川品川区清掃事務所長","answer":"今後また区民の方に使いやすいような形で、アプリやチャットのほう、何とかやっていきたいように進めていきたいと考えております。","id":"exchange-011"},{"speaker":"澤田委員","kind":"質問","question":"今ひがし委員が質問されたことも、私もちょっと気になっていたのですけれども、以前予算特別委員会で、ＡＩチャットボットどうでしょうかということを質問しましたが、今まだ検討中というか、いろいろ調べていただいているところなのでしょうか。","respondent":"品川品川区清掃事務所長","answer":"委員のおっしゃるとおりで、現在研究をしているところで、いろいろと物事を進めるためには、自治体の中では予算というハードルもありながら、そのようなところを越えていくように、日々努力をしているというような状況です。","id":"exchange-012"},{"speaker":"澤田委員","kind":"質問・要望","question":"そうですよね。別の質問なのですけれども、今のは要望で、すみません、リサイクル通信の発行部数が今約１万３,０００戸で、全戸配布ではないのではないですか。","respondent":"品川品川区清掃事務所長","answer":"リサイクル通信等の全戸配布、そうですね、もうどうしてもコスト面など、そのようなところと兼ね合いになると思いますので、ただ、やっていくことについては、非常に効果もあることですし、一定の方向で、何か啓発方法は随時考えていきたいと思いますので、１つの案として。","id":"exchange-013"},{"speaker":"澤田委員","kind":"質問","question":"ぜひお願いいたします。今度はオイシックスと産学官連携で、今度またちょっと違う話なのですが、中学生による食品ロス食材を活用したメニューを考案する取組が行われていると思うのですけれども、楽しみながら食材を無駄にしないことを学べる、すばらしい機会になっていると思います。今後、ほかの中学校で行われる予定はあるのでしょうか。いかがでしょうか。","respondent":"河内環境課長","answer":"一方で、この場合は特別な授業を設けていただいているというようなところもございまして、こういった要望があれば、環境課、あるいはエコルとごしの指定管理者なども柔軟に対応していきたいという姿勢は変わりございませんので。","id":"exchange-014"},{"speaker":"澤田委員","kind":"質問・要望","question":"ということは、この学校側などから要望がないと、特にやっていないということなのでしょうか。","respondent":"河内環境課長","answer":"そういったもののために、あえてですけれども、ここですと青稜中学校だとか、具体的な学校名も出しつつも、こういった連携を進めているので皆様いかがですかという啓発の力を入れていると。","id":"exchange-015"},{"speaker":"こしば委員","kind":"確認","question":"私からは資源ステーション回収のところで、確認の意味も込めてお聞きしたいのですけれども、まずこちらのステーションなのですが、１万か所ということで、これまずは１万か所以外のところでの資源回収というものはされておるのかしていないのか、その資源回収のごみの種類がありますけれども、それぞれの地域で曜日は異なっていると思うのですが、まずそこの確認だけさせてください。","respondent":"品川品川区清掃事務所長","answer":"すみません。ちょっと説明があれでしたけれども、そこの資源ステーションというものは、週１回回収している場所のことを示しています。","id":"exchange-016"},{"speaker":"こしば委員","kind":"質問","question":"それと、これからプラスチック製容器包装のところで、これまでは燃やせるごみの中で扱われていたプラスチックが、今度はプラスチックのほうに入ってくるとなると、大量にごみが増えてくると思うのですけれども、その辺の回収車両への影響含めて、どういったように見込んでおるのか、ちょっと教えていただければと思います。","respondent":"品川品川区清掃事務所長","answer":"状況が変わり次第、車のほうについては対応していこうかと考えています。","id":"exchange-017"},{"speaker":"こしば委員","kind":"意見","question":"どうもありがとうあります。現状では、今のところは車の台数に、恐らく大きな変化はないだろうというような見立てということ、かしこまりました。その辺との連携について、現状も含めて、今後についてのお話をいただければと思います。","respondent":"品川品川区清掃事務所長","answer":"このプラスチック関係で、やはり各企業も製造者責任というところを負われているところがありまして、今割と、例えば大井町のほうのイトーヨーカ堂など、そのような大手スーパーを利用した形で、そこに回収ボックスを置いて、やはりどうしても各企業。","id":"exchange-018"},{"speaker":"こしば委員","kind":"質問・要望","question":"そうですね。企業もやはりどうしても利益を求めるので、関心はあるのだけれどもなかなかその先に進まないというところもあるのですが、それでも必ずどこか着地点が見いだせてくるのかなという期待を持っておりますので、ここからまたよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"西村委員","kind":"質問・要望","question":"今日まさに地元が資源ごみの日でして、今のこしば委員の質問にもありましたけれども、資源ごみの出し方についてちょっと伺いたいなと。正しいごみの捨て方のルールを知っていただくだけではない課題があるような気がしておりまして、お考えがあればお聞かせいただきたい。","respondent":"品川品川区清掃事務所長","answer":"例えばボックスが足りなければ、清掃事務所のほうにご連絡いただければ、増やすということは容易にできるところなのですけれども、ただ、その連絡するというところを分かっていない方も当然いらっしゃると思いますので、今やっている対策としましては。","id":"exchange-020"},{"speaker":"新妻委員","kind":"質問・要望","question":"ご説明ありがとうございました。ちょっとまず１点、最初に確認させていただきたいことが、区有庁舎の中でもしっかりと分別をしてリサイクルされていると思うのですけれども、区有庁舎における、このリサイクルをしている中での効果というか、評価をどうされているのかというところをちょっとお聞きしたいと思います。","respondent":"品川品川区清掃事務所長","answer":"ただ、この庁舎については、リサイクルを進めるところでは、清掃事務所のほうもいろいろと対応しているところがありまして、分別方法については、同様に、一般家庭と同様な形で分別のほうを進めて、効果としましては、大分大きな量をリサイクルに回しているような状況ですので。","id":"exchange-021"},{"speaker":"新妻委員","kind":"質問・要望","question":"これは非常に難しいことだと思うのですが、今後、区としての検討をされている中で、この２つに関してどのようなことを検討されているのかということをお知らせいただきたいと思います。今後、またもう一層の食品ロス削減の取組として、そのような民間事業者と連携をしての取組を、自治体として、品川区としてやっていただきたいと思うのですが、そのようなご検討や、またお考えをお聞きしたいと思います。","respondent":"品川品川区清掃事務所長、河内環境課長","answer":"こちらをうまく、何かこう活用してできないかなというところで、現在は進めているようなところがあります。ただ、これは実際にやるとなると、現在の可燃ごみの中の生ごみを分別して出してくださいということになります。そういったところの知見も応用しながら、やはり食を見つめ直し、日本のエネルギーやＣＯ２について見つめ直すものを、しっかり機会を捉えて広げていきたいというところで。","id":"exchange-022"},{"speaker":"須貝委員","kind":"質問","question":"何かよい方法があればいいのかと思うのですが。それで、そのようなところに一度、恐らくやられていると思うのですけれども、マンションにご協力いただいて、何か見やすいパネル等を、一定期間でもいいですから、１か月間ちょっとやってください、半年後にまた掲示してくださいというような、何かそのような工夫をして、出すけれども、そのとき一緒に見られるというような対応も大事なのかなと。１軒１軒。","respondent":"品川品川区清掃事務所長","answer":"例えば資源ステーションのところで何かあるときには、先ほども説明したとおりパトロールの職員などが個別に対応するというような状況もありますし、あと、そうですね、看板設置なども、やったりもしておりますので、ただ、何というのですか、このような対応をすると。","id":"exchange-023"},{"speaker":"須貝委員","kind":"質問・要望","question":"本当に大変な事業だと思います。外国の方もいらっしゃるので、できれば、その若者をターゲットにして、できるだけ掲示してどうなのかなというものを、１人でも２人でもきちんと分別して出してもらえるように、今後も努力をしていただきたいと思います。ここでちょっと２点だけお伺いしますが、太陽光パネルというものが３０年たつと寿命が来るという話を聞いています。私もお総菜、結構買います。","respondent":"河内環境課長","answer":"売る側には売る側の理屈もあるかと思うのですが、一方、例えば恵方巻きの問題など、昨今あったかと思います。そういったところを踏まえまして、こういったところの改善方向に、区としてしっかり取り組んでいきたいという考えです。","id":"exchange-024"},{"speaker":"せりざわ委員","kind":"提案","question":"何点かお伺いをしたいと思います。それをぜひ清掃事務所でやってほしいなと思って、また、これから資源循環推進担当課ですか、新しいものができるという話もあると思うので、ぜひこれは予算をしっかり取り続けてほしいなと思っています。この２つ、お話をお伺いできればと思います。","respondent":"品川品川区清掃事務所長","answer":"単価が教育委員会の大体見込み、やっている実績ですと、キロ２０円ぐらいになるのです。そうすると、やはりどうしても億超えるお金が必要になってきます。そういったコスト面もいろいろ考えながらやっていく必要があるかなと考えています。","id":"exchange-025"},{"speaker":"せりざわ委員","kind":"質問・要望","question":"事業者などから聞くのですけれども、それは多分持ち去られたかどうか分からなくなっただけなのではないかなとも思っているので、そのような意味でいえば、やはりまず今の拠点回収の段階で持ち去っているかどうかをしっかり、逆に今時点で取り締まっておかなければ、戸別回収に今後なったときに、もう取締りがかなり難しくなるのだと思うので、拠点回収の段階でしっかり、その人が生計立てているということは。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"つる委員","kind":"提案","question":"大丈夫ですか。そのようなものがある。こちらがやろうとしていることの趣旨をどう伝えていくかと。ですから、全体合わせて、この辺の、何というのでしょう、いわゆる区民運動としてどう全体を動かしていく、何かツールという部分や、今申し上げた広報の工夫など。感謝。ですから、ぜひそのような広報の工夫や、区民運動をどう今後持っていくかということを、ちょっと全体の話で教えていただければと思います。","respondent":"河内環境課長、品川品川区清掃事務所長","answer":"そういったところも含めまして、全体の区民の見方が変わるように、区民運動、国民運動と、大変重いテーマですが、重いテーマだけに、区民の皆さんがお気軽にということは変ですけれども。清掃事務所についても、基本的に環境課と連携した形で、広報のほう進めていけることが一番理想かと思いますので、そのような方向性でやっていきたいというところと、それから分別等、そのようなところも、既存のもので。","id":"exchange-027"},{"speaker":"つる委員","kind":"質問・要望","question":"そのような視点のもったいないを持っていただきたいなと思っています。ですから、そのような工夫というところをまさにやっていただきたいなと思います。そういったところなので、今後その辺を展開していくに当たって、ぜひ、今の広報の工夫、これはぜひもったいなくならないようにやっていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"鈴木副委員長","kind":"質問・要望","question":"そのプラスチックのリサイクルというものが、地球温暖化にとってもすごく重要なのだという、ＣＯ２削減にとってもとても大事なことなのだというところは、ぜひその啓発の中に入れていただきたいなと思っているのですけれども、ここ、サーマルリサイクルということも、区としても進めてきた部分であると思うのですが、サーマルリサイクルよりもプラスチックのリサイクルということが。","respondent":"品川品川区清掃事務所長","answer":"当然プラスチックは、多分普通の可燃ごみの中でも、ＣＯ２発生量は非常に多いものですので、そういった点も説明していこうかなと考えています。","id":"exchange-029"},{"speaker":"鈴木副委員長","kind":"質問・要望","question":"そのようなところからすると、もしも処分というようななことになるのであれば、区役所でもいいですし、地域センターなどでもいいですし、そのようなところで、もし必要な方があったらご自由にお持ちくださいというような形でしていただくと、助かる方はすごくたくさんいらっしゃるのではないかなと思っていまして、清掃の方からも。","respondent":"平原防災課長","answer":"今、災害備蓄品の廃棄のお話がありましたので、私のほうからお答えします。以前こちらで備蓄物資のお話をさせていただいたときに、担当の課長から、現在品川区における災害備蓄品、水、食料等につきましては、全て有効活用させていただいているというお話をさせていただきました。","id":"exchange-030"},{"speaker":"鈴木副委員長","kind":"質問・要望","question":"もしもそのようなことが実際にあるのだとしたら、ぜひそのように、困っている方にとってはすごく助かるものなので、そのようなご活用も含めてご検討いただきたいということで、要望させていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"}]},{"id":"topic-02","title":"環境学習動画","agenda":"環境学習動画","exchanges":[{"speaker":"つる委員","kind":"確認","question":"ごめんなさい。１点だけ確認は、これ今年度、たしか夏配布されなかったＥＣＯｍｉｃ、エコラが載っている漫画のものが動画になったという、当然内容など充実されているのでしょうけれども、そのようなことでいいのか教えてください。","respondent":"河内環境課長","answer":"紙冊子ですが、電子化することによりまして、利用される分母の計算も、そちらの部分につきましては、全て電子化によりまして展開を予定しております。","id":"exchange-032"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/556800?Template=document&Id=6646#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=19&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":46042,"voices":91}},{"id":"r05-20231130-10","meetingId":"r05-cm11","date":"2023年11月30日","dateIso":"2023-11-30","committee":"議会運営委員会","time":"午後 ０時４５分～午後 ０時４７分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/105128?Template=document&Id=5526#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":1361,"voices":8}},{"id":"r05-20231205-10","meetingId":"r05-cm12","date":"2023年12月5日","dateIso":"2023-12-05","committee":"議会運営委員会","time":"午前１０時３０分～午前１１時４０分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を27件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"陳情の理由の一番上にあるように、委員会での質疑というのは、付託をされて、実質的な審議をやるものですから、区民の皆さん、とりわけ請願や陳情を出した方にとってはかなり関心が高いものだと思います。何といっても開かれた議会をつくる上でも、ライブ配信というのは、ルールさえつくれば、すぐにでも実施できると私は思いますので、すべきだと思いますけれども、皆さんどのようにお考えなのか。","respondent":"あくつ副議長、大澤区議会事務局長","answer":"今、安藤委員のお話の中で、本会議場では傍聴者によるＳＮＳでのライブ配信は認められているというお話があったのですが。録画を許可するということで、この後の配信については制限をしていないということで、許可をしているという考え方ではございません。録画は認められている。そのまま流すかどうかは、議会として許可をしているということではないということは確認させていただきました。","id":"exchange-001"},{"speaker":"須貝委員","kind":"質問","question":"広い委員会室が物理的にできた、またはそういうところで委員会、いろいろ審議できるような場所があったら、ライブ配信ですか、そういうものもやっていいと私は思うのですが、今の段階でそこに大勢の傍聴者が見えて、さらに撮影云々ということになると、それはちょっといかがなものかなというふうに思いますので、広い委員会室ができたときに、利用できるようなときがきたら。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"山本委員","kind":"確認","question":"一方で、一部だけ切り出されたときに誤って伝わるといったリスクもあるかなというふうに思っております。区民の皆様に正しい情報を展開していくという責任がありますので、誤解を生むように切り取られて配信された場合などに備えて、やはり区議会が発信して、確認することができる状態にしておくことは、十分に考慮する必要があるというふうに考えております。陳情第４７号については……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"安藤委員","kind":"質問","question":"許可でないというのは、正確には分かりました。今は機器とかも様々ありますので、狭いスペースの中でも配信できるようなルールをつくればいいのではないかと私は思うので、そこら辺についてもクリアできるのではないかというふうに思いますけれども、皆さん、そこら辺はどうですか。スペース上、問題があるとか、ちょっと厳しいのではないかとか、そういった点についてはどうでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"山本委員","kind":"確認","question":"陳情第４７号についても併せて申し上げます。その中で、正しいものは何かということが確認できる状況にしておくことは、区民の皆様に区議会の情報を正しく伝えていくということでは、とても大事であると思います。これと併せて予算特別委員会、決算特別委員会についても傍聴者の皆様のライブ配信も考えていくべきであるというふうに考えております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"須貝委員","kind":"確認","question":"先ほど申し上げましたけれども、いずれはこういう方向に、ライブ配信を各常任委員会で行うと思うのですが、繰り返しますと、まずハードの面で、スペースがあるところで多くの方が見に来られるということを想定して考えて、十分な座席数、それから傍聴できる場所があるかどうかを確認した上、さらにせっかく議会改革のための会議があるのですから、そちらのほうで十分審議されて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"安藤委員","kind":"提案","question":"区民に開かれた議会という議会改革の中心中の中心だと思うのですけれども、これを進める上で重要なことだなと私は思っていますし、私は個人的にもかなりこの問題は打開すべきだなということで、何回か提案もさせていただいていたのです。質問があるのですが、そもそも委員会は委員会室でという規定については、特に規定というのはないということでよろしかったのか、ちょっとそこだけ確認させてもらえますか。","respondent":"大澤区議会事務局長","answer":"委員会は委員会室でやらなければいけないという規則はございませんけれども、どこでやるかというのは議会運営委員会の中でその都度確認しているものだと認識しています。","id":"exchange-007"},{"speaker":"安藤委員","kind":"提案","question":"理事者の入替えとかのところは、席数が課題になるかもしれませんけれども、現状の第一委員会室でも、パイプ椅子を並べて後ろのほうに待機していただくということもあります。様々な課題はあると思いますが、ぜひこれは踏み出してみるというのが、陳情者の方、区民の皆さんがこれだけ議会の議論に関心を持っているということなのですから、それに応えるべきなのではないかなというふうに私は思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-008"},{"speaker":"塚本委員","kind":"質問","question":"本日結論を出します。結論は不採択です。他自治体でも同じようなことがあったりもしていますし、そういうふうに捉えておりますので、不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"安藤委員","kind":"提案","question":"本日結論を出して、採択を主張します。やはり開かれた議会をつくる上で、特に委員会の中継を強く求める区民の皆さんの提案ということもありますので、現状すぐにもできる工夫ということで、こういうことをやっていくというのは、すごく議会改革につながると私は思いますので、採択です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-010"},{"speaker":"須貝委員","kind":"意見","question":"先ほども申し上げましたが、結論を出すということと、不採択です。初めてこういう陳情が出てきて、こういうふうにライブ配信して区民に見せるということはいいことなのです。ただ、今、物理的な問題とかが様々あるので、そこは議会にある議会改革を検討する会議でしっかり審議して、そちらの場所で皆さんで検討されて、最後に議会運営委員会で決められたらいいのかなというふうに思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"},{"speaker":"塚本委員","kind":"意見","question":"理由としては、本会議場であれば傍聴できるではないかという視点での陳情なのですけれども、傍聴が可能となるということは、平場で一問一答という非常に真剣な議論がなされる予算特別委員会、決算特別委員会ということで、まず委員、理事者の発言がしっかり保たれることがあって、その上で傍聴ということをしっかりと考えていくということだと思いますので、本会議場で今の予算特別委員会。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-012"},{"speaker":"安藤委員","kind":"意見","question":"本日結論を出すで、採択なのですが、今、新庁舎の検討も進んでおりますけれども、イレギュラーなことだとは思うのですけれども、やはり新庁舎での決算および予算の特別委員会は、恐らくフルスペックの傍聴は課題が解消されると思うのですけれども、あまりに時間もかかりますし、それまで暫定的に、今あるものを使って。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-013"},{"speaker":"須貝委員","kind":"意見","question":"私も本日結論を出すということと、不採択でお願いします。これも第４６号と同様に、初めての陳情なので、今後、議会改革を検討する会議でしっかり議論して、最後、議会運営委員会で決められたらいいかと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-014"}]},{"id":"topic-02","title":"議会運営上の変更","agenda":"議会運営上の変更","exchanges":[{"speaker":"須貝委員","kind":"意見","question":"今回議席を変更するということで、理由もなく変更するというのはまずいと思うのです。議会運営委員会の中で、こういう申出があって、こういう状況なので議席を変更しましたというふうなことをちゃんと残しておくべきだと思うのです。そうしないと、今後勝手にどんどん移動できることになってしまうので、その辺、委員長はどう思われますか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"},{"speaker":"松永委員","kind":"質問・要望","question":"前回の一般質問の際も、少しお話をさせていただきまして、木村議員に関しては足の具合が少し悪くて、この間は椅子に座って一般質問させていただいたのですが、やはり段差があるとちょっと厳しい部分がありまして、本人からも、ぜひそうしていただきたいということで、今回このような形で皆さんにご報告をしています。ぜひご理解いただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"}]},{"id":"topic-03","title":"令和５年第４回定例会","agenda":"令和５年第４回定例会","exchanges":[{"speaker":"安藤委員","kind":"提案","question":"もしこの議会運営委員会の場で賛同が得られれば、ぜひ修正した内容で本会議に提案していただければと思っています。修正内容なのですけれども、口頭で説明するよりも、文章があったほうが説明しやすいので、本当に一部なのですけれども、この資料を配付させていただきたいのですけれども、委員長、よろしいですか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-017"},{"speaker":"安藤委員","kind":"提案","question":"提案内容なのですが、案の、第１段落の文章の最後の部分、「現地は人道的に深刻な危機に直面している」というのは、そのとおりだと思うのです。よいと思うのですけれども、なぜそうなっているかという前段の部分なのです。この案文では、「ハマスとイスラエルによるパレスチナ・ガザ地区での戦闘により」となっています。皆さんのご意見を聞かせていただければと考えています。いかがでしょうか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-018"},{"speaker":"高橋（伸）委員長","kind":"提案","question":"委員長としては、お示しした案のとおりで、議案として提案したいので、よろしくお願いします。いただいた資料に関しては、資料として預からせていただきますので、よろしくお願いいたします。今のご発言に対して何かほかにご発言はありますでしょうか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"},{"speaker":"須貝委員","kind":"質問","question":"このようにハマスの無差別攻撃とか、ミサイルによるパレスチナ・ガザ地区への攻撃、報道を聞いていると、その双方にそれぞれ主張はあるのですよね。かなり宗教絡みで、それぞれの言い分はまさにそのとおりで、ただ、やり過ぎ、どうだ云々となってくると思うのですけれども、そこは我々が文面で明記するものではないのかなという気がします。それはちょっと皆さんのご見解をお聞きしてと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"せりざわ委員","kind":"意見","question":"そもそもは即時停戦が目的だと思いますので、その意味で言えば、委員長案で進めていただいていいのかなと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-021"},{"speaker":"塚本委員","kind":"意見","question":"私も同様に委員長案で出していただければと思います。安藤委員は、ちょっとしたというような感じでおっしゃっていましたけれども、文字づらは少しの変更に見えるけれども、内容の方向性の変更は相当なものなので、会派に持って帰って相当議論しないと、これはなかなかいけないという部分もありますし、物理的な時間の問題もありますので、委員長案で進めていただけるといいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-022"},{"speaker":"松永委員","kind":"意見","question":"私たちの会派といたしましても、先ほど塚本委員からありましたけれども、時間的な問題というのもありますし、あとはどちらが悪いというわけではなくて、まず戦争自体をやめないといけないということを主張していきたいというふうに思っておりますので、委員長案のとおりでお願いしたいと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-023"},{"speaker":"安藤委員","kind":"提案","question":"皆さん、ご意見をありがとうあります。くどいようですけれども、停戦を求める決議を議会として上げるということに関しては、すごく意味があると思いますので、今回私たちの提案が合意とならなかったのはちょっと残念ですけれども、こういう決議にはもちろん提案者になった上で賛成したいと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-024"}]},{"id":"topic-04","title":"通年での服装軽装化","agenda":"通年での服装軽装化","exchanges":[{"speaker":"安藤委員","kind":"確認","question":"その他の(4)なのですけれども、例年２日間ぐらいに分かれていたような気がするのですが、１日で全部終わるのかということ、それと当日の説明資料を電子データでという話だったのか、そこら辺をちょっと確認させてください。","respondent":"大澤区議会事務局長","answer":"これまで２日間でやっていたのを１日にするということで、１日で終わるように、今、時間の調整をしているところと聞いてあります。資料ですけれども、資料は説明の際に配付というふうに聞いてあります。データのお話は、予算プレスのお話です。","id":"exchange-025"},{"speaker":"安藤委員","kind":"質問・要望","question":"どちらに要望すればよいのか分からないですけれども、２点ありまして、一つは結構大事な説明なので、例年並みの時間は各会派取っていただければなという要望なのですけれども、もう一つは、プレス資料の件も、うちの会派としてはぜひ紙ベースでもいただきたいなと思うのです。そういった要望があるのですけれども、それは伝えてもらえますでしょうか。","respondent":"大澤区議会事務局長","answer":"ご要望としてどちらかにお伝えすることはできます。","id":"exchange-026"},{"speaker":"須貝委員","kind":"質問","question":"今の件ですけれども、我々はもうタブレットのほうに、ペーパーレスでやっていかなければいけないと思うので、そういう方向で共産党にもご協力願ったほうが良いのではないでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/105128?Template=document&Id=5528#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":20144,"voices":95}},{"id":"r05-20231226-10","meetingId":"r05-cm12","date":"2023年12月26日","dateIso":"2023-12-26","committee":"議会運営委員会","time":"午前 ９時００分～午前 ９時３７分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を12件抜き出しています。","topics":[{"id":"topic-01","title":"令和５年第２回臨時会","agenda":"令和５年第２回臨時会","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"通常でしたら議案審査の２日前に資料をいただくのですが、今回は明日なので、できれば早めに補正予算議案の資料をいただければと思うのですけれども、そこら辺はいかがでしょうか。","respondent":"桑村副区長","answer":"ご意見として受け止めしますが、一つは、議案説明会で一定の議案説明をしないうちに説明資料が公式にいくというのは、なかなか難しいのかと思います。","id":"exchange-001"}]},{"id":"topic-02","title":"会派変更届","agenda":"会派変更届","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"その理由は、日本共産党品川地区委員会名で見解を発表し、その中身が新聞報道でも伝えられましたように、中塚区議が、猥褻な言動による性暴力、セクシュアルハラスメントを行っていたこと、それが被害者からの告発で判明し、本人にも事実確認したところ、全て事実と認めたことによるものであります。被害者は、日常生活を送ることに困難を抱えることになりました。したがって、党を除籍といたしました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"せりざわ委員","kind":"質問・要望","question":"念のため確認させていただきたいのですが、１２月１２日、１３日と、大手新聞社の報道があって、私も報道ベースでは何となく伺ってはいるのですが、品川区議会として、いろいろお問い合わせもいただいているので念のため確認で、まず、事実として、地区委員会からの調査があって事実が認定されたというようなお話があったと思うのですが、会派としてご本人に確認をされたのでしょうかということが１点。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"安藤委員","kind":"確認","question":"本人と直接話して事実確認を行ったところ、全て事実と認めております。見解にもありますように、そういったことです。会派としても確認して、会派としても判断したです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"せりざわ委員","kind":"質問","question":"もう１点だけ。少し厳しい指摘になりますが、そうすると、今回、会派としても、もしくは党としても、地区委員会としても、セクハラという事実認定をされたということだと思いますが、今回、離脱になって無所属にはなりますけれども、区議会にセクハラをされた方が今後も居るわけであります。それに対して、会派から何か行動を起こすというようなイメージはあるのでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"安藤委員","kind":"質問・要望","question":"共産党からは、辞職勧告決議案等を出す考えはないのですが、ただ、議員辞職すべきだと強く思っておりますし、共産党としても、本人に繰り返し辞職を求めてきたところです。仮に決議案が出された場合は、賛成するつもりです。その際も、繰り返すようですが、二次被害を避けるという観点から、地区委員会の見解以上のことをお話しすることはいたしません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"須貝委員","kind":"意見","question":"今、共産党のお話を聞いたのですが、我々も新聞報道、それから、共産党の赤旗新聞で公表されているという話を聞きまして、文面も読ませていただきました。今この場で話すべきかどうかは分かりません。で委員長のほうからなのかもしれませんが、私は、明確にこういう事実を相互に認めているということならば、議員辞職勧告決議案を品川区議会として提出するべきだと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"},{"speaker":"塚本委員","kind":"質問・要望","question":"これは事務局にお聞きしたいのですけれども、いわゆる過去の事例などで、何かこういった対応をとってきたということがあったりするのか。あるいは、明文化されないまでも、内規みたいなものがあって、こういう対応をとるように定められているみたいなところがあるのか、そこのところを教えていただきたいと思います。","respondent":"大澤区議会事務局長","answer":"品川区議会としては、過去にこのような事例はございません。規程も特には、今のところはないです。","id":"exchange-008"},{"speaker":"塚本委員","kind":"質問","question":"そうすると、いわゆる辞職勧告決議案というのは、時々、他の自治体などでも出てきたりして見聞きをするのですけれども、ほかには何かそういう、問責決議というものがあったか、そういうものとか、何か幾つか、議会として、他の自治体の例などを踏まえた上での対応の在り方というのか、手法というのか、そういうものが、どういったものになるのかということが今の段階で分かれば教えてください。","respondent":"大澤区議会事務局長","answer":"件数としては少ないですけれども、被害者から陳情書をもって決議案を提出したりですとか、あとは、辞職勧告のほかには、不祥事には毅然と対応し、議会の信頼回復に努めることを誓う決議案を提出している場合がございました。","id":"exchange-009"},{"speaker":"塚本委員","kind":"意見","question":"分かりました。今後、区議会として必要な対応、とるべき対応は、少し検討する必要もあるかと思いますけれども、その一方で、また、共産党の会派としては、本人にも話を聞いているというお話でしたけれども、本人から、区議会として弁明等を聞く機会も一定必要かなとも思います。いずれにしても、また新たな検討ということでは、何ができるかということを考えていく必要があるかと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-010"},{"speaker":"安藤委員","kind":"提案","question":"辞職勧告決議については、共産党から必ず出さないということを今の時点で明言してしまうこともどうかなと、今少し思い直しているところがありまして、なぜ出さないと言ったかというと、繰り返しますけれども、私たちとしては、そういったことを起こした以上は、議員は辞めるべきだと強く思っておりますし、それはもちろん何回も言ったわけですが、辞職勧告決議となりますと、私たちとしては。","respondent":"あくつ副議長","answer":"いわゆる本人からの何かしらの発信がない中で、それは共産党しか分かり得ない状況であって、そのようにご主張されるのであれば、先ほど、その可能性は排除しないというお言葉もいただいたので、それはよくよくご検討いただきたいと思います。","id":"exchange-011"},{"speaker":"山本委員","kind":"意見","question":"当会派としても、今までの話を踏まえましても、議会として何らかの対策をとっていくべきではないかと考えております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-012"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/105128?Template=document&Id=5530#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":12922,"voices":63}},{"id":"r05-20231227-6","meetingId":"r05-cm12","date":"2023年12月27日","dateIso":"2023-12-27","committee":"区民委員会","time":"午前１０時０７分～午前１１時１７分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を19件抜き出しています。","topics":[{"id":"topic-01","title":"第１０３号議案、令和５年度品川区一般会計補正予算（歳出等 区民委員会所管分）","agenda":"第１０３号議案、令和５年度品川区一般会計補正予算（歳出等 区民委員会所管分）","exchanges":[{"speaker":"山本委員","kind":"質問","question":"ご説明、ありがとうございました。本件は長期化する物価対策ということで、区民生活の下支えと区内経済の活性化のために必要な取組と評価しております。プレミアム付区内共通商品券事業についてお伺いします。例年と比較して発行総額を増額したこと、それからプレミアム率を増加させたこと、それから前倒しにされたことというのはどういった意図や背景があるのかという、区の考えをお聞かせください。","respondent":"小林商業・ものづくり課長","answer":"こうした中で、消費喚起を行うことによりまして、区民生活の下支え、区内経済の活性化というところで、発行総額につきましても例年に比べて大きく増やし、かつプレミアム率も大きく増やすとやはり消費喚起も大きくなるというところで。","id":"exchange-001"},{"speaker":"山本委員","kind":"質問","question":"ご回答ありがとうあります。その中で、これは区民生活の下支えと区内経済の活性化の両立が図れるという意図だと思うのですけれども、これまでの利用実績の中で、品川区在住の方がどれぐらい使われているのかというのが、もし分かるようでしたら教えていただければと思います。","respondent":"小林商業・ものづくり課長","answer":"そのことを通じまして、商店街などでたくさん消費をしていただくというようなことを目的としている事業です。","id":"exchange-002"},{"speaker":"山本委員","kind":"質問","question":"質問の意図がうまく伝わらなかったようなので、もう一回質問しますと、ご説明のとおり、このプレミアム付区内共通商品券については、品川区在住にかかわらず購入ができると理解しております。その中で、区民の方がどれだけ使われているのかということ、買われているかということを把握したいとお聞きした次第です。これは申込のときに分かるのかどうかというところも含めて、ご回答いただければと思います。","respondent":"小林商業・ものづくり課長","answer":"ただ、実際に住所別の購入予定者がどういうところにいらっしゃるかというと、ほとんどが区内の方でいらっしゃって、大田区、目黒区、世田谷区、港区の方も若干いらっしゃいますけれども、大半は区内の方ということで把握しています。","id":"exchange-003"},{"speaker":"山本委員","kind":"質問・要望","question":"ご答弁ありがとうございました。やはりこういった実態というのはしっかりと確認していったほうが、せっかく施策としてやりますので、効果検証というところで言うと、区民の方がしっかり使われているのかどうかという確認を、今後の機会ではやっていただきたいと思います。これは要望です。続いて、キャッシュレス決済ポイント還元事業について伺います。幾つか確認をさせてください。","respondent":"小林商業・ものづくり課長","answer":"先ほど少し申し上げたように、令和４年度に実施した場合でいきますと、４事業者からいろいろデータも頂くのですけれども、その中で、やはり我々としましては生活に身近な分野で、実際区民以外の方もいらっしゃいますけれども。","id":"exchange-004"},{"speaker":"山本委員","kind":"質問・要望","question":"何点か確認をさせていただければと思います。これは先ほどのご答弁の中では分かりませんでしたので、改めて教えていただきたいと思います。それから債務負担行為についてのご答弁なのですけれども、法令に基づき契約準備が必要だということで、必要なことはしっかりやっていただければと思うのですが、これは業務委託先、相手方というのは特に決まっているのでしょうか。それとも今後選定されるのでしょうか。","respondent":"小林商業・ものづくり課長","answer":"契約の委託先が決まっているのかですけれども、これから議決いただいて調整ですので、まだ現時点で具体的にどうするかというところは、これからの検討です。","id":"exchange-005"},{"speaker":"山本委員","kind":"質問・要望","question":"ご答弁ありがとうございました。スケジュールでこれぐらいの時間がかかるということですけれども、世田谷区、渋谷区のように一度インフラを整えてしまえば、その後は迅速にこういった景気刺激策などができるということもありますので、そういったところについて検討をしていただきたいということで、これは要望で質問を終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"えのした委員","kind":"質問","question":"そういった方は多いので、この周知方法として毎回周知をどうするかというのはありますが、それはこのキャッシュレス決済で２０％のポイント還元を行いますという周知だと思うのですが、できれば一番いいのはやはり区民の方に多く利用していただければ、区民の方も喜ばれて、区内の事業者も潤う、活性化するということになってつながってくると私も考えていますので、例えば今まで特に高齢者の方に対して。","respondent":"小林商業・ものづくり課長","answer":"区民利用を広げるためにですけれども、我々としましては広報しながわをはじめ、ホームページの専用ページも作って前回は実施して、幅広く目に留まるようにして使っていただくということで、我々は今回もこの事業が幅広く皆さんの目に留まるように。","id":"exchange-007"},{"speaker":"えのした委員","kind":"意見","question":"やはり周知もすごく重要なのですが、区民の方へより丁寧なアドバイスではないですけれども、それをお願いしたいです。スマホは高齢者の方も結構お持ちで、ＬＩＮＥなどは特にお孫さんですとかとの写真のやりとりなどに使っているような光景が見受けられるのですけれども、支払に関してはやはりまだまだ利用されている方が少ないと思いますので、そこら辺の取組も今後進めていっていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-008"},{"speaker":"あくつ委員","kind":"質問・要望","question":"かなり切れ目がない形で、区民と区民生活と、あと事業者の事業を支援するという形になっていると思うのですけれども、その辺りの、補正予算というのは我々の認識ではやはり年度内に使い切らなくてはいけないという認識があったのですが、繰越明許費と債務負担行為と、先ほども山本委員の質問でありましたが、債務負担行為については。","respondent":"小林商業・ものづくり課長","answer":"切れ目のない経済対策ですけれども、ご指摘のとおり、まだ報道レベルではありますけれども、東京都が先日、報道にあるような事業というところでは、補正予算のプレスリリースで「暮らし向き向上緊急サポート事業」ということで。","id":"exchange-009"},{"speaker":"あくつ委員","kind":"質問","question":"意図はよく分かりました。それでもう一点だけ。大丈夫だとは思うのですけれども、国のほうはこの補正予算ですから、本来であれば年度内で消化というか、それを使わなければいけない。繰越明許費でも来年度もいいのですよということで、これは大丈夫なのでしょうか。","respondent":"小林商業・ものづくり課長","answer":"今回、都の支出金という形で入れるのが、紙のプレミアム付区内共通商品券事業のほうですけれども、こちらは企画部にも確認をして、こういったような予算執行で問題ないかというところで調整して、今回実施するものです。","id":"exchange-010"},{"speaker":"あくつ委員","kind":"質問・要望","question":"三億数千万円の予算の中で２億１,０００万円をこちらに投入されるということでしたので、非常に割合が大きいというところで、それは全然ウェルカムですし、我々も要望していたことですからありがたいと考えていますが、スキームについてはまた私たちも研究していきたいと思います。もう一つだけ。ただ一方で都のほうなのですが、都内のコンビニや飲食店、美・理容店で使えるというような報道があります。","respondent":"小林商業・ものづくり課長","answer":"先ほどご指摘のありましたような区内のスーパーでいきますと、中小企業基本法で中小企業に位置づけられる資本金なり従業員の数というのも確認しつつ運営事業者と調整しまして、その中で分類されるものにつきましては、先ほど具体名を挙げていただきましたけれども。","id":"exchange-011"},{"speaker":"あくつ委員","kind":"質問・要望","question":"それはどちらに重きを置くのかというところで、そこについてはぜひ、例えばタバコには使えないと、物価高騰対策重点支援地方創生臨時交付金のものはタバコを買ってはいけませんなどいろいろ縛りがあるのですけれども、そういうところも、これから全く同じものをやるということではなくて、この前アンケートを取ったのであるならば、また分析をしているのであれば。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"藤原委員","kind":"質問","question":"プレミアム付区内共通商品券についてお伺いしますが、今回内容がよく分からないのですけれども、これは１冊１万円で、１人１冊しか買えないのですか。買える上限はあるのですか。買える範囲というのはどうなっているのですか。申し込む方が多ければ調整して、希望の商品券の数、金額まではいかないかもしれないけれども、調整するのですか。何で今回こういう形の事業内容の説明になったのでしょうか。","respondent":"小林商業・ものづくり課長","answer":"チラシなどでは、これはまだ作成はしていない段階ですけれども、品川区商店街連合会のほうで発行する冊子ではタイトルがございまして、一番上のところに、今委員からご指摘があったような。","id":"exchange-013"},{"speaker":"藤原委員","kind":"質問","question":"今の説明だと、これから品川区商店街連合会と調整して決めていくということですか。そういうお話であるならば、先ほど区外の方にもというお話があったけれども、区内の方の分の数を減らして区外の方にというのは、私個人の考えでは、区民への施策ですから、まずは区民の申込希望を優先して、その後にという思いが私の気持ちの中にはあるのです。","respondent":"小林商業・ものづくり課長","answer":"品川区商店街連合会と調整というところではありますけれども、今、話としてはもう既に進めているところでございまして、４冊というのは過去ずっと一つのルールで申込の上限というか、幅広く買っていただくという観点からやっているところですので。","id":"exchange-014"},{"speaker":"藤原委員","kind":"質問・要望","question":"最後に、同じことを何回も言うかもしれませんけれども、せっかくこうやって補正予算に出ているのだから、４冊までですよとか、４冊以上になったら抽選ですよというのは、そういう大事なことはやはり資料に書いておいてほしいです。だからそういう意味において、紙ベースですけれども、書ける情報というのは、私はやはり書いておいていただきたいと思うのですけれども、その辺についてはいかがでしょうか。","respondent":"小林商業・ものづくり課長","answer":"記載内容につきましてはより中身について、先ほど申し上げたような４冊ですとかそういうところも含めて、次回またこのようなご説明、あるいは別の事業につきましても気をつけてまいりたいと考えております。もう一点、他自治体の例で大きいプレミアム率もあるのではないかです。","id":"exchange-015"},{"speaker":"藤原委員","kind":"質問","question":"そこの辺をしっかり押さえておかないと、ほかの自治体は高い、何で品川区は２０％なのかと聞かれたときに、私たちも議員ですから、聞かれたときにちゃんとした話を地域に持っていかないといけないわけです。だから、その辺についてしっかり教えてくださいと質問しているので、その財源というのではなくて、品川区商店街連合会から来ているリクエストが２０％程度と言われているのですね。","respondent":"小林商業・ものづくり課長","answer":"でも効果は上げていくという、非常にバランスも考えながらやっていくという中で今回２０％としているところでございまして、そういうところでまた経済状況が変わる部分はありますけれども、関係事業者なり。","id":"exchange-016"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"１点お聞きしたいのが、こうした国・都からの交付金ですけれども、様々使えるメニューがあったりもする中で、今回プレミアム付区内共通商品券事業とキャッシュレス決済ポイント還元を選んだというよりは、これが決まるときというのは、所管課からメニューの候補を出すのですか。","respondent":"小林商業・ものづくり課長","answer":"交付金の考え方という部分です。","id":"exchange-017"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"そうすると、幾つか挙げた中でこれと選ぶのか、それとも今回はメニューがある中でプレミアム付区内共通商品券事業とキャッシュレス決済ポイント還元事業かなとこの２つを挙げたのか、幾つかある中から候補を課として挙げる中でこれに決まったのかというのを伺いたいのと、あと、消費支出が落ち込んでいて消費喚起をというところでは。","respondent":"小林商業・ものづくり課長","answer":"実際に直接の支出、区民の方の収入に何かしらプラスになるという部分につきましては、区のいろいろな政策の中で総合的に対応すべき観点かなと考えておりまして、我々商業・ものづくり課としては、やはり先ほど申し上げたような区民生活と区内経済、具体的に言うと商店街とか店舗。","id":"exchange-018"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"この限られた交付金をどう使おうかというところでは分かるのですけれども、大本を転換させていかないと、先ほども言いましたけれども、消費税減税や賃金アップ、やはりこういうことを抜本的に進めていかないことには、この目的である消費喚起というのはなかなか進まないと思いますので、ここを区としても積極的に国に求めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/238887?Template=document&Id=2978#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":23902,"voices":48}},{"id":"r05-20231227-7","meetingId":"r05-cm12","date":"2023年12月27日","dateIso":"2023-12-27","committee":"厚生委員会","time":"午前１０時０７分～午前１０時５９分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を21件抜き出しています。","topics":[{"id":"topic-01","title":"第１０４号議案、専決処分の承認を求めること","agenda":"第１０４号議案、専決処分の承認を求めること","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"６番の申請方法のところのイということは、今のご説明だと、新たに転入した方がイに当たるということで考えていいのでしょうか。なので、新たに転入されたという方でいいのかということの確認をしたいということが、１点です。相談窓口です。旧リボン（第３庁舎２階）で相談受付を行うということです。併せて庁内の３４２会議室のコールセンターの体制についてもお聞かせいただきたいと思います。","respondent":"豊嶋生活福祉課長","answer":"基本的には３万円の給付金をもらった方は、自動的に７万円を振り込めるはずなので、今回については、特に原則お手続は不要なのですが、こちらから振り込みますという通知だけは行きますので、これは何かと聞かれたときに対応ができるというようなことで、今。","id":"exchange-001"},{"speaker":"鈴木委員","kind":"提案","question":"もう一つ、たしか３万円のときは、住民税均等割は、これから新たに提案のところで均等割まで拡大されるということは、国のほうからも方針が出て、拡大されるということの提案があると思うのですけれども、家計急変世帯というものも、区独自にされたと思います。多分３万円のときは、家計急変世帯も対象にしましたよね。そこのところは検討をされたのか。その点についてお聞かせください。","respondent":"豊嶋生活福祉課長","answer":"よって、今回、家計急変の世帯については、次年度の国の方針を待って対応をしていくということで、今、検討をしています。","id":"exchange-002"},{"speaker":"鈴木委員","kind":"質問","question":"次年度というのは、令和６年度ということですか。家計急変世帯まで３万円のところの対象にしたということは、多分、区独自で一般財源でやったと思うのです。インボイスも１０月からされましたし、そのような点では、今年度、今回の１０万円というところで、家計急変世帯というものも本当に対象にすべきではないかなと思うのです。検討をされた結果、どうだったのか。","respondent":"豊嶋生活福祉課長","answer":"ただ、先ほどの話ではありませんが、修正申告などをした方であれば、そこについては、対象であれば７万円の給付の振込をすることは可能ですので、まずはそちらの給付を迅速に一日も早くできるように進めようということで、現在、準備を進めているです。","id":"exchange-003"},{"speaker":"鈴木委員","kind":"質問・要望","question":"３分の１に減ったとはいえ、３万円のときも区独自にされたわけなので、ぜひそれはやっていただきたい。これからも、もしこういうことがあったとしたら、区としては、一番に区民のそのような切実な実態を直接つかめるところでもありますので、そのような実態もつかんでいただいて、対象を本当に困っている人のところに届くような形で、ぜひご検討をいただけたらということで要望をしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"こんの委員","kind":"質問・要望","question":"スケジュールがもう出ているので、あれなのですが、できる限り、可能な限り早く支給していただきたいという思いで、何点か質問をしたいと思います。私たちのところにも、「いつになったら振り込まれるのでしょうか」というようなお問合せは結構いただいております。専決処分をしてですが、この時期に支給といったところをもう少しご説明いただけますでしょうか。そこら辺のところを教えてください。","respondent":"豊嶋生活福祉課長","answer":"もちろん幾つかの業者に話は聞いていますが、皆さん同じなのです。結局いち早くラインを抑えるために、やはりいち早く我々も動きたかったということで、業者のほうにかなり無理を言いまして、それでも１月末にはなってしまいますが、今、何とかこれで準備を進めているです。","id":"exchange-005"},{"speaker":"こんの委員","kind":"確認","question":"全国でというか、全自治体で、これを進めていくので、東京都内だけでも、この年末年始、そのような印刷業者が大変にされているということは、想像がつくところです。もう１点は、受給承諾書、確認書の通知をされて、支給開始が下旬、末日だと、先ほどご説明がありましたけれども、この返事は返ってきて、初めて支給をするという形になると思うのです。そこら辺のスケジュール感を教えてください。","respondent":"豊嶋生活福祉課長","answer":"申請不要の方にお送りする受給承諾書からご説明いたします。通知自体の発送は、現在、どちらの通知も１月２２日を予定しております。この通知の発送後、およそ２週間の間隔、スパンをもって振り込むことが、国から令和３年の事務連絡で、各自治体に申し伝えがありました。","id":"exchange-006"},{"speaker":"こんの委員","kind":"質問","question":"ということは、受給承諾書のほうは、主に生活保護を受けていらっしゃる方や非課税世帯の方で、前回３万円をもう既に振り込んで、口座が分かっている人、いわゆる振込先が分かっている人たちがほとんどであるといった方たちが、１月末あるいは２月に入ってからになってしまうというような理解でいいのですか。もう一度、そこを教えてください。","respondent":"豊嶋生活福祉課長","answer":"そのとおりです。以前に振り込んだ口座がある方には、実際の着金は２月に入ってからという形になります。","id":"exchange-007"},{"speaker":"こんの委員","kind":"確認","question":"なるほど。そうですか。確認証のほうは転入された方で、行政のほうで非課税世帯だと把握ができない方が申請をして、申請とともに、申請書が届き次第、処理ができれば、どんどん支給ができるということなのですね。そうですか。できる限りそこをすごく早く支給ができたらといったところを思うわけなのですが、これは、再度確認をしますが、受給承諾書の支給を早めるということは、なかなか難しいのですか。","respondent":"豊嶋生活福祉課長","answer":"これも、実は、１月２２日は実現不可能だったのですけれども、何とかお願いをして、ここまで早めてもらったということと、やはり郵便局が年末年始は年賀状の発送の問題で、一度に大量に送れないということもありますので、郵便局とも調整をして、この日以降。","id":"exchange-008"},{"speaker":"こんの委員","kind":"質問・要望","question":"やはりこの年末年始は、非課税世帯の方や生活保護の方はお正月を迎えたいという思いでいらっしゃったお気持ちはよくよく分かるのですが、国が決まってからのスタートで、どこも一斉に始めていることなので、その中できる限りこのようにご努力をしてくださっていることはよく分かりましたので、あとはこのスケジュールどおり、スムーズに進めるようにお願いしたいと思います。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"}]},{"id":"topic-02","title":"第１０３号議案、令和５年度品川区一般会計補正予算（歳出 厚生委員会所管分）","agenda":"第１０３号議案、令和５年度品川区一般会計補正予算（歳出 厚生委員会所管分）","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"福祉タクシー等助成券交付対象者のほうを伺います。これと同じことが、１年前にもされたと思うのですけれども、そのときの対象者は４,５００人だったのですが、今回４,３００人ということは、福祉タクシー券の交付をされている方が２００人減ってしまったということなのでしょうか。そこのところの原因を一つ教えていただきたいことが１点です。６,０００円の考え方についても伺いたいと思います。","respondent":"松山障害者支援課長","answer":"今回につきましては、今回の見込みを出す際に、令和６年の１月１日の発送予定の見込み者として出したものは、現時点での交付対象者としては４,１９１人ということで、タクシー券につきましては３,５００人程度、自動車燃料費券につきましては８００人程度を見込んで。","id":"exchange-010"},{"speaker":"鈴木委員","kind":"質問・要望","question":"４,２６５人が対象で、４,１０９人というのはタクシー券をもらっている人には、そのまま自動的に送るというやり方をされているのかということを伺いたい。今、品川区の福祉タクシー券は年間３,５００円だと思うのですけれども、それは、２３区の中でも、ちょうど真ん中ぐらいだった。その点についてはいかがでしょうかということも、お伺いさせていただきたいと思います。","respondent":"松山障害者支援課長","answer":"実際、昨年度タクシーが値上がったということもあるのですが、やはり、もともと燃料費の高騰が続いているということが、今回の大きなことですので、今後とも物価上昇や燃料費の状況を見ながら、区としては考えていきたいと考えています。","id":"exchange-011"},{"speaker":"鈴木委員","kind":"質問・要望","question":"こういう区内商品券を６,０００円ということは、これはこれで評価するものですけれども、さらに、ぜひタクシー券そのものの引上げをしていただきたいということで、これは要望をさせていただきたいと思います。その点を１点、お伺いしたい。そこのところの差はないのかどうかというところを伺いたいと思います。その点についても確認をさせてください。","respondent":"豊嶋生活福祉課長","answer":"委員おっしゃるように、この３０世帯は、転入をしてきた方が、恐らくこれぐらいではなかろうかということで、まずは想定値として出したものです。","id":"exchange-012"},{"speaker":"鈴木委員","kind":"質問","question":"それであれば、気づかずに申請がされなくて、本来であれば、受け取れる方が受け取れていないということは、それほど考えなくていいのか、そこのところについては、どのような状況になっているのかも伺いたいと思います。","respondent":"豊嶋生活福祉課長","answer":"前回の３万円の給付金もそうですが、今回も、ある一定期間がたって申請がない方には、全てに勧奨通知をお送りします。前回も勧奨通知をお送りしております。なので、今回もそこでまだ申請されていませんということは、こちらからご通知は申し上げる予定です。","id":"exchange-013"},{"speaker":"鈴木委員","kind":"意見","question":"対象者なのに申請がされていないために、受け取れないということがないというところでは、ぜひこれからもくれぐれもよろしくお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-014"},{"speaker":"ひがし委員","kind":"質問","question":"今のことに続いてです。申請をされていない方に通知を送ると言っていたのですけれども、その後の追加の調査はしないのかという話です。視察へ行ったところなどでも、その追跡調査をして、送れない、申請をできない理由というところを把握するということが大切だったというところで、その申請をできなかった理由についての追跡の調査はされているのかを教えてください。","respondent":"豊嶋生活福祉課長","answer":"あくまで勧奨通知をお送りして、ホームページや広報しながわ、掲示板も含めて、先ほどの在宅介護支援センター、各種もろもろのところで、手を差し伸べて、申請をしていただくという方法を取ったのみですので、委員おっしゃるような追跡調査をしたかと言われたら。","id":"exchange-015"},{"speaker":"ひがし委員","kind":"質問・要望","question":"こちらは、要望です。もう１点は、福祉タクシー等助成券交付対象者への物価高騰対策支援について、そもそものところで、ご質問をします。こちらは福祉タクシー利用券または自動車燃料費助成券についての価格上昇分の助成を行うということで、もともと利用をしているタクシー券等ではなく、区内商品券にした意味というところを確認させていただきたいのです。その点についてお聞かせください。","respondent":"松山障害者支援課長","answer":"共通商品券についてのご質問です。前回と今回は同様なのですが、やはり年度内の執行は実際に困難でして、印刷が間に合わないということがありますので、年度内にお届けするためにはということで、共通商品券で相当分として対応をするものです。","id":"exchange-016"},{"speaker":"ひがし委員","kind":"質問","question":"区内共通商品券は、タクシーは一部しか利用できないという話もあったりして、タクシー券として使いたかった方にとっては利用しづらかったりするのか。その分を商品券として別のところでというところで、変えたところに対してお声はあるのかと思うのですけれども、実際の利用されている方々の反応がありましたら、教えてください。","respondent":"松山障害者支援課長","answer":"ただし、やはり区内共通商品券は、一部の福祉タクシーの事業者で、タクシー利用券としての使用を想定しているもので、全てのタクシー事業者に使えるわけではないのですが、ただ物価高騰という趣旨を鑑みますと、例えば家計への負担ということも大きいことですから。","id":"exchange-017"},{"speaker":"ひがし委員","kind":"質問・要望","question":"やはり必要なものと使いやすいものというところを、前回もこうだったからというところではなく、前回やったのであれば、その反応やご意見というところをいただいて、次に生かしていくべきだと思います。次回もし同じようなことになることが想定されるのであれば、ぜひ調査というものをして、利用しやすいものというところを発行していただきたいと思いますので、要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"こんの委員","kind":"質問・要望","question":"もう一つ言えば、今回私ども公明党としても、緊急要望をさせていただいた中に、「国の対象外の方にも、ぜひ支給を」という要望をさせていただいたものが、このように春のときに３万円支給、均等割といったところをしていただいたことは、大変評価をしております。いわゆるこの７万円を支給される方は、先ほどの話とまた確認が同じなのですが、支給までの流れを確認したいのです。その辺を教えてください。","respondent":"豊嶋生活福祉課長","answer":"２週間のお話です。","id":"exchange-019"},{"speaker":"こんの委員","kind":"質問","question":"一定期間というのは、おおむね２週間を待って、その一定の待機期間を待ってということは、受給承諾書を送った後、返事が返ってくるかどうかのおおむね２週間を待って、あともう少し様子を見て、振り込んでいくという理解でいいですか。","respondent":"豊嶋生活福祉課長","answer":"発送してから２週間たったら、もうその段階で支給の準備はできていますので、会計管理室を通して、決済を行っていくという流れです。","id":"exchange-020"},{"speaker":"こんの委員","kind":"確認","question":"すみません、再度確認ですが、そうすると、３月中に支給開始となっているものは、受給承諾書の方に限っては、３月を待たずして……。２月の下旬に送って、２週間を待つから、結局３月ということですね。分かりました。いずれにしても、この２週間を待って、その方たちから何らかのアクションがなくても、振込を開始するという理解でいいということですね。","respondent":"豊嶋生活福祉課長","answer":"原則、申請不要ですので、申請漏れがないというやり方で、３万円のときから始めているものです。","id":"exchange-021"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/424146?Template=document&Id=3680#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":16112,"voices":75}},{"id":"r05-20231227-9","meetingId":"r05-cm12","date":"2023年12月27日","dateIso":"2023-12-27","committee":"文教委員会","time":"午前１０時０７分～午前１０時４７分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を15件抜き出しています。","topics":[{"id":"topic-01","title":"第１０３号議案 令和５年度品川区一般会計補正予算（歳出 文教委員会所管分）","agenda":"第１０３号議案 令和５年度品川区一般会計補正予算（歳出 文教委員会所管分）","exchanges":[{"speaker":"安藤委員","kind":"確認","question":"この２つの給付金を含む、今回、文教委員会所管分の補正予算３つの事業のうち、区の一般財源でお金を受領というのはあるのでしょうか。それぞれ財源を伺いたいと思います。","respondent":"飛田子育て応援課長","answer":"区独自のひとり親世帯の臨時特別給付金につきましては、委員がおっしゃいます地方創生臨時交付金も使うということで、予定では１億１,４００万円ほど、地方創生の臨時交付金から使います。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"給付金のほうでまず伺いたいのですが、子育て世帯生活支援特別給付金ということです。これ、コールセンターとあるのですけれども、開設時期は何日間ぐらいでしょうか。それと、ひとり親世帯臨時特別給付金のほうですが、資料の裏面にスケジュールで「要申請者受付開始」とありますけれども、この要申請者とはどういう方なのか伺いたいと思います。","respondent":"飛田子育て応援課長","answer":"コールセンターのほうですが、委員おっしゃるとおり、現在も国の給付金の関係でコールセンターをやっておりますが、そのまま引き続きコールセンターを設置しまして、今のところ、ほかの国の給付がなければ、５月末までというふうに考えているところです。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"申請が必要な方については、自分が申請が必要で、対象になっているかは、なかなか分かりづらいと思うのですけれども、やはり漏れがないように、ホームページと広報紙のみでは、少し周知としては不十分だと思いますので、周知を徹底していただきたいと思うのですけれども、いかがでしょうかということです。伺います。","respondent":"飛田子育て応援課長","answer":"ひとり親世帯のほうでの周知ですが、一応、住基台帳で対象世帯の方の情報を得まして、対象者へは案内を全員に送る予定です。なおかつ、案内漏れということがないように、まずは対象者全員に送付すると考えております。もう１つ、フードパントリーのほうです。","id":"exchange-003"},{"speaker":"安藤委員","kind":"質問・要望","question":"私たちとしては、要望してきたのが、例えば、区内全ての児童・生徒の学校給食の無償化へ、国立私立等に通う子どもへの対象拡大ですとか、あるいは、区独自の大学生等への給付型奨学金を実施するですとか、これは所管が違うのですけれども、１８歳までの子どもの国保料を無料化するですとか、こういったことを今こそ実施に踏み出すよう求めたいと思うのですが、ここでは１点だけ。","respondent":"飛田子育て応援課長","answer":"今、国、各自治体でも様々な支援をしているところですが、今また東京都のほうにも、都立大学の無償化とか、そういうことも言って、大学に対しての奨学制度、大きく今、変化があるところですので、私としては、国また都の状況を見ながら、状況は注視していきたいと考えております。","id":"exchange-004"},{"speaker":"安藤委員","kind":"質問・要望","question":"都立大はごく一部ですし、変化を見ているのではなく、やはり区内からも、区民の大学生から、何度か文教委員会にも請願・陳情など上がっておりました。そういった声を受け止めて、さらなる支援に踏み出していただきたいと、給付型の大学生への奨学金に踏み出していただきたいなと改めて要望させていただいて終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"二、三件だったら、所管のところで対応できるのではないのかなと思ってしまうのですけれども、その辺のコールセンターの在り方について、どのように考えているのか教えていただきたいのと、このシステム作業支援委託というのがどのような事業なのかお知らせいただきたいと思います。以上、３つ教えてください。","respondent":"飛田子育て応援課長","answer":"ですので、それを１つ１つ職員が対応するというのはとても難しいことかなというふうには考えておりますので、やはりコールセンターの設置は必要かと考えております。そしてもう１つ、システム作業支援委託費です。","id":"exchange-006"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"もちろんやっていただいている方たちへの支援は、引き続き継続的にやっていただきたいですけれども、もうそろそろ子ども食堂をやらなくていい社会に向けた子育て支援を真剣に考えていただきたいと思うので、今回のこの件については、もう全然やっていただいてありがたいなと思うのですけれども、そういう根底の部分のところの問題解決に向けて真剣に考えていただきたいなと思うので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"高橋（し）委員","kind":"質問","question":"そこで、先ほども少し石田しんご委員から質問があったのですけれども、子ども食堂の今後の方向性というようなお話をしていただいたのですけれども、先ほど、フードパントリーの補助金が既にもう足りないということが１つあって、だから、ここで支給する。逆に言うと、フードパントリーだから、食品以外は使えないという仕組みなのかというところをお尋ねします。","respondent":"飛田子育て応援課長","answer":"今回、この商品券、きちんとチェックとかがどうなっているのかということですが、今回、実際に商品券の購入費としましては４３２万円を予定しておりまして、そのほかに事務費ということで４８万円上げします。","id":"exchange-008"},{"speaker":"高橋（し）委員","kind":"意見","question":"それぞれ区のほうでも、今までの補助プラスで、ガバメントクラウドファンディングができたらしていこうというような意向を持っているということが分かりました。やはり現状ではなかなか厳しい。今の最後の商品券の使い道については、いろいろ制限がありつつも、柔軟に対応はできるという表現でよろしいのかなと思いますので、子ども食堂のほうには、そういうふうに伝えていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-009"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"私からは、私、生活保護の仕組みとかに詳しくないのですけれども、この子育て世帯生活支援特別給付金が、所得に計算されるのかどうか、その辺について伺いたいと思います。すみません、その点を１点教えていただきたいと思います。それをフードパントリーに特化したような形に見えるのですけれども、その辺についてはいかがなのでしょうか。","respondent":"飛田子育て応援課長","answer":"こちらですが、基本的には、やはりフードパントリーの利用者は全然減っていないというところもありますので、そこのところで、基本的にはフードパントリーに使っていただくということで、ただ、やはり各子ども食堂のやり方がありますので。","id":"exchange-010"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"子育て世帯生活支援特別給付金のほうは承知いたしました。特にこれによって生活保護の制度上、不利益な扱いにはならないという確認でよろしいですね。フードパントリーのほうです。その点について、もし何か見解があったら伺いたいと思います。","respondent":"飛田子育て応援課長","answer":"今回は、あくまでもメインはフードパントリーというふうに考えております。ただ、どうしてもやはり運営上、必要なものはあると思いますので、それについては、まず相談していただいて、それで判断することは考えています。","id":"exchange-011"},{"speaker":"安藤委員","kind":"確認","question":"すみません、確認なのですが、１番の、基本的にこれ、国の給付金ではないですか。確認だけさせてください。","respondent":"飛田子育て応援課長","answer":"基本的に国の制度なので、収入認定はないというふうに言われています。","id":"exchange-012"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"子育て世帯生活支援特別給付金と、ひとり親世帯臨時特別給付金については、どちらも公明党が１２月５日に区長に緊急要望した内容が早急に反映された内容であり、非常に歓迎したい内容だと感じています。給付については、住基台帳に基づいて行われると先ほどもありましたが、今後のためにも、要申請者の確実な把握と周知の徹底を重ねて要望したいと思います。公明党は賛成です。公明党は賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"安藤委員","kind":"質問・要望","question":"賛成です。深刻な物価高騰や子育て世帯の生活状況等に照らして、さらに一歩踏み込んで実施していただきたいという点はあるものの、今回の内容はどれも大切な事業でありますので、賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"両方とも賛成です。１つだけ。臨時交付金が来て、こういう形でやっていただいて、大変すばらしいし、区の独自財源も使ってプラスしているのですけれども、臨時交付金とかがなくなった後に、その後、区としてどういうふうに子育てを支援していくかというところは、しっかりと検討していただきたいというふうに思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/246913?Template=document&Id=5118#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":13033,"voices":45}},{"id":"r05-20231227-5","meetingId":"r05-cm12","date":"2023年12月27日","dateIso":"2023-12-27","committee":"総務委員会","time":"午前１１時３０分～午前１１時５９分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を9件抜き出しています。","topics":[{"id":"topic-01","title":"第１０３号議案、令和５年度品川区一般会計補正予算","agenda":"第１０３号議案、令和５年度品川区一般会計補正予算","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"１点、ひとり親世帯臨時特別給付事業についてですけれども、まず、補正全体としては、物価高騰が続く中、区民の暮らしを応援するものだと考えています。ただ、暮らしの実態は一層厳しいし、先行きの見通しも立ちませんから、適時こういう補正を組んで引き続き暮らしを応援してほしいし、来年度の予算についても、こういう姿勢で取り組んでいただきたいと、これは要望しておきたいと思います。","respondent":"遠藤財政課長","answer":"所得制限の考え方ですが、こちらは、今回、国の事業の中で所得の制限を設けて実施されているところです。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問","question":"だけれども、ここが苦しいから所得制限をなくすという考え方を今後も続けていくのか、拡大していくのか、改めて伺いたいと思います。私は、いずれにしても、生活が苦しい、そういう実態があるところは、十分に支援を行き届かせる必要があると思うし、子育て支援だったり、社会保障だったり、教育だったり、対象は全ての子どもたちやお年寄りを対象にすべきだと思いますけれども、最後にいかがでしょうか。","respondent":"遠藤財政課長","answer":"ここだったらいいとか、ここだったら駄目だとかという部分で、本当に困っている、困っていないという点は確かにあるだろうとは考えるところですけれども、ただ、今回については、ひとり親世帯の所得については撤廃した。","id":"exchange-002"},{"speaker":"松本委員","kind":"質問・要望","question":"総務委員会なので、本当に簡単に伺います。お願いします。","respondent":"遠藤財政課長","answer":"キャッシュレス決済ポイント還元事業ですけれども、こちらはどうしても事業者との調整が必要になりまして、おおむね６か月から７か月ぐらい実施にかかるというところで、４月、当初予算でやると遅くなってしまうため、今回、債務負担行為という形でやらせていただくところです。","id":"exchange-003"},{"speaker":"須貝委員","kind":"質問","question":"先ほど、中塚委員からもありましたけれども、物価高騰の影響は、様々な所得、生活している方たちに影響を与えていると思います。こういうこともやっている。それともう１点、フードパントリーというものが今回出ていますけれども、子ども未来応援事業、これはフードバンクとどのような違いがあるのですか。ここで増えていくわけですよね。その説明だけ分かる範囲で教えてください。","respondent":"遠藤財政課長","answer":"そちらにつきましては、以前、しながわ活力応援給付金などもやらせていただいておりますので、今後ですけれども、いろいろな社会事情等もあろうかと思いますので、そこら辺につきましては、臨機応変に対応させていただければと考えています。","id":"exchange-004"},{"speaker":"須貝委員","kind":"質問・要望","question":"フードパントリーのほうは、そんなに変わらないのであれば、わざわざこういうふうにつくる必要が、子育て応援ということですから、どうなのかなと少し疑問に思います。これ、皆さんが生活をしているときに、皆さんの生活を支えているのは私はスーパーだと思うのです。そういうことを考えると、やはり共通商品券の在り方も、今後、何か考えていただきたい。意見だけ言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"なぜ遅いのですかということをまず聞きたい。それで無償化になる。そういう話にきちんと我々が対応できるようにしないと、何でもかんでも物価高騰対策だ、低所得者対策だ、子育て支援策だと言って、何でもやるのは、少し違うような気がしてならなくて、特にここで臨時会まで開いて補正予算をやるわけだから、そこら辺をもう少し丁寧に説明してほしいと思うのだけれども、そこら辺の考え方だけ教えてほしい。","respondent":"遠藤財政課長","answer":"様々な意見が当然あろうかと考えていますので、本当は全てかなえられればいいのかなというふうに思っているところですけれども、優先順位をどうしてそういうふうにつけたのかというところは、なかなかすぐにパッとご納得いただける説明は。","id":"exchange-006"},{"speaker":"塚本副委員長","kind":"確認","question":"確認ですけれども、例えば、子育て世帯生活支援特別給付とか、住民税均等割のみ世帯、これは、今は財調を取り崩して歳入に当てていますけれども、いずれは国のほうから財源として当て込まれる、そういうふうに認識しているのですが、そういったときに、これは３月３１日の年度内に使い切らないと、給付し切らないといけないというような縛りとかがあるということで。","respondent":"遠藤財政課長","answer":"こちら２つの事業については、一応、年度内を目標にしているところではありますが、これはシステム改修なども出てくる形なので、国からは、一定、繰り越しても大丈夫というような話もいただいているところですので、できるだけ年度内にやらせていただいて、万が一難しい場合には。","id":"exchange-007"},{"speaker":"須貝委員","kind":"質問・要望","question":"１点だけ。別の方もお聞きしていたのですが、プレミアム付区内共通商品券ですが、これを区外の方も購入できるという話を聞いたのです。でも、基本的に区の予算を充当するということならば、残る、残らないはあるかもしれないですけれども、私はやはり区民に何とかして買っていただくような仕組みにするよう、区のほうでもしっかり取り組んでいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"須貝委員","kind":"質問","question":"だから、意見だけ。質問ではなくて、それだけは今指摘しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/166654?Template=document&Id=2286#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":10574,"voices":40}},{"id":"r05-20231227-10","meetingId":"r05-cm12","date":"2023年12月27日","dateIso":"2023-12-27","committee":"議会運営委員会","time":"午後 ２時３０分～午後 ２時３２分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/105128?Template=document&Id=5532#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":1100,"voices":8}}]);
